INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259412876', 'Jibbitz™ Lego Gaming I Única', 'Dê vida a novas construções em seus sapatos e acessórios com nossa coleção criativa de Jibbitz™ LEGO®. Comece com esta minifigura LEGO Gamer super legal. Os Jibbitz™ têm escala de 150% das peças LEGO tradicionais. Não é um brinquedo. Não recomendado para menores de 3 anos. As imagens do produto podem sofrer pequena alteração de cor dependendo do monitor e da resolução em que elas sejam visualizadas.', 34.99, 34.99, NULL, 'Fashion Accessories > Additional Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-820m7-mnel6dw9n7r7b4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757311881%2F58259412876', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15380972680', 'Sandália crocs baya black', 'Aposte no conforto da Crocs com o Crocs Baya Clog. Uma versão do nosso clássico Clog, ele apresenta a estrutura leve e durável que você tanto adora, com ventilação avançada para respirabilidade e para ajudar a drenar água e resíduos. • Material Croslite™ totalmente moldado para amortecimento máximo e leveza • Impermeável e flutuante; pesa apenas 30 gramas • A ventilação avançada na área dos dedos mantém os pés frescos e ajuda a drenar água e resíduos • Fácil de limpar e rápido de secar • Tiras giratórias no calcanhar para um ajuste mais seguro • Personalizável com Jibbitz™ • Iconic Crocs Comfort™: Leve. Flexível. Conforto de 360 graus. As imagens do produto podem sofrer pequena alteração de cor dependendo do monitor e da resolução em que elas sejam visualizadas.', 299.0, 284.05, NULL, 'Men Shoes > Sandals & Flip Flops > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-824ia-mdvv0ssbk7wlee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757311881%2F15380972680', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
