INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9444461422', 'Borracha Porta Malas Tipo Original Gol G5 Todos', 'Detalhes do Produto: Borracha Porta Malas Tipo Original Gol G5 Todos Os veículos possuem componentes de borracha nas portas, vidros e no teto que tem por função evitar a infiltração de água e também no caso das Canaletas e Pestanas formam o trilho do vidro. A avaliação periódica desses componentes é recomendada, para que eventuais infiltrações não comprometam a lataria, provocando sua corrosão e molhando o interior do veiculo. Compatível com veículos: Gol G5 Todos Especificação Técnica: Alta resistência e durabilidade Qualidade padrão original Borracha casco de cobra Impede a entrada de pó e outros materiais Impede a infiltração de água Reduz o nivel de ruídos externos Evita correntes de ar, perda de climatização Na cor preta Tamanho: 4,20m Importante: Garantia da borracha: 02 anos contra defeito de fabricação Valor unitário Imagens meramentes ilustrativas Recomendamos que a instalação seja feita sempre por um profissional A Nolascoshopnão se responsabiliza por mal instalação ou uso indevido do produto Itens Inclusos: 01 Borracha para o porta malas (02 anos de garantia)', 79.9, 79.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/5e37826b5af827d4f058c19706d732eb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F9444461422', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599881682', 'Borracha Vedação Da Porta Motorista Encaixe Corolla 2014 á 2019 Envio Imediato', 'A borracha de vedação é responsável por contornar toda a porta, sendo fixada diretamente na carroceria. Sua função é impedir a entrada de água, poeira e vento, além de reduzir ruídos internos e proporcionar um fechamento mais suave e silencioso da porta. A verificação e substituição periódica dessa guarnição é fundamental, pois infiltrações podem causar corrosão na lataria e danificar o interior do veículo. Aplicação Compatível com: Toyota Corolla – 2014, 2015, 2016, 2017, 2018 e 2019 Conteúdo da Embalagem: 01 Borracha da Porta Dianteira – Lado Motorista Características do Produto: Borracha na cor preta Encaixe perfeito, seguindo o padrão original Acabamento com aba e duplo bulbo, garantindo excelente vedação Fixação por encaixe, sem necessidade de cola Produto novo, resistente e desenvolvido para reposição da peça original Recomendação de Instalação Para garantir o encaixe correto e o melhor desempenho da vedação, recomendamos que a instalação seja realizada por um profissional qualificado.', 82.9, 82.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Glass', 'https://cf.shopee.com.br/file/br-11134275-81z1k-meg1v8bn5z4275', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177934907%2F21599881682', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
