INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11232927165', 'Sobrelençol Queen Percal 180 Fios Buddemeyer Basic Percalle 100% Algodão Penteado Branco', 'CARACTERÍSTICA DO PRODUTO: Atemporal, a coleção Basic Percalle prima pelo conforto e modernidade. Possui refinado acabamento que ressalta o cuidado e a versatilidade que só a Buddemeyer proporcionaTecido 100% algodão Fio Penteado, percal 180 fios; toque macio e acabamento de excelente qualidadeQualidade e design Buddemeyer??? CONTEÚDO DA EMBALAGEM: Contém: 1 sobrelençol queen 240x240cm COMPOSIÇÃO: Tecido percal 180 fios - 100% algodão, Fio Penteado TIPO DE MATERIAL: Tecido 100% algodão, fio penteado COR: Branco EAN: 7909301399963 REFERÊNCIA: F00193330000011103 DESCRIÇÃO: Sobrelençol solteiro Basic Percalle. Em tecido 100% algodão Fio Penteado, percal 180 fios; toque macio e acabamento de excelente qualidade. Atemporal, a coleção Basic Percalle prima pelo conforto e modernidade. Possui refinado acabamento que ressalta o cuidado e a versatilidade que só a Buddemeyer proporciona. A Buddemeyer é referência em qualidade e estilo. INSTRUÇÕES DE CUIDADO: Lavar antes de usar. Cores escuras devem ser lavadas separadas das cores claras. Lavar em água fria ou em temperatura de até 60°C. O melhor sabão para manter as características do produto é o de coco ou neutro. Não colocar sabão diretamente no produto. Evite alvejantes e quaisquer produtos a base de cloro, eles atacam o corante dos tecidos. Não exagere no uso de sabão em pó e use pouco amaciante. Permite secadora em temperatura baixa. Temperatura máxima da base do ferro 110°C. Não usar ferro a vapor. Não lavar a seco.', 220.95, 178.84, NULL, 'Home & Living > Bedding > Bedsheets, Pillowcases & Bolster Cases', 'https://cf.shopee.com.br/file/07793791e3502a2af4a478055a16c662', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fsh