INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47259649475', 'Glucose de Milho Xarope 500g Arcolor', 'O Xarope de Glucose de Milho 500g Arcolor é um ingrediente versátil essencial na confeitaria, garantindo textura, brilho e acabamento profissional em receitas como brigadeiros, caramelos e bolos. Ajuda a manter a maciez, evita a cristalização do açúcar e melhora a consistência das preparações. Não contém glúten nem alergênicos, sendo seguro para diversos usos. Vem em embalagem prática de 500g, com ótimo rendimento e fácil armazenamento, ideal para produções caseiras e profissionais. Indicação de uso: Ideal para bolos, caramelos, sorvetes, doces em geral e produções de confeitaria artesanal Características: Xarope de glucose de milho, alta viscosidade, promove maciez e cristalinidade, retarda cristalização do açúcar, não contém glúten Ingredientes: Xarope de glucose de milho. NÃO CONTÉM GLÚTEN. NÃO CONTÉM ALERGÊNICOS. CONTÉM DERIVADOS DE MILHO TRANSGÊNICO. INFORMAÇÃO NUTRICIONAL (Porção de 10g - 1 colher de sopa) Valor Energético: 8kcal Carboidratos: 8g Açúcares Totais: 8g Proteínas: 0g Gorduras Totais: 0g Gorduras Saturadas: 0g Gorduras Trans: 0g Fibras Alimentares: 0g Sódio: 5,5mg', 30.92, 30.92, NULL, 'Food & Beverages > Cooking Essentials > Others', 'https://cf.shopee.com.br/file/sg-11134201-820oe-mnll3rjn9q88ce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F47259649475', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
