INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198860320', 'KIT ELSEVE SH + COND SUPER ALINHADOR LISO DOS SONHOS LORÉAL', '1 SHAMPOO ELSEVE LISO DOS SONHOS SUPER ALINHADOR 200ML 1 CONDICIONADOR ELSEVE LISO DOS SONHOS 200ML O Shampoo Super Alinhador limpa e fortalece a fibra preparando os fios para um liso de longa duração e com frizz controlado. O Condicionador Efeito Liquid Hair sela e restaura a superfície da fibra para um liso com efeito liquid hair: desmaiado, com movimento super fluido e brilho intenso. Enriquecido com AHA + QUERATINA VEGETAL, Elseve Liso dos sonhos é o nosso 1ª tratamento em casa que transforma os fios para 1 semana de cabelos lisos e à prova de umidade. Resultados que resistem até 5 lavagens. - 2X mais liso, 2x menos frizz - 15X mais sedoso - 3X mais fácil de desembaraçar Modo de Uso Aplique o shampoo nos cabelos molhados, massageie e enxágue. Repita se necessário. Após o uso do shampoo, aplique o condicionador no comprimento até as pontas, deixe agir e enxágue.', 49.99, 44.0, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdp1xuons6nt55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F22198860320', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10426648026', 'Modulo Taramps Ds1200x4 4 Canais 2 Ohms 1200w Rms Amplificador Automotivo Potencia Digital Ds1200', 'O amplificador DS 1200×4 é desenvolvido com a mais alta tecnologia e desempenho para sistemas de som automotivo. É multicanal, com potência máxima de 1200Watts RMS com impedância de 2 OHMS, e 4 canais de 300W RMS. O DS 1200×4 é FULL RANGE tocando todas as frequências na medida certa para você. CLASSE DE OPERAÇÃO Classe D NÚMERO DE CANAIS 04 POTÊNCIA MÁXIMA @ 12,6 VDC - 2 OHMS: 1200W RMS (4 x 300W RMS) @ 12,6 VDC - 4 OHMS: 768W RMS (4 x 192W RMS) SENSIBILIDADE DE ENTRADA 250mV RELAÇÃO DE SINAL/RUÍDO >80dB RESPOSTA DE FREQUÊNCIA 9Hz ~ 27KHz(-3dB) CROSSOVER HIGH PASS (HPF) 90Hz (-12dB/8ª) Fixo CROSSOVER LOW PASS (LPF) 90Hz (-12dB/8ª) Fixo IMPEDÂNCIA DE ENTRADA 18K OHMS IMPEDÂNCIA DE SAÍDA 2 OHMS SISTEMA DE PROTEÇÃO Sobrecarga na Saída TENSÃO DE ALIMENTAÇÃO MÍNIMA 9VDC TENSÃO DE ALIMENTAÇÃO MÁXIMA 16VDC CONSUMO EM REPOUSO 1,8A CONSUMO MÁXIMO MUSICAL @12,6VDC 67,5A CONSUMO MÁXIMO EM SINAL SENOIDAL 135A DIMENSÕES (LXAXP) 182 x 52 x 281mm PESO 2,1Kg', 1000.0, 887.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/bd31a68ef463677590091a01776fdcbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411081274%2F10426648026', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
