INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093277232', 'Bóia Tubular Fiat Uno 1989 a 1989 - 1350618 - T060001', 'Bóia Tubular Fiat Uno 1989 a 1989 1350618 T060001 MOTOR 1.5 8v - Combustível: Gasolina (60mm) Com RETORNO A boia tubular de combustível funciona em conjunto com indicador, normalmente localizado no painel. A boia no interior do tanque realiza a medição do nível de combustível de forma eletromagnética e transforma essa medição em um sinal que é enviado ao indicador, interpretando o sinal, o transformando na indicação através do ponteiro no mostrador, auxiliando no monitoramento e controle da quantidade de combustível.', 164.79, 164.79, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbne-ln4y5qpmo9pxce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22093277232', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
