INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49408035441', 'Bola de Vôlei de Quadra Mikasa V200W Oficial', 'Bola de Vôlei Profissional Mikasa V200W Oficial FIVB – Tamanho 5 Certificada pela FIVB (Federação Internacional de Voleibol), a bola de vôlei Mikasa V200W é utilizada nas principais competições do mundo, incluindo campeonatos mundiais e Jogos Olímpicos. Desenvolvida para alto desempenho, é a escolha ideal para atletas profissionais e também para quem busca qualidade superior no jogo. Produzida com tecnologia avançada em microfibra, a V200W oferece excelente controle, estabilidade e precisão. Seu design inovador com 18 painéis melhora a visibilidade e a aerodinâmica durante as jogadas. A tecnologia Double Dimple reduz a resistência do ar e melhora a precisão dos movimentos, enquanto a tecnologia Nano Balloon Silica evita que a bola fique escorregadia com o suor, garantindo desempenho consistente. Já o revestimento Super Composite proporciona maior aderência e melhor sensação de toque. Características do produto Modelo: Mikasa V200W Bola oficial aprovada pela FIVB Indicada para uso profissional e competições Tamanho: 5 Construção com 18 painéis Material em microfibra de alta qualidade Tecnologia Double Dimple (melhor aerodinâmica e precisão) Tecnologia Nano Balloon Silica (menos escorregadia) Revestimento Super Composite (melhor grip e controle) Circunferência: 65 a 67 cm Peso: 260 a 280 g Garantia contra defeito de fabricação Indicação de uso Competições profissionais Treinos de alto rendimento Atletas profissionais e amadores exigentes A compra na Sloth Você está adquirindo um produto original, com qualidade e durabilidade garantidas. Todos os produtos são comercializados com autorização da marca e acompanhados de nota fiscal. Seu pedido será processado, separado e enviado em até 24 horas após a aprovação do pagamento. Caso ocorra qualquer imprevisto, você será informado imediatamente. Em casos de defeito de fabricação, oferecemos 30 dias para devolução, com reembolso após análise e confirmação do problema. Os custos de envio em casos de devolução por defeito são por conta da Sloth. 7 dias para devolução por desistência após o recebimento do produto.', 999.9, 749.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Volleyball', 'https://cf.shopee.com.br/file/sg-11134201-82618-mmhi7i5dqdj5b0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322737721%2F49408035441', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16971901431', 'Vinho Esporão Pe Tinto 750ml', 'Pé Tinto é o vinho de entrada da renomada vinícola alentejana Herdade do Esporão. Jovem, sem passagem por barrica, é um vinho tinto frutado, macio e equilibrado, ou seja, fácil-fácil de gostar. Frutas pretas (cereja e ameixa) destacam-se no nariz e há uma gostosa nuance de ervas. Taninos macios e uma boa acidez tornam o Pé Tinto um bom companheiro à mesa. Ele é produzido a partir de um corte de vinhos de Trincadeira e Castelão, duas típicas castas portuguesas que se dão muito bem no quente Alentejo. Se você busca um vinho bom e barato, o Pé Tinto é um forte candidato! Não é exagero dizer que a Herdade do Esporão é a vinícola que colocou a região do Alentejo no mapa-múndi do vinho moderno. Localizada na pequena cidade de Reguengos de Monsaraz, possui nada menos que 700 hectares de vinhas, olivais e outras culturas. Para as proporções portuguesas, isso significa um mar de vinhedos, com uma coleção de 40 castas! A Herdade do Esporão destaca-se também pela estrutura arrojada de vinificação. À frente da produção de seus vinhos, de várias gamas e categorias, está o enólogo australiano David Baverstock, que figura como uma celebridade do vinho português. A origem da Herdade do Esporão é antiga – a propriedade existe desde a Idade Média! Mas somente nas últimas décadas do século XX é que se voltou, seriamente, para a produção de vinhos, ao ser adquirida, em 1973, por José Roquette. Em 1985, foi realizada a primeira colheita que deu origem à marca Esporão. De lá pra cá, as coisas só melhoraram. Atualmente, os vinhos tintos, brancos e rosés da Herdade do Esporão são cobiçados em nada menos que 50 países do mundo! Vale mencionar que a propriedade abriga verdadeiros monumentos: a Torre do Esporão, o Arco do Esporão e a Ermida de Nossa Senhora dos Remédios. Ou seja, é um tesouro de vinhos e história!', 49.9, 49.9, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/8bb5e6d0bd5115acc914d4873b6fb863', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F16971901431', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
