INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394510599', 'Touca de Natação Poliamida - Azul', 'A Touca de Natação Poliamida da Mor foi projetada para oferecer o melhor para quem gosta de praticar natação. Ergonômica, adapta-se perfeitamente ao formato da cabeça sem apertar ou puxar os cabelos. Possui dois recortes centrais que proporcionam maior conforto, deslizando facilmente ao ser colocada ou retirada. Resistente ao cloro é peça fundamental para nadadores profissionais ou amadores.', 16.0, 16.0, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Training Equipments', 'https://cf.shopee.com.br/file/sg-11134201-824ja-mfbbocm3egwe55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F23394510599', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694143076', '50x Terminais de Conduite de Marcha 4mm para Transmissão de Bicicleta', 'Conjunto de Terminais para Conduite de Marcha, marca Paco, utilizado na ponta dos conduites de transmissão de Bicicleta. Possui 4mm de diametro cada. Kit com 50 unidades. Fabricado em plastico para maior durabilidade. Pode ser usado para acabamento em conduites 4mm para câmbio da bicicleta. -Leve, forte resistência à pressão e durável. -Borda lisa, não machucará a caixa do cabo. -Mais propício à proteção do tubo de linha. -Não é fácil cair. -Aplicável: conduite de 4mm -Material: plástico -Tamanho: (extremidade do cabo de mudança) 4mm x 18mm', 11.39, 11.39, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rauu-maus56qu89sg9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F22694143076', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20998271457', 'Eixo Traseiro Completo Marcha 175mm Aço Caixa Colares P/Bike', 'Eixo Traseiro Completo Marcha 3/8 175mm Aço Caixa Colares Bike Este eixo traseiro completo é perfeito para quem precisa substituir o eixo da bicicleta aro 26. O eixo é feito de aço resistente 3/8 x 175 mm e vem com caixa, colar e espaçadores para garantir uma instalação segura e precisa. Especificações: - Marca: Paco - Material: Aço - Modelo: Traseiro Com Bacias e Esferas - Medida: 3/8 - Tamanho: Total - 175 mm; Entre carretel - 50 mm - Cor: Preto - Peso aproximado: 180g PRODUTO DISPONÍVEL A PRONTA ENTREGA, ENVIO IMEDIATO!!! QUALQUER DÚVIDA ESTAMOS A DISPOSIÇÃO. EQUIPE WJ SHOP!!!', 14.53, 14.53, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rdyh-mcw5d6inhequce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F20998271457', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51751908094', 'Kit 4 Painéis Plafon Quadrado Embutir 12W Luz Branca 6500K Luminária de Gesso Forro 127v 220v Avant', 'Você está comprando: 04 Painéis Pop Embutir 04 Caixas de papelão Painel LED Pop Embutir Quadrado 12W 6500K – Avant O Painel LED Pop Embutir Quadrado Avant é a solução ideal para quem busca iluminação moderna, uniforme e com excelente eficiência energética. Com design slim e discreto integra-se perfeitamente a ambientes residenciais, comerciais e corporativos, valorizando a decoração e proporcionando luz branca fria de alta qualidade. Com fluxo luminoso constante, mesmo em variações de tensão, oferece iluminação estável e confortável ao longo de toda sua vida útil — que chega a 25.000 horas. Além disso, seu baixo consumo de energia reduz custos e contribui para um uso mais sustentável. Características e Benefícios Iluminação homogênea com design leve e moderno Instalação embutida para acabamento limpo e sofisticado Baixo consumo de energia com alta eficiência luminosa Luz branca fria (6500K) ideal para foco, produtividade e ambientes bem iluminados Informações Técnicas: Código: 903009579 Modelo: Embutir Marca: Avant Tensão nominal: 100V a 240V. Emissão de Luz: Branco Frio Temperatura da Cor: 6500K Potência: 12W Fluxo Luminoso: 720 Lumens Eficiência Luminosa: 70 Lumens Watts Temperatura ambiente: -5°C a 40°C. Vida útil Aproximada: 25 Mil Horas Dimerizável: Não Índice de Proteção: IP20 Dimensões Aproximadas: 160x160mm Material: Plástico Garantia: 1 Ano ATENÇÃO: Certifique-se de que o transformador eletrônico não fique em contato direto com a luminária, pois a base funciona como dissipador de calor. O contato pode causar danos e interferências no funcionamento do transformador.', 43.99, 39.6, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-8225p-mhcaorq102z31b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F951290141%2F51751908094', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497923983', 'Brinquedo Infantil Mini Jogo Basquete de Mesa com 6 Bolinhas Zippy Toys - 8343', 'Brinquedo Infantil Mini Jogo de Basquete Com Lançador Brinquedo divertido para pais e filhos e amigos se divertirem. Essa incrível quadra de basquete possui um lançador para arremesso das bolinhas ao cesto. Jogue em grupo e divirta-se fazendo muitas cestas. Esse brinquedo possui o design idêntico a uma quadra de verdade, cesta com tabela e 6 mini bolinhas de basquete. Pressione a alça para colocar a bolinha, ajuste a bolinha no lançador e depois é só pressionar e soltar. - Recomendado para Crianças a partir de 5 anos Características: - Marca: ZIPPY TOYS - Modelo: 8343 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 1x Cesta com tabela e 6 mini bolinhas de basquete mini basquete de mesa - brinquedo infantil - jogo de basquete - presente - coordenação motora - esporte', 26.7, 24.03, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/sg-11134201-7rdwg-m1d5uvjqs5ru64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F22497923983', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25096348134', 'Kit Pegadores Brinox – Massa + Salada – Aço Inox', 'Facilite o preparo e o serviço das suas refeições com este kit prático e resistente. Produzidos 100% em aço inox, os pegadores para massa e para salada unem durabilidade, higiene e sofisticação, ideais para uso diário e também para ocasiões especiais. O Pegador para Massa possui design funcional que garante firmeza ao servir espaguetes, talharins e outros tipos de massa, sem esforço. Já o Pegador para Salada é perfeito para folhas, legumes e acompanhamentos, mantendo a apresentação dos alimentos. Ambos podem ser lavados na máquina de lavar louças, mantendo brilho e qualidade por muito mais tempo. Diferenciais: - Produzidos em aço inox de alta qualidade - Resistentes, higiênicos e fáceis de limpar - Design funcional para servir com praticidade - Podem ir à máquina de lavar louças Especificações: - Material: Aço Inox - Modelos: 1689/000 (Massa) | 1688/000 (Salada) - Cor: Prata Conteúdo da Embalagem: - 01x Pegador para Massa Brinox - 01x Pegador para Salada Brinox', 33.72, 30.35, NULL, 'Home & Living > Kitchenware > Spatulas & Cooking Tweezers', 'https://cf.shopee.com.br/file/sg-11134201-7rdvm-mdkm4hn2cklx89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F25096348134', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
