INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397561931', 'Fire Black 60 Caps Max Titanium', '🔥 Fire Black Max Titanium 60 Cápsulas: O Que É? O Fire Black Max Titanium é um suplemento alimentar de cafeína em cápsulas, que traz em sua fórmula 400mg de cafeína pura por porção (2 cápsulas). Ele é indicado para auxiliar no aumento do estado de alerta, na melhora da performance durante os treinos e na aceleração do metabolismo e da queima calórica.', 48.61, 43.21, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lw63k9eqe8qdb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965164614%2F22397561931', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
