INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251856803', 'Fixador Auto-adesivo Dupla Face 19x19mm - Kit com 50 Unidades', 'Fixador Auto-adesivo Dupla Face 19x19mm - Kit com 50 Unidades O Fixador Auto-adesivo Dupla Face 19x19mm F7801 é desenvolvido para organização, fixação e suporte de cabos em aplicações automotivas, residenciais, eletrônicas e profissionais. Fabricado em material resistente com adesivo de alta fixação, permite prender abraçadeiras e conduzir cabos de forma prática, segura e organizada. Com dimensões de 19x19mm, oferece excelente aderência e estabilidade, garantindo acabamento limpo mesmo em superfícies variadas. O kit contém 50 unidades, ideal para oficinas, instalações elétricas, montagem de painéis e organização de chicotes automotivos. Características Técnicas: Modelo/Código: F7801 Tipo: Fixador auto-adesivo para abraçadeiras Dimensões: 19x19mm Material: Nylon/plástico resistente Fixação: Adesivo de alta aderência Quantidade: 50 unidades Aplicação: Organização e suporte de cabos Diferenciais: Adesivo forte para aplicação segura Compatível com diversas espessuras de abraçadeiras Instalação rápida, limpa e sem necessidade de ferramentas Material resistente a uso contínuo Acabamento profissional em instalações elétricas Vantagens: Organização eficiente de cabos e chicotes Fixação firme e durável Permite fácil roteamento de fiações Excelente custo-benefício no kit com 50 peças Ideal para: Chicotes automotivos, instalações elétricas, montagem de painéis, organização de cabos em escritórios, residências, racks e aplicações que exigem fixação segura usando fixadores auto-adesivos F7801.', 43.9, 43.9, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi5zahc2yfb7d5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946086188%2F58251856803', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
