INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23592231867', 'Sensor Map Pressão Coletor Volkswagen Gol G3 99 A 2005 Mte', 'O sensor MAP tem como principal função informar a central de injeção a pressão no coletor de admissão, ele calcula a quantidade de oxigênio que está entrando na central, para que use a quantidade ideal de combustível que vai precisar usar, caso o sensor pare de funcionar o seu Gol pode travar, morrer com frequência, e não pegar quando estiver com o motor frio.', 114.86, 114.86, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rbkm-llxiod0gwhu3ba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F23592231867', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
