INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10694436457', 'Meia Calça Kendall Média Compressão s/Ponteira', 'DESCRIÇÃO: Seu corpo em equilíbrio, da ponta dos pés ao coração. A Meia Calça Kendall Sem Ponteira 15–20mmHg combina tecnologia e bem-estar, melhorando a circulação e reduzindo o cansaço das pernas. Ideal para quem trabalha em pé ou passa longas horas sentada, o modelo sem ponteira é perfeito para climas quentes e sapatos abertos. A Tecnologia UltraPro regula a temperatura e oferece proteção antibacteriana duradoura. COMPOSIÇÃO: 86% Poliamida e 14% Elastano. Fundelo: 56% Algodão e 44% Poliamida. PAÍS DE ORIGEM: Brasil. INSTRUÇÕES DE LAVAGEM: Lavagem a mão/Temperatura máxima 40°C; não alvejar; não secar em tambor; secagem em varal por gotejamento à sombra; não passar; não limpar a seco. INDICAÇÃO: Tratamento de varizes – Casos acentuados de Inchaço, dores e cansaço nas pernas – Uso de pílulas anticoncepcionais – Tendência hereditária e varizes – Viagem de longa distância, prevenindo a síndrome da classe econômica – Para quem fica o Dia inteiro sentado ou em pé – Durante ou após a gravidez. CONTRAINDICAÇÃO: Insuficiência arterial. Gangrena. Infecções cutâneas, Enxertia de pele em processo de cicatrização nos membros inferiores. CONTÉM: 01 par.', 206.9, 144.9, NULL, 'Health > Medical Supplies > Injury & Disability Support', 'https://cf.shopee.com.br/file/sg-11134201-821fz-mh0pw2m0glcad5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F735725428%2F10694436457', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998771917', 'Varal Para Roupas De Chão 100% Alumínio Grande Reforçado Com Abas Dobrável Retrátil Resistente Aço', 'NOVO DESIGN REFORÇADO! ÚNICO NO MERCADO! O MAIOR E MAIS RESISTENTE DISPONÍVEL! LIVRE DE FERRUGEM - FRETE GRÁTIS - ENTREGA RÁPIDA! DIMENSÕES DO VARAL ABERTO: 1,60M DE COMPRIMENTO x 0,90M DE ALTURA x 0,60M DE LARGURA SUPORTA ATÉ 23KG DE ROUPAS! O Varal de Chão com Abas de Alumínio é uma escolha inteligente para quem busca praticidade. Fácil de montar, desmontar e guardar, é ideal para quem tem uma rotina agitada e não pode esperar as roupas secarem ao ar livre. Sua estrutura robusta é feita de alumínio, proporcionando durabilidade e resistência, complementada por peças plásticas que conferem elegância e protegem seu piso contra arranhões. Sendo resistente à ferrugem, é perfeito para áreas costeiras. CARACTERÍSTICAS: Resistente à Ferrugem: Perfeito para regiões litorâneas. Não Descasca: Mantém seu aspecto novo por muito tempo. Leve: Fácil de manusear e transportar. Prático: Montagem, desmontagem e armazenamento simples e rápidos. Durável: Feito para durar, proporcionando anos de uso confiável. Experimente a qualidade e a praticidade deste varal inovador. Faça seu pedido agora e garanta roupas secas de forma rápida e eficiente! AGUARDAMOS SUA COMPRA!', 199.95, 149.99, NULL, 'Home & Living > Home Care Supplies > Clotheslines & Drying Racks', 'https://cf.shopee.com.br/file/sg-11134201-7rdvu-mct2n0oh1odz73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F601021305%2F22998771917', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40622942154', 'Mesa Prática Alumínio MOR Premium 80x60 Resistente Modelo Dobrável Vira Maleta - Original Mor', '🍽️ Mesa Prática Dobrável Mor – Portátil, Leve e Resistente ✅ Perfeita para piqueniques, churrascos e eventos ✅ Design dobrável com alça de transporte – fácil de carregar e guardar ✅ Estrutura reforçada em aço e alumínio ✅ Tampo em MDF resistente – suporta até 30 kg ✅ Ideal para uso interno e externo 🌟 Funcionalidade e Praticidade A Mesa Prática Mor foi projetada para quem busca mobilidade e eficiência no dia a dia. Com pernas dobráveis e alça de transporte, é simples de montar, desmontar e armazenar, ocupando pouquíssimo espaço. Perfeita para: Piqueniques e acampamentos 🍃 Churrascos e eventos ao ar livre 🍖 Refeições rápidas ou apoio em casa Feiras, trabalhos improvisados e áreas comerciais 🔧 Estrutura e Resistência Material da estrutura: Aço e alumínio Tampo: MDF resistente Capacidade de carga: até 30 kg Acabamento: firme, estável e durável 📏 Medidas Aberta: 80 cm (C) x 60 cm (L) x 70 cm (A) Fechada: 80 cm (C) x 60 cm (L) x 4,5 cm (A) 💡 Diferenciais Compacta, leve e fácil de transportar Montagem rápida – sem ferramentas Ideal para quem tem pouco espaço Uso versátil: doméstico, profissional ou lazer 👉 A Mesa Prática Dobrável Mor é sinônimo de versatilidade e praticidade, adaptando-se a qualquer ocasião com qualidade e estilo. Garanta a sua e leve funcionalidade para onde quiser!', 249.98, 184.99, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfgtzuej93b80d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F601021305%2F40622942154', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44272890236', 'Colchão de Ar Solteiro Inflável Bel Camping Acampamento Dormir Preto Confort Deluxe Premium Original', 'Colchão Inflável Solteiro Deluxe Comfort - Preto | Bel Garanta mais conforto e praticidade nos seus momentos de descanso com o Colchão Inflável Solteiro Deluxe Comfort da Bel. Perfeito para uso em casa, viagens ou acampamentos, ele é a solução ideal para quem busca praticidade sem abrir mão do bem-estar. Características: Versátil: Ideal para uso doméstico, viagens ou aventuras ao ar livre, como camping. Conforto garantido: Superfície aveludada que proporciona um toque macio e agradável ao deitar. Fácil de transportar: Leve, compacto e de fácil armazenamento quando esvaziado. Alta resistência: Estrutura durável, projetada para suportar até 150 kg com segurança. Praticidade no uso: Rápido de inflar e desinflar (bomba de ar não inclusa). Dimensões: 191 cm (comprimento) x 73 cm (largura) x 22 cm (altura). Atenção: Este produto não acompanha bomba de ar. Recomendamos o uso de bomba manual ou elétrica compatível para inflar o colchão com facilidade.', 149.98, 87.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mffig6lq6sjrac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F601021305%2F44272890236', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
