INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49058208201', 'Pano De Prato Barrado Premium Atacado Kit Com 5 Peças', 'Esses panos de prato são meu xodó na cozinha! Feitos com sacaria 100 % algodão – o legítimo “pé de galinha” – eles oferecem a qualidade que sempre procurei Cada um dos cinco panos do kit traz um barrado de 12 cm em tricoline, também de algodão, com estampas modernas e exclusivas que alegram qualquer ambiente O tecido é superabsorvente e anti‑mancha, não solta fiapos e pode até ser lavado com água sanitária sem desbotar As medidas generosas (45 cm x 69 cm) garantem versatilidade, seja para secar louça, proteger bancadas ou decorar Como amo cozinhar, valorizo cada detalhe: a costura reforçada nas bainhas traz durabilidade, e o passa-fita no barrado dá um charme extra Você recebe cinco unidades com estampas sortidas, perfeitas para usar ou presentear Garanta agora mesmo seu kit e transforme sua rotina com praticidade e beleza – clique em comprar e leve para casa esses panos de prato premium!', 35.99, 23.99, NULL, 'Home & Living > Home Care Supplies > Cleaning Cloths', 'https://cf.shopee.com.br/file/sg-11134201-8262m-mlfas52oskqt05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F388739239%2F49058208201', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
