INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50258959174', '10 SACOLA GRANDE 21X21X27,8cm 5852 DOLCE VITA ( MÃES JANGO 2026 )', 'INFORMAÇÕES IMPORTANTES E DICAS DE USO ✔ Acompanha alças resistentes Proporcionam praticidade e segurança no transporte, além de valorizar a apresentação do seu produto. ✔ Produto enviado desmontado A sacola é enviada desmontada para reduzir custos com frete e evitar avarias no transporte. A montagem é simples e rápida. ✔ Perfeita para valorizar seus produtos ✔ Comporta Caixa Mesinha ✔ Material ideal para datas sazonais e presentes Ótima opção para lembranças especiais, presentes personalizados e kits gourmet. ✔ Imagens e vídeos disponíveis para divulgação Todo o material visual deste anúncio pode ser baixado e utilizado livremente para promover seus produtos. ⚠ Imagens meramente ilustrativas O produto refere-se somente à embalagem. Não acompanha doces ou acessórios decorativos. Não recomendamos acomodar: ✖ Produtos acima de 21cm de largura ✖ Produtos acima de 21 cm de altura ✖ Produtos acima de 1,2 kg ? Dica de apresentação: Utilize papel de seda, tags ou laços para deixar a embalagem ainda mais sofisticada e segura durante o transporte. ⚠ Atenção aos prazos de entrega Recomendamos sempre considerar o prazo das transportadoras ao programar sua produção, especialmente em períodos de alta demanda. ⚠ Atenção: As cores do produto podem sofrer pequenas variações devido à configuração da tela do seu dispositivo.', 69.85, 69.85, NULL, 'Stationery > Gift & Wrapping > Gift Boxes', 'https://cf.shopee.com.br/file/sg-11134201-81zuz-mn4ouo912ark53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F50258959174', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
