INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53254160069', 'Sutia Sutien Push Up Com Efeito Magico Aumenta Modela e Junta os Seios Com Bojo Bolha 3D', 'Sutiã Push UP 3D Silicone Efeito Mágico Nayane Rodrigues Ref. 3774 - Original Confeccionado em microfibra macia e confortável. Sutiã com aro, bojo moldado e volume interno extra, que aproxima e levanta os seios, proporcionando o efeito "Push Up", sustentando e deixando os seios mais bonitos e atraentes. Sem base e com decote acentuado. Alças finas reguláveis. Costas com fecho em colchetes duplos de tripla regulagem. Caracteristicas: - Elásticos embutidos. - Alças com regulagem. - Costas em microfibra dupla. - Push up, aumenta em 2x volume dos seios. - Abotoador com três regulagens. BOJO ESPUMA MAGIC Esse bojo possui enchimento, aumentado a aparência dos seios, valorizando o colo. ALÇA MÉDIA Acompanha a maior parte dos sutiãs, garantindo média sustentação. LATERAL MÉDIA Lateral com modelagem confortável, se ajustando bem ao corpo. Sem renda Composição: - Poliamida: 91% - Elastano: 9% - Forro do Bojo: Poliéster: 100% Com renda Composição - Forro do bojo: Renda: 90% - Poliamida 10% - Elastano - Forro do Bojo: 100% Poliéster Tamanhos Disponiveis: - P - M - G - GG Cores Disponiveis: - Creme - Preto', 162.27, 89.19, NULL, 'Women Clothes > Lingerie & Underwear > Bras', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj4g0zcz8lxf2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800864347%2F53254160069', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23996920039', 'Restaurax 1,5L Renovador de Plástico Aplicador Pano Microfibra', '1- RESTAURAX 1,5L VONIXX 1- APLICADOR DE ESPUMA VONIXX 1- PANO 40X40 MICROFIBRA ------------------------------------------------- RESTAURAX 1,5L VONIXX DESCRIÇÃO: RESTAURAX renova e restaura superfícies plásticas, como para-choques, painéis e laterais de portas. Sua fórmula contém polímeros especiais que também protegem as peças contra as ações do tempo, evitando degradação precoce do material. MODO DE USO: 1- Limpar bem a superfície e em seguida aplicar o produto com um aplicador de espuma até a completa restauração. Se necessário, repetir a operação. 2- Para manter o plástico sempre novo, repetir a aplicação do produto a cada 60 dias na parte externa e a cada 6 meses na parte interna. Obs: Para um resultado com menos brilho, realizar acabamento com uma microfibra.', 199.93, 199.93, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Towels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-llw4rjo8c65z47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F23996920039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4561335015', 'Graxa Adesiva Spray Lubrificante Líquido W-Max', 'GRAXA ADESIVA SPRAY W-MAX 300ML DESCRIÇÃO: A Graxa adesiva W-MAX é um lubrificante líquido com alta capacidade de penetração em pequenas folgas, grande poder de adesão e resistência à pressão resultante da compressão. Possui baixo índice de gotejamento e com o aumento do atrito, a viscosidade aumenta progressivamente. APLICAÇÃO: - Rolamentos blindados. - Sistemas de transporte, como trilhos e cabos. - Superfícies deslizantes. - Pinos e dobradiças. - Engrenagens. - Peças submetidas a pressão, impacto e vibração. - Correntes de transmissão. MODO DE USAR: - O local a ser lubrificado deve estar limpo e seco, livre de óleos e graxas usados. - Aplique o produto diretamente sobre o ponto a ser lubrificado, a uma distância de 15cm.', 59.92, 59.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-7qukw-ljh3x5ilj99f52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F4561335015', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397383366', 'Cera Carnaúba Cristalizadora Automotiva Brilho 120g Vonixx', 'CARNAÚBA HYBRID WAX 120ML - CERA HÍBRIDA DESCRIÇÃO: Carnaúba Hybrid Wax é uma cera desenvolvida com a mais pura carnaúba cearense e polímeros de última geração, que protegem e dão brilho por um longo período DURABILIDADE: Até quatro meses de proteção na pintura do veículo MODO DE USO: 1. Aplicar o produto em pequena quantidade na pintura limpa e seca 2. Utilizar o aplicador incluso na embalagem e realizar a aplicação com movimentos uniformes 3. Aguardar entre 5 e 10 minutos e remover o produto utilizando toalha de microfibra até obter o brilho desejado', 71.92, 71.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Wax', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lsmobhbtxlic6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F23397383366', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
