INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8925558244', 'Escova Furadeira Drill Cerdas Média Mandala Detailer', 'ESCOVA DRILL DE CERDAS MEDIA AMARELA DETAILER A Escova Drill Cerda Média é uma escova com rosca 14mm indica para utilização em Politriz Rotativa de mesma rosca. Acompanha parafuso adaptador para ser acoplado em furadeira e parafusadeiras, sendo uma excelente ferramenta para uso em superfícies que necessitam de esfregação média e uma limpeza mais pesada. As cerdas desta escova são médias, desenvolvida para limpeza pesada seja em estofados, carpetes, bancos de couro e outros. Especificações técnicas: Limpeza média Tamanho: 4,25 polegadas 10 cm de diâmetro Rosca 14mm Acompanha o drill para o uso de furadeira ou parafusadeira Fácil instalação Alta praticidade Proporciona limpeza uniforme Alta durabilidade Material: Plástico PP Cerdasmédias Aplicação: Limpeza de tecidos automotivos e sofás com fios sintéticos. Instruções de uso: Utilizar com auxílio de multiuso específico para limpeza de tecidos. Dica importante: Verifique antes de comprar se a rosca do parafuso da sua politriz é 14mm, caso contrário este suporte não irá servir na sua politriz. ALoja ITPtraz todos os produtos que foram testados e aprovados pelo Instituto ITP, onde garante a qualidade e o custo benefício na hora de executar todos os procedimentos. O Instituto ITP profissionaliza você!', 98.87, 98.87, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/ac9ff14b4cda7a58da7e6c286b4eedea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F8925558244', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
