INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208249950', 'Gloss Labial Fairy Glitz Luluca - Rrl6411 - Melu', 'O Fairy Glitz é mais do que um gloss, é um carinho para os seus lábios! Com óleo de girassol e jojoba, ele nutre profundamente e possui ação antioxidante que protege os lábios durante o uso do produto. Leve, confortável, entrega um glow irresistível que você vai se viciar! Ativos: Óleo de Girassol e Óleo de Jojoba Modo de uso Aplique diretamente nos lábios ou sobre o batom. Precauções "Uso externo. Manter fora do alcance de crianças, em local seco e arejado, ao abrigo da luz, calor e umidade. Em caso de irritação, suspenda o uso e procure orientação médica. Indicação de idade: Acima de 12 anos', 36.91, 30.27, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-81ztn-mmoykqpa8iyp36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1784827857%2F58208249950', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
