INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53506595412', 'Par Bico Válvula Alumínio Pvr70 Pneu Scooter Lead Burgman Moto Elétrica 90 graus Premium', 'O Bico de Válvula Curvo 90° para pneus sem câmara é a solução ideal para facilitar a calibração, principalmente em scooters e motos onde o acesso ao bico tradicional é difícil. Fabricado com corpo em alumínio de alta resistência e vedação reforçada, proporciona maior durabilidade, excelente vedação e praticidade no uso diário. Seu formato curvo de 90° permite calibrar o pneu com muito mais facilidade e segurança. Conteúdo da Embalagem: - 01 Par de Bico Válvula Curvo 90° (2 unidades) Aplicação Compatível com motos e scooters com pneu sem câmara, como: - Honda Lead - Suzuki Burgman - Yamaha Neo - Yamaha Nmax - Dafra Citycom - Citycoco - e demais motos com sistema tubeless Principais Benefícios: - Facilita a calibração do pneu - Melhor acesso em rodas de scooter - Alta durabilidade - Excelente vedação - Não enferruja - Produto resistente - Instalação simples Especificações Técnicas: - Material: Alumínio + base de borracha - Ângulo: 90 graus - Tipo: Para pneus sem câmara (Tubeless) - Cor: Dourado com base preta Diferenciais: - Muito mais prático que o modelo reto - Facilita o acesso para calibragem - Maior durabilidade - Melhor vedação - Visual esportivo', 17.14, 16.29, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Others', 'https://cf.shopee.com.br/file/br-11134207-820ma-ml9j79jc701w4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F937893879%2F53506595412', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
