INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899856597', 'Conjunto Infantil Menina Blusa e Vestido Floral Elian Azul', 'O Conjunto Infantil Menina Blusa e Vestido Floral Elian é o must-have da estação! Composto por uma blusa em meia malha e vestido em tricoline, as peças oferecem conforto e leveza para as meninas aproveitarem cada momento. O vestido é o grande destaque do look, com sua estampa floral charmosa trazendo alguns rostinhos sorridentes, ideal para dar um contraste estiloso na sobreposição com blusa. Além disso, ele ainda conta com alças e detalhe com botões frontais, enquanto a blusa básica de mangas curtas complementa o look. Superfofo e confortável, é ideal para momentos de lazer ou ocasiões especiais. Aposte nessa combinação perfeita entre leveza e estilo para dias mais divertidos!', 149.9, 74.95, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-825ag-mr1tgejv92is40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F18899856597', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54608015858', 'Manto Flamengo Feminina OF2 Adidas 2026', 'Camiseta de malha de futebol com tecnologia Climacool para um desempenho sem distrações. A Camisa Manto 1 Branco Flamengo 26 mostra a lendária identidade do clube brasileiro com uma barra ousada no peito em uma base limpa. Esta camisa faz uma declaração poderosa dentro e fora do campo. A modelagem padrão e a gola bomber criam uma silhueta moderna de futebol, enquanto o tecido de malha dupla proporciona durabilidade e conforto contra a pele. Construída com a tecnologia adidas Climacool, a camisa é feita com materiais respiráveis para ajudar no resfriamento e proporcionar mais conforto. Um brasão do clube trançado completa o design com um símbolo autêntico da identidade do Flamengo. Mostre seu suporte ao time com esta linda camisa. Modelagem padrão: Nem apertada, nem oversized, na medida certa. Modelagem normal:Recomendamos pedir o tamanho normal. Tabela de Medidas: PP 77 - 82 cm (Busto) / 61 - 66 cm (Cintura) / 86 - 91 cm (Quadril) P 83 - 88 cm (Busto) / 67 - 72 cm (Cintura) / 92 - 97 cm (Quadril) M 89 - 94 cm (Busto) / 73 a 78 cm (Cintura) / 98 - 103 cm (Quadril) G 95 - 101 cm (Busto) / 79 - 85 cm (Cintura) / 104 - 110 cm (Quadril) GG 102 - 109 cm (Busto) / 86 - 94 cm (Cintura) / 111 - 117 cm (Quadril) Detalhes: Ajuste regular Decote bomber 100% poliéster (100% reciclado) Estrutura em malha dupla Comprimento regular Tecnologia CLIMACOOL Escudo do clube em tecido', 449.99, 449.99, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-820m4-mmvujbf53ytea7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467774639%2F54608015858', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
