INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897123501', 'Aspirador de Pó Vertical Mondial Turbo Cycle AP-36 - 1100W 220V', 'Manter a casa limpa e sem esforço não é mais um mistério. Com o Aspirador de Pó Vertical Mondial Turbo Cycle AP-36 - 1100W 220V você terá mais tempo de curtir sua família e amigos. O Aspirador é prático e versátil 2 em 1, para utilizar com haste ou na mão (portátil), perfeito para qualquer ambiente e ainda acompanha os acessórios como bocal para cantos e frestas, que é ideal para aspirar locais de difícil acesso, bocal para estofador com escova e bocal multiuso para todos os tipos de pisos e carpetes e tapetes. O Aspirador de Pó Vertical AP-36 tem o motor 1100W de potência, alto poder de sucção com baixo consumo de energia e 4 metros de alcance para aproveitar e limpar cada cantinho da sua casa. Com dupla filtragem, o Turbo Cycle remove impurezas do ambiente, deixando o ar mais limpo e completamente sem poeira e ainda conta com um reservatório de capacidade para 1,3L de pó transparente que aspira mais sujeira sem o uso de saco coletor, depositando-a diretamente no lixo, super prático, fácil de esvaziar e limpar, já que o filtro Cyclone é permanente, removível e lavável. Aspirador de Pó Vertical Mondial Turbo Cycle AP-36-1100W-220V, design moderno na cor vermelha para combinar com seu estilo, ainda é compacto e prático. Um Aspirador inteligente para manter a casa livre de poeiras, proporcionando mais tempo livre!', 241.99, 219.99, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/sg-11134201-825am-mqz2sn4chjb455', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F23897123501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
