INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097726597', 'Chave Combinada com Catraca 15mm Vonder 36.06.300.015', 'Chave Combinada com Catraca 15 MM - 36 06 300 015 - Vonder Produzida em aço cromo vanádio, proporcionando maior resistência e durabilidade. Conta com acabamento cromado fosco que oferece ótimo acabamento e maior proteção contra oxidaçãocorrosão. Possui sistema de catraca que permite a realização de trabalhos com mais agilidade e facilidade em locais de difícil acesso, sem a necessidade de retirar a chave para novo movimento.. Indicada para apertar e soltar porcas e parafusos sextavados. Nunca utilizar prolongadores sobre a chave, pois isso aumentará o torque aplicado e diminuirá a vida útil da ferramenta. Não utilizar o lado com catraca para o aperto final.. Dados Técnicos Material do corpo da chave: Aço cromo vanádio Acabamento da Chave: Cromado fosco Medida da chave combinada (mm): 15 mm Indicação: Agronegócio Autopeças e Acessórios Metal Mecânico Todas as informações divulgadas são de responsabilidade do FabricanteFornecedor Imagem Meramente Ilustrativa', 68.11, 68.11, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdy1-lyxkrpi9dcmg98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1096473040%2F22097726597', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
