INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255952566', 'Sutiã Com Aro Plus Power Liso Eclipse', 'O Sutiã Com Aro Plus Power Liso foi desenvolvido para oferecer sustentação firme, conforto e um ajuste impecável durante todo o dia. Com aro e sem bojo, valoriza a silhueta de forma natural, enquanto o tecido duplo proporciona suporte eficiente sem adicionar volume. As alças largas e reguláveis distribuem o peso de maneira uniforme, reduzindo a pressão nos ombros e garantindo mais conforto. É a escolha ideal para quem busca segurança, bem-estar e liberdade de movimentos, deixando para trás os desconfortos causados por sutiãs inadequados. Parte da linha Power Liso da Marcyn, este modelo reúne sutiãs e calcinhas essenciais para o dia a dia da mulher. Desenvolvida para quem valoriza sustentação, conforto e elegância em uma única peça, a coleção combina leveza, alta qualidade e excelente modelagem, tornando-se indispensável no guarda-roupa feminino. Descubra o conforto e a segurança do Sutiã Com Aro Plus Power Liso Marcyn e sinta a diferença de vestir uma peça criada para acompanhar sua rotina com máximo bem-estar. Um básico indispensável, com a qualidade, a tecnologia e a tradição que fazem da Marcyn uma referência em lingerie. Composição: 83% poliamida e 17% elastano Para melhor conservação da peça: Antes da lavagem, consulte sempre as instruções presentes na etiqueta interna do produto. Cada tecido possui características específicas que exigem cuidados adequados para preservar a qualidade, a elasticidade e a durabilidade da peça. Industria Brasileira!', 129.9, 129.9, NULL, 'Women Clothes > Lingerie & Underwear > Bras', 'https://cf.shopee.com.br/file/sg-11134201-82614-ml7y1ohh0xs115', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1635123562%2F58255952566', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
