INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398094250', 'Filtro Ar Vw Gol 1994 a 2002 - 1352991 - FAP4049', 'Filtro Ar Vw Gol 1994 a 2002 1352991 FAP4049 Motor 2.0 8v - (Mecânico) Após passar pelo filtro, o ar é aspirado pelo motor através de seus êmbolos (pistões). Durante este processo, sensores do sistema de injeção eletrônica enviam sinais para o Módulo da Injeção Eletrônica do Veículo, informando a temperatura do ar que está sendo admitido. O filtro do ar é construído para que as impurezas em suspensão no ar sejam separadas, ficando as mais pesadas depositadas no fundo da caixa de filtração e as mais leves sendo retidas pelo elemento filtrante.', 25.53, 25.53, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rfg8-m3z7a2g7qav748', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23398094250', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697034286', 'Eletroventilador Radiador Gm Kadett 1989 a 1998 - 182155 - AVLD02005', 'Eletroventilador Radiador Gm Kadett 1989 a 1998 182155 AVLD02005 1.8/2.0 8v - (Com ACD) (5 Pás) (Sentido Horário) (Diâmetro - Hélice 360 mm / Motor 100 mm / Eixo 8 mm) (Potência 252W) (Aspira) Sua finalidade é forçar a circulação de ar no radiador para reduzir a temperatura do líquido de arrefecimento. O eletroventilador consiste numa ventoinha acionada por meio de um motor elétrico de corrente contínua.', 256.23, 256.23, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-822x8-mo8scuwnsd1k6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23697034286', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23395588036', 'RELÓGIO LINCE FEMININO LDM4642L PXSX', 'Relógio Feminino Digital Led Lince LDM4642L PXSXRelógio feminino com sistema digital indicando as horas, minutos e segundos. Possui formato 24 horas e iluminação noturna. Pulseira em aço trabalhado com fechamento por fivela de pressão.Resiste à água: 5ATMComposição do Vidro: cristal mineralMaterial da Caixa: metalMaterial da Pulseira: aço Medidas aproximadas:- Largura da caixa, incluindo pino: 3,2cm- Espessura da caixa: 1cm- Comprimento da pulseira: 19cm Informações Adicionais:Tamanho: únicoCor: prateadoModelo: Relógio Feminino Digital Led Lince LDM4642L PXSXMaterial: açoDetalhes adicionais: digital ledMarca: Lince - Acompanha estojo com 1 Relógio, 1 Manual de instruções e Certificado de garantia', 307.73, 307.73, NULL, 'Watches > Women Watches', 'https://cf.shopee.com.br/file/br-11134201-7r98o-mbd219bcj4pb14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F220800578%2F23395588036', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898021379', 'Reparo Bico Injetor Fiat Idea 2006 a 2016 - 191354 - 1243', 'Reparo Bico Injetor Fiat Idea 2006 a 2016 191354 1243 1.4 8v Flex /1.6 16v E-Torq - (Multi Point) (4 Filtros + 8 O''rings) Tem a finalidade de evitar entupimento do bico injetor devido às impurezas e contaminações do combustível. Outra função é vedar a entrada falsa de ar no coletor de admissão evitando vazamentos. Ao fazer a limpeza do bico injetor, devemos trocar o(s) filtro(s) e os anéis, pois eles retêm as impurezas que diminuem o volume de combustível injetado provocando assim, algumas irregularidades como perda de potência, dificuldade na partida e funcionamento irregular do motor.', 38.84, 38.84, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7req5-m2iaatm6w28m11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22898021379', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40462529106', 'CELIMAX Cica BHA Blemish Toner Pad 10pads', '✅ Product Features Key Ingredients: Cica (Centella Asiatica Extract), BHA (Salicylic Acid) Benefits: Exfoliates dead skin cells and cares for pores Soothes the skin and helps improve blemishes Controls excess sebum and refines skin texture Texture: Soft cotton pads soaked in toner Skin Type: Recommended for oily, combination, and acne-prone skin 💡 How to Use After cleansing, take out a pad and gently wipe along the skin texture using the embossed side. After refining the skin texture, use the smooth side to wipe once more for better absorption. Can be used daily or 2–3 times a week depending on skin condition. Close the lid tightly after use to keep the pads fresh. Full Ingredients: Water, Butylene Glycol, Denatured Alcohol, 1,2-Hexanediol, Arginine, Salicylic Acid (0.45%), Hydroxyacetophenone, Camellia Japonica Flower Extract, C12-14 Alketh-12, Lactobionic Acid, Ethylhexylglycerin, Glycerin, Bifida Ferment Lysate, Centella Asiatica Extract (0.02%), Disodium EDTA, Lactose, Melaleuca Alternifolia (Tea Tree) Leaf Oil, Houttuynia Cordata Extract, Portulaca Oleracea Extract, Perilla Frutescens Extract, Panthenol, Lonicera Japonica (Honeysuckle) Flower Extract, Pelargonium Graveolens Extract, Uncaria Tomentosa Extract, Eupatorium Fortunei Extract, Corydalis Ternata Root Extract, Pinus Sylvestris Leaf Extract, Nepeta Cataria Extract, Madecassoside (0.001%), Capryloyl Salicylic Acid', 34.77, 34.0, NULL, 'Beauty > Skincare > Toner', 'https://cf.shopee.com.br/file/sg-11134207-7rdyu-mdcrgpe1dvf8a3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F40462529106', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
