INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41466051332', 'PURCELL Highdose SAMPLE SET, 1ml Each * 3Types (Pixcell Biom™, Peptide Formula, L-Glutathione Liposome)', 'CONJUNTO DE AMOSTRAS DE altadose PURCELL CONJUNTO DE AMOSTRAS DE altadose, 1ml Cada*3Tipos (Pixcell Biom™, Fórmula Peptídica, L-Glutationa Liposome) 🌟 CONJUNTO DE AMOSTRAS DE COMPRA COMPRA DE altadose 🌟 Contém: 1. Biom de casca de pixceleira™ Bifida Lactobacillus, 1ml x 1Billion/mL - Lactobacillus Bifida, 1ml x 1EA 2. Dose alta de 82%™ Fórmula Peptídica Peptídica - Atualizador de Procolágeno, 1ml x 1EA 3. Liposome Flexível L-Glutationa 88B/mL - Regulagem de Melanócito, 1ml x 1EA ✨ Visão geral do produto] Experimente as principais inovações de PURCELL em um conveniente conjunto de amostras de altas dos detalhes da PURCELL em um conveniente conjunto de amostras de altadose. Este kit de teste deluxe possui três formulações avançadas, cada um projetado com tecnologia de ponta para direcionar diferentes preocupações com a pele - hidratação, firmeza e brilho. Perfeito perfeito para usuários de primeira viagem que desejam descobrir a biotecnologia única da PURCELL ou como solução de cuidados com a pele amigável para viagens. 🧪 O que há dentro do ✅ Biom de casca de pixceleira™ (1ml) Complexo inovador de biotecnologia inovadora para revitalizar a pele cansada Fortalece a barreira da pele e aumenta o equilíbrio de hidratação ✅ Fórmula de Peptídeos (1ml) Peptídeos de alta potência para cuidados reafirmantes e comprovantes de rugas Apresenta elasticidade e textura mais suave ✅ Liposome Flexível Glutationa Glutationa (1ml) Sistema de entrega avançado de glutationa avançado para clareamento e cuidados com o tom A ajuda a melhorar o embotamento e a tez irregular 🌱 Benefícios principais ✔️ Conjunto de teste experimental com 3 soluções poderosas em um pacote ✔️ Fórmulas científicamente apoiadas com Pixcell Biom™Peptídeos, e Glutationa ✔️ Ampolas de uso único de tamanho de viagem e higiênicas ✔️ Adequado para todos os tipos de pele 📦 CONTEÚDO 1ml × 3ea (uma de cada fórmula Highdose) Selado individualmente para máxima frescura 💡 Dica: Use consecutivamente mais de 3 dias para experimentar toda a sinergia das fórmulas Highdose da PURCELL!', 28.3, 27.0, NULL, 'Beauty > Beauty Sets & Packages', 'https://cf.shopee.com.br/file/sg-11134207-824iu-me13q4nfwf7p64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F41466051332', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492976396', 'Válvula Termostática Vw Fox 2003 a 2022 - 842195 - AVTS01002T87', 'Válvula Termostática Vw Fox 2003 a 2022 842195 AVTS01002T87 1.0/1.6 8v Flex - 87º A válvula termostática é uma peça importantíssima do sistema de arrefecimento dos carros. Ela controla a temperatura do motor. Quando o motor está frio, ela fica fechada, fazendo com que o líquido de arrefecimento (água e aditivo) volte para o bloco do motor. A partir de uma determinada temperatura, cerca de 90 graus, ela se abre, permitindo a passagem do líquido para o radiador para que ele seja refrigerado e volte para o bloco. A manutenção preventiva a cada 30 mil km ou menos.', 37.81, 37.81, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd5j-lufhp2uv9pma5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22492976396', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
