INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23592819804', 'Radiador Chevrolet Corsa 94 A 2002 Sem Ar - 64403 - IR48218', 'Radiador Chevrolet Corsa 94 A 2002 Sem Ar 1.0/1.4/1.6 (SEM AR CONDICIONADO) Alumínio Mecânico (530x268x23) O radiador, faz parte do sistema de resfriamento da água que circula pelo bloco do motor, fazendo com que a temperatura não exceda os limites aconselháveis para o funcionamento do motor. A temperatura ideal para a água é de 70º C praa gasolina e de 80º C nos a álcool e a diesel. A água quente que sai do bloco do motor, circula forçadamente pelo interior dos tubos do radiador, onde é resfriada. Essa água é resfriada porque através do bloco, é forçada a circulação de ar, através de um ventilador.', 222.74, 222.74, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Air Conditioning', 'https://cf.shopee.com.br/file/sg-11134201-7rbma-lqqs6r1nxbc23f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23592819804', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
