INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21299254445', 'Sensor Fase Amarok 2.0 2010/2014 Mte-70584', 'DESCRIÇÃO: O sensor de fase no carro é responsável por monitorar a posição do virabrequim. Ele fornece informações precisas ao sistema de gerenciamento do motor, permitindo a sincronização correta da ignição e injeção de combustível. Essa função essencial ajuda a garantir o desempenho ideal do motor, economia de combustível e redução das emissões. APLICAÇÃO: AMAROK 2.0 16V 2010/2014 Especificações técnicas: Quantidade de itens na embalagem: 1 Código de referência: 03L957147 Código do fabricante: 70584 Quantidade de pinos: 3 CODIGOS ORIGINAIS E SIMILARES DA PEÇA Seat: 03L907601 03L957147 03L957147A Volkswagen: 03L907601 03L957147 03L957147A Audi: 03L907601 03L957147 03L957147A Skoda: 03L907601 03L957147 03L957147 Atenção: As compras realizadas em nome de Pessoa Jurídica estão sujeitas à cobrança de ICMS, conforme Protocolo ICMS 41, de 4 de Abril de 2008. Caso você tenha dúvidas sobre o percentual a ser aplicado, consulte a Cláusula Segunda, §1° do referido ProtocoloVALOR REFERENTE: MTE-70584', 271.65, 271.65, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd5x-lv28oxf9q8e7b1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290560683%2F21299254445', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18897381898', 'Motul C4 Mc Care Chain Lube Lubrificante De Corrente 400ml', 'DESCRIÇÃO DO PRODUTO CHAIN LUBE Factory Line Lubrificante para motocicletas de estrada Coloração branca, de alta aderência Spray USO Todos os tipos de correntes: standard ou com O’RING, X’RING, Z’RING. Resultado da experiência da Motul em competições de motocicleta e somente para uso em estrada (pela alta aderência), o MOTUL CHAIN LUBE Factory Line é um lubrificante especialmente desenvolvido para lubrificar correntes de motocicletas de corrida. Especialmente recomendado para motocicletas de alta velocidade: MOTUL CHAIN LUBE Factory Line adere à corrente mesmo em altas velocidades. DESEMPENHO Baseado numa formulação de aditivos sólidos anti-desgaste e extrema-pressão, o MOTUL CHAIN LUBE Factory Line reduz a resistência à rolagem, aumenta a eficiência da transmissão e mantém suas propriedades lubrificantes mesmo sob alta temperatura. Aumenta a durabilidade da corrente. Resistente à água e ferrugem. Protege O-rings, X-rings e Z-rings. Contém solvente para eliminar os resíduos antigos e penetrar entre os elos da corrente. Coloração branca para facilitar a aplicação. RECOMENDAÇÕES Limpe a corrente com MOTUL CHAIN CLEAN. Agite antes de usar. Aplique ao longo de toda a corrente, na face interna: aplicação facilitada pela coloração branca do MOTUL CHAIN LUBE Factory Line. MOTUL CHAIN LUBE Factory Line adere completamente em 10 minutos após a aplicação. SEGURANÇA Consulte a FISPQ e as informações no rótulo do produto.', 152.37, 152.37, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rdwq-lz0jqnezfkef2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1068060049%2F18897381898', 