INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20597995361', 'Cilindro Roda Gm Monza 1988 a 1996 - 120959 - CCR9283', 'Cilindro Roda Gm Monza 1988 a 1996 120959 CCR9283 1.8 / 2.0 (8V) - Traseiro - Lado Direito - 7/8" / 22,22 mm - Sistema VargaO Conjunto de Cilindro de Roda é utilizado em veículos cujo sistema de freios é a tambor. Ele aciona os freios na roda quando recebe pressão hidráulica enviada pelo cilindro mestre, assim, as sapatas são empurradas dando o atrito no tambor de freio, fazendo com que a roda freie e pare o veículo.', 46.59, 46.59, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd41-m7t8qmxua22rab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20597995361', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
