INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997668848', 'Sonda Lambda Gm Corsa 1999 a 2002 - 152638 - 781012040', 'Sonda Lambda Gm Corsa 1999 a 2002 152638 781012040 Wagon - 1.0/1.6 - 1 Fio - Comprimento do Fio 40 cm - Pré Catalisador - Fio Violeta A sonda lambda, sensor de oxigênio, sensor de O2, por vezes também chamado sensor EGO (do inglês exhaust gas oxygen), é um dispositivo que envia um sinal elétrico à injeção eletrônica do automóvel indicando a presença de oxigénio nos gases de escape, possibilitando o controle da quantidade de combustível a enviar para o motor.', 141.3, 141.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7rd46-luf9zreytsr81e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18997668848', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
