INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16771675313', 'Óculos de Proteção Para Solda Automático OSL-3/11 15627.6 LYNUS', 'Óculos de Proteção Para Solda Automático OSL-3/11 15627.6 LYNUS Bateria interna recarregável através de célula solar até mesmo com a luz da própria solda. Escurecimento automático. Ampla área de visão. MSL-3500 Compatível com processos MMA/MIG. MSL-5000 Compatível com processos MIG/MAG/MMA/TIG/CUT - com regulagem de estágio. Protege o usuário de partículas volantes frontais, radiação ultravioleta, infravermelho e luminosidade intensa. DADOS TÉCNICOS: Área de visão: 90 x 32mm. Estágio claro: DIN 3. Estágio escuro: DIN 11. Tempo de resposta: 5/10000. Proteção do filtro (UV / IR): DIN 16. Dimensões do filtro: 110 x 50 x 5mm. Temperatura de operação: -5°-55°. Temp. de armazenamento: -10°-70°C. Peso (gf): 0,90. Ref: 15627.6 Marca: Lynus Garantia: 3 meses *Imagens meramente ilustrativas.', 75.9, 75.9, NULL, 'Home & Living > Tools & Home Improvement > Protective Gloves, Goggles & Masks', 'https://cf.shopee.com.br/file/8e9c96b8f83657b5d1b9334779ecb50d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F16771675313', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793643061', 'Pré Treino V9 Pump 300g - Shark Pro', 'Explosão de Energia e Foco Para Seus Treinos! O V9 Pump Pre Workout da Shark Pro é o aliado perfeito para atletas que desejam maximizar sua performance. Com ingredientes como beta-alanina, taurina, arginina e cafeína (400mg por dose), este pré-treino oferece energia duradoura, resistência prolongada e foco total, ajudando você a ultrapassar limites nos treinos mais intensos. Além disso, sua fórmula é enriquecida com vitaminas e minerais que promovem equilíbrio e saúde. Benefícios: Energia Explosiva: 400mg de cafeína por dose, garantindo disposição máxima. Foco Intenso: Mantém sua mente concentrada durante todo o treino. Resistência Prolongada: Beta-alanina e taurina combatem a fadiga, otimizando o desempenho. Saúde Nutricional: Rico em vitaminas B5, B6, E e cromo para suporte completo. Sabores Variados: Disponível em açaí com guaraná, limão, maracujá, tangerina e uva. Sugestão de Uso: Misture 1 ½ colher medida (10g) em 150ml de água gelada. Consuma de 15 a 30 minutos antes do treino ou conforme orientação de um profissional de saúde. Advertências: Este produto não é um medicamento. Não exceder a recomendação diária indicada na embalagem. Não recomendado para gestantes, lactantes ou crianças. Contém cafeína e fenilalanina. Mantenha fora do alcance de crianças. Composição e Ingredientes: Principais ativos: Beta-alanina (2g), taurina (2g), arginina (1g), cafeína (400mg). Enriquecido com vitaminas B5, B6, E e cromo. NÃO CONTÉM GLÚTEN. NÃO CONTÉM LACTOSE.', 109.9, 69.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5a3levg46nm21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965164614%2F23793643061', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
