INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21847856465', 'Folhas Prontas Corporal Depilsam Mel 10 Pares', 'A Depilsam Folhas Prontas Corporais Mel 10 Pares é a solução perfeita para uma depilação prática, eficiente e sem sujeira! Desenvolvidas para remover os pelos desde a raiz, elas garantem uma pele lisa e livre de pelos por semanas. O extrato de mel na fórmula ajuda a manter a pele nutrida e hidratada, reduzindo irritações. Basta aquecer levemente as folhas entre as mãos, aplicar na pele e puxar com firmeza. Ideal para quem busca resultados rápidos e duradouros sem sair de casa! Uso impróprio para: ❌ Crianças ❌ Gestantes ❌ Não utilizar em pessoas em tratamento médico específico para a pele Zonas de Aplicação: ✅ Corpo (exceto virilha, axilas e rosto) ❌ Não aplicar na virilha, axilas e rosto Benefícios: ✅ Depilação eficiente e prática ✅ Pele macia e livre de pelos ✅ Ingredientes suaves para a pele ✅ Fácil de usar, sem necessidade de aquecer a cera Modo de Uso: 1️⃣ Leia as instruções no rótulo antes de iniciar o uso. 2️⃣ Certifique-se de que a pele esteja sem oleosidade, suor ou resíduos de produtos cosméticos. 3️⃣ Aqueça as folhas entre as mãos por 10 segundos (20 a 30 segundos em dias frios). 4️⃣ Aplique a folha na região desejada e pressione suavemente no sentido do crescimento dos pelos. 5️⃣ Puxe a folha em um movimento único e rápido no sentido contrário ao crescimento dos pelos. 6️⃣ Caso reste algum excesso de cera, pressione a folha dobrada para remover. 7️⃣ Após a depilação, utilize o removedor pós-depilação Depilsam para retirar os resíduos.', 42.99, 23.49, NULL, 'Beauty > Bath & Body Care > Hair Removal Cream & Wax', 'https://cf.shopee.com.br/file/de9a18e3719d1f0c32df29c19c3d15cf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436104412%2F21847856465', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
