INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20898104892', 'Tênis Under Armour Charged Quicker 2 Preto e Branco', 'Tecnologias High Frequency: oferece mais firmeza na amarração. Charged: Sistema que proporciona um super amortecimento e resposta rápida, protegendo os pés contra impactos. New Charged Cushioning: proporciona máxima resposta, mantendo o conforto e a durabilidade durante a performance. High Abrasion Rubber: oferece uma ótima tração e mais segurança nas transações. Ortholite®: Absorve a umidade para as camadas externas, concede amortecimento de longa duração, inibe a formação de odor e bactéria, além de proporcionar fluxos de ar para os pés. Composição cabedal (parte superior): Têxtil com partes em sintético Forro: Têxtil com acolchoamento reforçado no calcanhar Palmilha: Em EVA Ortholite forrado e removível Solado: Borracha resistente e antiderrapante Entressola: EVA leve e macio Cor predominante: Preta Lingueta: Integrada Gênero: Unissex Origem: Nacional Ajuste: Cadarço Peso aproximado: 570g o par n° 40', 510.9, 510.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7repn-m83rc34qgpts8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F20898104892', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204711570', 'Lanterna Led Scania S5 S6 Ntg P G R Bivolt - luz de posição, freio, ré e pisca', 'Lanterna Traseira LED Bivolt Compatível para Caminhões Scania Modelos Streamline S4 S5 S6 (ano 2013 em diante) * Selecione a opção desejada nas variações do anúncio Modelos de Aplicação: - Scania Streamline 2014 - Scania Streamline 2015 - Scania Streamline 2016 - Scania Streamline 2017 - Scania 113 (adaptação simples) - Scania Serie 5 Serie 6 P/ G/ R - Série 4- 114,124 P, G, R, T DE 1998 ATÉ 2006 - Scania S5/S6 2013 MODERNO P/G/R - Scania P114 P124 P230 P250 P270 P310 P340 P360 P420 P94 P31 - SÉRIE 4 / 5 / 6 - G360 G380 G400 G420 G440 G470 G480 - Scania R164 R124 R114 R380 R400 R420 R440 R470 R480 R500 R560 R580 R620 - A Ameriparts não se responsabiliza pela má instalação ou mau uso do produto, faça a instalação com profissionais especializados. - Atenção: As compras realizadas em nome de Pessoa Jurídica estão sujeitas a cobrança de ICMS, conforme Protocolo ICMS 41, de 4 de abril de 2008. Caso você tenha dúvidas sobre o percentual a ser aplicado, consulte a Cláusula Segunda, §1° do referido Protocolo. - Peças não genuínas - Todos nossos produtos acompanham Nota Fiscal, enviada de acordo com as informações do cadastro do comprador. - Código de referência: 020742 - 1905043 - 020743 - 1905044 - Em caso de dúvidas use o campo de Perguntas.', 268.49, 268.49, NULL, 'Spare Parts and Accessories for Vehicles > Heavy Duty and Boats > Spare Parts for Heavy Duty Vehicles', 'https://cf.shopee.com.br/file/br-11134207-820ln-mpm9h8lqvj0ja1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F843124271%2F58204711570', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202346857', 'Fonte Tecnologia GaN para Notebook Lenovo Thinkpad X1 Fold 16 21ET000DBR 65W USB-C', 'Fonte Tecnologia GaN para Notebook Lenovo Thinkpad X1 Fold 16 21ET000DBR 65W USB-C A Fonte Carregador bringIT com tecnologia GaN traz o que há de mais moderno em tecnologia de carregamento: leve, rápido e confiável para notebook e outros dispositivos com USB-C. Este carregador é a combinação perfeita de potência e portabilidade porque utiliza o Nitreto de Gálio (GaN), na sua composição. O Nitreto de Gálio (GaN) é um semicondutor mais eficiente que o silício usado nas fontes convencionais. A fonte GaN opera em potências mais altas, com menor geração de calor e maior aproveitamento de energia. Especificações Técnicas: Marca Compatível: Lenovo Série do notebook: Thinkpad X1 Fold Modelo: 16 21ET000DBR Voltagem: 5V 12V 15V 20V Amperagem: 3A 3.25A Potência: 65W Plug: USB-C Garantia: 36 meses de garantia contra defeitos de fabricação Referência: FG165-LE-0046 Compatibilidade: As fontes com tecnologia GaN utilizam o padrão USB-C Power Delivery (PD). São compatíveis com notebooks que carregam via porta USB-C, identificada pelo símbolo de carregamento próximo à entrada. Para o melhor desempenho, verifique a potência* (W) da sua fonte original: - Se o notebook usa fonte de 65W, pode utilizar GaN de 65W, 100W ou 140W - Se o notebook usa fonte de 90W, recomenda-se uma GaN de 100W ou 140W Atenção: Se a potência da for menor do que a fonte original, o notebook poderá carregar lentamente ou não iniciar a carga.', 187.38, 187.38, NULL, 'Computers & Accessories > Desktop & Laptop Components > Power Supply Units', 'https://cf.shopee.com.br/file/sg-11134201-825a6-mq6w1u5ovrbf3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F58202346857', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
