INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206818180', 'Vult & Baton Gloss Stick Translúcido com Glitter 2g', 'O Gloss Stick Translúcido com Glitter é a escolha certa para iluminar o sorriso com nostalgia. Ele combina partículas de brilho com o delicioso cheirinho inspirado no chocolate branco. Conheça as características desse produto que vão fazer você se apaixonar: Garante brilho espelhado intenso; Textura que derrete e hidrata os lábios; Fórmula leve que não pesa; Acabamento lustroso e suave; Vegano e Talc free. Perfeito para finalizar a make ou usar sozinho, este gloss oferece alto brilho e tratamento, deixando os lábios macios e com aspecto saudável. Nenhum produto VULT é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 49.99, 44.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-8261d-mlqq82sl81s224', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1675526045%2F58206818180', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
