INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22761046143', 'CNP Propolis Lip Cerin, 4 opções, 15ml', '[Original] Características: Extrato de própolis: Proporciona excelentes efeitos calmantes e hidratantes da pele, proporcionando rica nutrição aos lábios. Proteção Labial Lip: Hidrata os lábios secos suavemente e hidrata, mantendo-os lisos e hidratados. Aplicação Lisa: Desliza suavemente sem viscosidade, proporcionando um brilho natural. Modo DE USAR: Aplique uma quantidade adequada nos lábios e alise suavemente. Reaplicar sempre que sentir secura para hidratação contínua. [Cafe Mocha] Características: Cafe Mocha scent: Um aroma doce que mistura notas ricas de café e chocolate. Extrato de Própolis: Acalma e hidrata os lábios. Hidratação labial: Além do perfume Cafe Mocha, mantém os lábios hidratados. Modo DE USAR: Aplicar suavemente nos lábios para hidratação natural e fragrância agradável. [Matcha] Características: Perfume Matcha: Um fresco, Verde Fragrância de chá de chá que refresca os lábios. Própolis de própolis: Ajuda a acalmar e hidratar os lábios, mantendo-os macios e protegidos. Modo DE USAR: Aplique nos lábios para mantê-los saudáveis e hidratados. Latte de café] Características: Perfume Cafe Latte: Um aroma suave e nocivo Cafe Latte que adiciona um toque natural aos seus lábios. Umidade e Nutrição essenciais: A própolis proporciona umidade e nutrição essenciais aos seus lábios. Modo DE USAR: Aplique suavemente nos lábios e reaplicar conforme necessário para proteger e manter os lábios hidratados.', 81.51, 78.0, NULL, 'Beauty > Skincare > Lip Treatment', 'https://cf.shopee.com.br/file/sg-11134207-7reqa-m8bozbhyy5xtc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F22761046143', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
