INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998427540', 'Forma De Silicone Cupcake Mini Bolo 6 Cavidades Vermelha', '🧁 Forma de Silicone para 6 Cupcakes, Muffins ou Petit Gâteaux – Resistente, Flexível e Prática 👩‍🍳 Mais praticidade, higiene e perfeição nas suas receitas! Prepare cupcakes, muffins, petit gâteaux e bolinhos com facilidade usando esta forma de silicone com 6 cavidades. Flexível, durável e resistente a altas e baixas temperaturas, ela é ideal para quem ama praticidade na cozinha, seja para uso doméstico ou profissional. ✅ Vantagens do Produto: 🧽 Silicone de alta qualidade Material resistente, atóxico, livre de BPA e com excelente durabilidade. 🔥 Resiste de -40 °C a 230 °C Vai ao forno, micro-ondas, freezer e até lava-louças sem perder a forma. 🙌 Desenforme com facilidade O silicone flexível permite soltar os bolinhos sem esforço, sem grudar e sem quebrar. 🧼 Muito mais higiênica Não retém odores, fácil de lavar e seca rapidinho. ♻️ Durável e reutilizável Economia e sustentabilidade no dia a dia da cozinha. 🍩 Perfeita para preparar: Cupcakes Muffins Petit Gâteaux Mini bolinhos, empadinhas doces e muito mais 📏 Especificações Técnicas: Material: Silicone alimentício Dimensões totais: 24 cm (C) x 16,5 cm (L) x 3,5 cm (A) Cavidades (cada): Diâmetro superior: 6,3 cm Diâmetro inferior: 4,8 cm Altura: 3,5 cm 📦 Itens Inclusos: 1x Forma de Silicone com 6 cavidades 💡 Dica: Por ser super flexível, use uma assadeira por baixo para facilitar o transporte até o forno com estabilidade.', 33.75, 19.01, NULL, 'Home & Living > Kitchenware > Bakewares & Decorations', 'https://cf.shopee.com.br/file/sg-11134201-7repq-m8w9mkh96nvd7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408653169%2F22998427540', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094883417', 'Kit Luminária Spot Led Redondo Com Controle Luz Fria ou Quente Auto Colante Bivolt', 'Lâmpada Spot LED com Controle Remoto – Branco Frio ou Branco Quente ✨ DESTAQUES • Iluminação LED eficiente e econômica 💡 • Acompanha controle remoto liga/desliga 🎮 • Duas opções de luz: branco frio ou branco quente • Ideal para móveis, armários, cozinha e iluminação decorativa • Instalação simples e rápida • Design discreto e funcional 💡 DESCRIÇÃO A Lâmpada Spot LED com Controle Remoto é perfeita para quem busca iluminação prática e direcionada. Permite ligar e desligar à distância, trazendo conforto e funcionalidade para o dia a dia. Ideal para cozinhas, armários, bancadas, corredores e iluminação auxiliar, com luz uniforme e agradável. Produto simples, eficiente e sem complicação. Funciona porque foi feito pra funcionar. ⚙️ ESPECIFICAÇÕES • Tipo: Spot LED • Controle: Remoto incluso • Cor da luz: Branco frio ou Branco quente • Aplicação: Iluminação interna 📦 CONTEÚDO DA EMBALAGEM • 01 Lâmpada Spot LED • 01 Controle remoto', 60.0, 23.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk81luwaz9c0a0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979730489%2F22094883417', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
