INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297668595', '5 Luminária Emergência Lâmpada 30 ou 60 Leds Recarregável Bivolt Luz Branca Fria', 'Luminária LED Recarregável de Emergência – 30 ou 60 LEDs Iluminação prática, econômica e indispensável para emergências, quedas de energia, corredores, quartos, escritórios, áreas de serviço, camping ou uso diário. Conta com bateria interna recarregável de lítio, acendimento instantâneo e excelente autonomia. Disponível em 2 versões: 30 LEDs ou 60 LEDs, para atender diferentes necessidades de iluminação. Modelo 30 LEDs Compacta, leve e ideal para iluminação auxiliar em ambientes internos. Especificações Técnicas * Quantidade de LEDs: 30 LEDs * Temperatura de cor: Branco Frio – 6500K * Índice de Reprodução de Cor (IRC): >70 * Fluxo luminoso: 50 lúmens (mínimo) até 100 lúmens (máximo) * Frequência: 50/60Hz * Ângulo de abertura: 120° * Vida útil estimada: 10.000 horas Alimentação e Bateria * Tensão de entrada: 100–240V bivolt automático * Corrente nominal: — 5mA em 110V — 25mA em 220V * Corrente máxima: — 10mA em 110V — 30mA em 220V * Bateria interna: Lítio 500mAh – 3.7V Autonomia * Fluxo mínimo: até 5 horas * Fluxo máximo: até 3 horas Dimensões e Peso * Medidas: 160 x 42 x 25 mm * Peso aproximado: 90g Modelo 60 LEDs Versão com maior intensidade luminosa, ideal para ambientes maiores ou necessidade de iluminação mais forte. Especificações Técnicas * Quantidade de LEDs: 60 LEDs * Potência: 5W * Temperatura de cor: Branco Frio – 6500K * Índice de Reprodução de Cor (IRC): >80 * Fluxo luminoso: 400 lúmens (80Lm/W) * Frequência: 50/60Hz * Ângulo de abertura: 120° * Vida útil estimada: 10.000 horas Alimentação e Bateria * Tensão de entrada: 100–240V bivolt automático * Corrente nominal: — 25mA em 100V — 50mA em 240V * Corrente máxima: — 30mA em 100V — 60mA em 240V * Bateria interna: Lítio 1200mAh – 3.7V Autonomia * Fluxo mínimo: até 6 horas * Fluxo máximo: até 3 horas Dimensões * Medidas: 203,1 x 56,5 mm Principais Vantagens * Bateria interna recarregável de longa duração * Funcionamento bivolt automático * Iluminação em branco frio com ótima visibilidade * Baixo consumo de energia * Ideal para emergências e uso diário * Compacta, portátil e fácil de instalar * Excelente vida útil dos LEDs Daquelas coisas que ninguém lembra… até faltar energia. Aí vira protagonista. 💡', 120.0, 37.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4ze9vonguog0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1137412789%2F22297668595', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
