INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497682787', 'Bermuda Compressão Feminina HUPI Run Longa Colors', 'Bermuda Compressão Feminina HUPI Run Longa Colors É fundamental estar equipado com roupas e acessórios apropriados ao praticar esportes, pois eles desempenham um papel crucial em nossa performance. Na HUPI, contamos com corredores e ciclistas em nossaequipe para testar e avaliar nossos produtos, garantindoqualidade e eficiência. Nossa Bermuda HUPI foi desenvolvida emPoliamida e Elastanopara proporcionarconforto e segurançaao corredor. Versátil para qualquer competição, seja de longa duração ou treinos intensos, suacompressão auxilia na prevenção de lesões musculares. A Bermuda HUPI também oferece praticidade com seusdois bolsos ergonômicos bilaterais, ideais para armazenar suplementos, dinheiro, chaves, entre outros itens essenciais durante a corrida. Além disso, você pode praticar suas atividades físicas com tranquilidade, pois a bermuda possuiproteção solar UV50+e um tecido que proporciona umencaixe firme ao corpo,sem transparênciasindesejadas esem marcar. Aprimore sua performance com abermuda para corridaHUPI Run. Características: Tecido 77% Poliamida| 23% Elastano; Bermuda para corrida de compressão; Proteção solar UV50+ ; Bolsos Ergonômicos bilaterais; Sem transparência. Referência de Tamanho: Tamanho P: Veste 34 Tamanho M: Veste 36 Tamanho G: Veste 38/40 Tamanho GG: Veste 42/44', 272.68, 199.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-7rdvf-lyawgfdviluwec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524728336%2F22497682787', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
