INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198561663', 'Kérastase Elixir Ultime Bain Shampoo 250ml', 'Shampoo de limpeza composto por Óleo de Camélia e Óleo de Marula que remove impurezas e purifica o cabelo, proporcionando um brilho radiante e duradouro. * RESULTADO: Nutrição Brilho * SUGESTÕES DE USO: 1.Umedeça os fios, retire o excesso de água, aplique 5ml do Le Bain; 2.Massageie o couro cabeludo com as pontas dos dedos para eliminar as impurezas; 3.Enxágue bem. * OBSERVAÇÕES: Imagem Meramente Ilustrativa * ITENS INCLUSOS: 1 Kérastase Elixir Ultime Bain Shampoo 250ml', 292.9, 241.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rdye-mddjlhxlskzyc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F23198561663', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992844462', 'Bioderma Sébium Moussant Actif Gel de Limpeza Facial 500ml', 'Gel de Limpeza Facial Bioderma Sébium Moussant Actif reduz a acne e respeita profundamente a barreira natural da pele, combina dois ativos renovadores, que limpam e purificam a pele acneica sem ressecar. Aumenta a resistência da pele contra as agressões externas. * RESULTADO: Desobstrui poros e reduz a acne. * SUGESTÕES DE USO: 1.Aplicar na pele molhada; 2. Massageie até virar uma espuma leve e enxágue gentilmente; 3. Usar manhã e/ou noite. * ITENS INCLUSOS: 1 Bioderma Sébium Moussant Actif Gel de Limpeza Facial 500ml', 149.9, 149.9, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134201-7rce0-lrsu5obg30nkf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F22992844462', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18099440189', 'Lâmpada De Led Par20 7W 4000K Bivolt Avant', 'SOBRE O PRODUTO A Lâmpada de LED Par20 7W 4000K Bivolt da Avant é uma excelente opção para iluminação residencial ou comercial. Com uma temperatura de cor de 4000K, proporciona uma luz branca neutra, ideal para ambientes como escritórios, lojas ou áreas de trabalho. Com baixo consumo de energia e funcionamento bivolt, oferece economia e versatilidade. Além disso, a tecnologia LED garante uma vida útil longa e baixa emissão de calor, tornando-a uma escolha sustentável e eficiente para iluminar diversos espaços. DIFERENCIAIS - Tecnologia LED - Base Bivolt - Iluminação Direcional - Potência de 7W GARANTIA 1 Ano SOBRE A FABRICANTE A AVANT é uma empresa genuinamente brasileira, especializada em produtos para iluminação e posicionada entre as maiores empresas do segmento. É reconhecida pela excelência e qualidade de seus produtos e por manter uma grande e sólida parceria de longo prazo com seus clientes. Está presente em todos os estados brasileiros, com uma estrutura de profissionais aptos e experientes, prontos para atender as diversas necessidades de seus clientes, com eficiência e comprometimento. Prestigiada por profissionais e consumidores, é considerada pioneira no lançamento de produtos modernos e inovadores, presente na diversidade e qualificação de seu portfólio.', 25.9, 25.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rdxe-m036bjmzb6dcd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1225401015%2F18099440189', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
