INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23292646656', 'Cuba Sobrepor banheiro de cerâmica Berlim - Mármore sintético', 'CUBA BANHEIRO SOBREPOR Nome modelo: BERLIM Cuba quadrada moderna, amplo espaço interno. Possui furo para válvula e torneira - Excelente escoamento de água e desenvolvida para evitar respingos * Excelente acabamento, sendo muito resistente a riscos ou manchas DESCRIÇÃO CUBA: Matéria-Prima: Mármore Sintético (cerâmica) - textura em louça Comprimento externo: 39 cm / Largura: 32 cm / Altura: 12 cm . Diâmetro do Furo para Torneira: (32mm) - DN 32 . Diâmetro do Furo para Válvula: 1.1/2" (35mm) - DN 35 COR: Branco Peso : 7 kg ITEM INCLUSO: 1 Cuba Sobrepor As cubas vão muito bem embaladas, possuindo uma embalagem própria de acordo com as dimensões do produto, incluindo caixa de papelão duplo, plástico bolha e cintas de papelão duplo para travar a cuba dentro da caixa, impedindo assim que ocorra avarias pelo transporte.', 259.9, 189.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lo7ekgysndexc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413779333%2F23292646656', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792795559', 'Sandalia Ortopedica Modare Conforto Anabela Leve Feminina Original', 'CABEDAL: Sintético FORMA: Normal PALMILHA: Super macia com enchimento em EVA SALTO: 4cm SOLADO: PVC Antiderrapante ENVIO: Na caixa do fabricante GARANTIA: Contra defeitos de fabricação - 30 dias A Sandália Modare Ultraconforto Ortopédica é uma peça de calçado que se destaca não apenas pelo seu design elegante, mas também por proporcionar um nível excepcional de conforto e suporte aos pés. Esta sandália oferece uma experiência única, unindo moda e bem-estar de forma equilibrada, ideal para você que sofre com fascite plantar, esporão e dores nos pés. Confeccionada em material sintético de alta qualidade. O destaque fica para as duas fivelas estrategicamente posicionadas no cabedal , que além de trazer modernidade para o design, confere maior praticidade ao calçar, permitindo um ajuste personalizado e seguro, garantindo maior estabilidade durante o uso. Conta com a tecnologia Ultracomfy, que consiste em sua palmilha ultramacia de 6,5 mm confeccionada em EVA que acomoda o pé de forma anatômica, garantindo maior conforto e estabilidade. Com design super moderno, a sandália apresenta uma plataforma de 4 cm, que proporciona altura com estabilidade, conferindo um toque de sofisticação ao visual. O formato do salto é projetado ergonomicamente para distribuir o peso de maneira uniforme, contribuindo para minimizar a pressão sobre os pés, proporcionando conforto durante todo o dia. Seu solado conta com frisos antiderrapantes, garantindo maior segurança ao caminhar. TABELA DE MEDIDAS Tamanho 33 - 23cm Tamanho 34 - 23.5cm Tamanho 35 - 24cm Tamanho 36 - 24.7cm Tamanho 37 - 25.9cm Tamanho 38 - 27cm Tamanho 39 - 27.8cm Tamanho 40 - 28.5cm', 162.95, 79.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Health Slippers', 'https://cf.shopee.com.br/file/sg-11134201-7rbl0-lqkyepphmt6ta0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F591297390%2F23792795559', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20397987116', 'Kit 2 Pack Repelente Elétrico Líquido Exposis Casa 32,9ml + Refil', 'O kit contém 2 Pack com Repelente Elétrico Líquido Exposis Casa 32,9ml + Refil cada. Exposis Casa é o repelente de insetos para ambientes da marca mais recomendada por médicos. Possui alta eficácia e é a solução ideal para proteger sua família contra mosquitos causadores de doença como Dengue, Zika e Chikungunya. Fornece até 4 semanas de proteção para sua casa. Abra a tampa do refil e introduza no aparelho, evitando tocar no pavio. Ajuste a intensidade de liberação desejada, arrastando o botão no aparelho. Coloque o aparelho na tomada 30 minutos antes de dormir e deixe sempre uma porta ou janela aberta para repelir os mosquitos. Sempre utilize o aparelho na posição vertical. Para proteção durante toda a noite, deixe o aparelho na menor potência. Para desligar, retire o conjunto da tomada. Utilize apenas um aparelho para cada espaço de 10m quadrados.', 100.49, 100.49, NULL, 'Health > Personal Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rffp-m30rokewc6g799', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819102498%2F20397987116', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
