INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593972379', 'Volante Caminhão Van Iveco 35S14 45S17 55C16 55C17 70C17', 'Oferecemos durabilidade e resistência incomparáveis. Nossos volantes foram projetaods para oferecer máxima segurança, garantindo aderência firme e conforto, proporcionando controle absoluto em todas as suas viagens. CONTEÚDO DA EMBALAGEM: • Volante Esportivo Personalizado; • Diâmetro de 370mm; • Cubo Adaptativo; • Emblema; • Parafusos para instalação. COMPATIBILIDADES: • Iveco Daily 2008 Em Diante EXCLUSIVIDADE • Qualidade superior em poliuretano: Volantes com toque macio, controle preciso e resistência excepcional, graças ao poliuretano de alta tecnologia e cubos metálicos que garantem segurança e durabilidade. • Personalização única: Volantes em diversas cores e compatibilidades, ideais para realçar o estilo e a personalidade do seu carro. • Atendimento especializado: Se não encontrar seu modelo em nossa descrição, entre em contato com nossa equipe e nós ajudaremos a encontrar a solução ideal para você. IMPORTANTE: • Verifique a compatibilidade do anúncio com seu veículo. Tire suas dúvidas ANTES da compra. • Entrega rápida: Compras realizadas hoje serão despachadas no próximo dia útil. • Recomendamos a instalação por um profissional. • A instalação dos nossos volantes resulta na perda da funcionalidade do airbag. Eleve a experiência ao dirigir com nossos volantes', 299.99, 240.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rfhf-m9kgqkwmb6hu9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F954535653%2F23593972379', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398916701', 'Serra copo diamantada 50 mm para esmerilhadeira M14 - Cortag', 'Produto: Serra copo diamantada 50 mm para esmerilhadeira M14 Marca: Cortag Descrição: A Serra Copo Diamantada 50 mm para Esmerilhadeira M14 da Cortag" é ideal para projetos de construção e reforma! Projetada especialmente para furar com alta precisão materiais duros e delicados como porcelanato, cerâmica, granito e mármore, esta serra-copo é uma ferramenta indispensável para profissionais e amadores que buscam resultados de alto nível. A tecnologia diamantada de última geração garante um corte limpo e sem lascas, preservando a beleza e a integridade do material trabalhado. Além disso, a Serra Copo da Cortag oferece uma performance duradoura e constante, mesmo sob os mais rigorosos usos. Características: • Fácil instalação na esmerilhadeira com rosca M14, adequando-se perfeitamente Ã s ferramentas mais usadas no mercado. • Diâmetro de 50 mm, ideal para trabalhos que exigem precisão em cortes de pequeno porte. • Durabilidade excepcional, graças Ã alta qualidade dos materiais diamantados usados na fabricação da serra. • Reduz significativamente o risco de quebra ou trinca dos materiais, oferecendo uma performance segura e eficiente. Especificações: Diâmetro da serra copo: 50 mm Indicado para perfurar materiais como: Porcelanatos, cerâmicas, granitos e mármore Tipo da rosca: M14 Material da serra copo: Corpo metálico com dentes diamantados. Dimensões (C x L x A): 5.00 x 6.00 x 6.00 centímetros Peso: 0.24 Kg', 218.16, 218.16, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-82593-mr30l1s9064s47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F23398916701', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694339176', 'Tapete Bandeja FastBack 5 Peças Tpe Flexível 2022/2026', 'Tapete Tipo Bandeja para Fiat Fastback 2022 em diante 5 Peças GRID Acessórios Este jogo de tapetes tipo bandeja é a escolha ideal para quem busca proteção completa, durabilidade e encaixe perfeito no Fiat Fastback. Produzido pela GRID Acessórios, marca nacional com mais de 20 anos de experiência no setor automotivo, o kit oferece alta qualidade e acabamento impecável. Compatibilidade • Fiat Fastback 2022 em diante • Não compatível com Fastback Hibrido Especificações • Marca GRID Acessórios • Material TPE Flexível resistente ecológico e de fácil limpeza • Cor Preto Conteúdo da embalagem • 2 tapetes dianteiros • 2 tapetes traseiros • 1 tapete para túnel central Diferenciais do produto • Produzido em TPE flexível resistente à água lama e desgaste • Design tipo bandeja com bordas elevadas que impedem vazamentos e protegem o carpete original • Encaixe sob medida sem necessidade de adaptações • Fácil de limpar e com longa vida útil Produto fabricado pela GRID Acessórios referência nacional em acessórios automotivos com compromisso com a qualidade e sustentabilidade. Adquira agora e preserve o interior do seu Fiat Fastback com segurança e sofisticação.', 417.99, 359.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Mat', 'https://cf.shopee.com.br/file/br-11134207-820lb-mqi1cpyiwsuaa6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1101226660%2F22694339176', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
