INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294960486', 'Água Sanitária Super Cândida', 'Super Cândida é a água sanitária ideal para a limpeza e desinfecção da sua casa, eliminando germes e bactérias. * Alvejamento de roupas: adicione 1 copo (200ml) para cada 20 litros de água, deixando de molho por 30 minutos. * Limpeza geral: adicione 1 copo (200ml) para cada 5 litros de água em banheiros, cozinhas, pisos, pias, azulejos e paredes. Enxágue após 10 minutos. * Desinfecção de frutas, verduras e legumes: misture 1 colher de sopa (15ml) em 1 litro de água. Deixe de molho por 10 minutos e enxágue. * Combate a larva do mosquito Aedes Aegypti: misture 2ml em 1 litro de água e despeje nos locais que reservam água parada.', 8.49, 8.49, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-825a4-mqnem3p80f0h6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555155%2F22294960486', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794043804', 'Dry Rub Pork - Porco', 'Dry Rub Dry Rub é uma mistura de temperos secos que é aplicada para dar sabor às carnes antes de irem ao forno, grelha ou churrasqueira. Sucesso nos churrascos norte americanos! Ao aplicar o tempero dry rub em uma carne é necessário cobrir todo o exterior da carne com uma camada do condimento e deixar por algumas horas descansando. Essa crosta de especiarias que fica ao entorno da carne potencializa o seu sabor e ajuda a reter todo o seu suco deixando a carne ainda mais suculenta. O Dry Rub Porco foi criado exclusivamente para dar mais sabor e textura a qualquer tipo de carne suína. Dry Rub Receita - Porco Para utilizá-lo basta aplicar o produto na carne antes dela ser defumada, assada ou grelhada, massageando-a para que o tempero penetre e cubra toda a sua superfície. Faça uma camada generosa nos dois lados das costeletas de porco, embrulhe em papel alumínio e coloque em um recipiente no forno a 200 graus por 2 horas. Tire o alumínio e deixe até dourar entre 30 a 60 minutos. Utilize em qualquer tipo de carne de suína e experimente essa explosão de sabor! Ingredientes: especiarias, açúcar e sal. Informações adicionais: Não contém glúten.', 33.9, 33.9, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/sg-11134201-8258q-mqz6zlykq3gh89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1484422644%2F22794043804', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
