INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393182289', 'Capacete Race Tech Sector Monsters Azul', 'Famosas pelas jaquetas de alta qualidade com excelente custo/benefício, a RACE TECH tem o prazer de apresentar o SECTOR, novo capacete da marca que chega ao mercado brasileiro. Fabricado em ABS de alta pressão, o SECTOR tem entradas de ar ajustáveis integradas com o EPS de multidensidade para elevar o conforto do motociclista. Características: • Pensado urbano e rodoviário leve, pesa apenas 1.450g (+-50); • A viseira de 2,2 mm recebe tratamento UV e anti-risco para maior vida útil; • O sistema de troca é rápido, visando a praticidade e agilidade necessária no dia a dia; • A forração removível e lavável recebe inserções refletivas e tratamento antialérgico; • Bavete removível, narigueira alta e fecho micrométrico de fácil acesso mesmo com luva.', 521.88, 521.88, NULL, 'Spare Parts and Accessories for Vehicles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdxf-ly3w8qpq8fznb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F806887225%2F22393182289', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594398357', 'Kit 3 Protetor Labial Mió Sabor Morango Shine 3,6g', 'Protetor Labial Mió Morango Shine O Mio Protetor Labial Morango Shine hidrata, nutre e restaura a suavidade dos lábios. Fórmula elaborada com Manteiga de karité e Vitamina E para deixar os lábios sempre macios a qualquer hora do dia. Possui um delicioso aroma de morango, além de proporcionar brilho e cor delicada aos lábios. Modo de uso: Aplicar diariamente o produto sobre os lábios para manter a hidratação. Reaplicar sempre quando necessitar de hidratar os lábios, mantendo-os saudáveis e protegidos.', 49.87, 49.87, NULL, 'Beauty > Skincare > Lip Treatment', 'https://cf.shopee.com.br/file/sg-11134201-825b2-mqmo6vlyt5osf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23594398357', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21098323252', 'Tapete Infantil Mosaico Almofadado Para Quarto 218x100cm Azul Marinho Keiko Colchões', 'Tapete Keiko Mosaico Almofadado Infantil — o “match” perfeito da Cama Montessoriana. Macio, estável e acolhedor, cria uma área segura para explorar, brincar e ler no quarto infantil. Visual em mosaico que harmoniza com o décor, toque fofinho, base firme e limpeza fácil. Mais conforto, mais segurança, mais autonomia — no mesmo ecossistema Montessori da Keiko. -Autonomia que se estende ao chão: O Tapete Keiko Mosaico Almofadado cria uma zona de brincar macia e segura no nível da Cama Montessoriana, complementando a decoração do quarto. -Design em mosaico. Conforto que performa: Seguro por ser almofadado e antiderrapante, seu design em mosaico adiciona funcionalidade e beleza ao quarto infantil. -Acolchoado integral. Bordas reforçadas: Projetado para a rotina infantil, oferece conforto para atividades no chão e seu formato delimita a área de uso, criando um layout coeso com a Cama Montessoriana Keiko. -Feito para a infância real: Prático e leve, cria um circuito de uso junto à cama que incentiva a autonomia da criança e a tranquilidade dos pais. Dimensões: Comprimento: 100 cm Largura: 218 cm Altura total: 2 cm Materiais: Espuma: D28 Revestimento em tecido premium Suporta Até 80kg', 629.9, 499.0, NULL, 'Home & Living > Decoration > Carpets & Rugs', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfu6qi3cp69se7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1374188221%2F21098323252', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251994159', 'Pilão Tradicional Café Torrado e Moído', 'O Café Pilão Tradicional é conhecido por seu sabor forte e encorpado, ideal para o dia a dia. Com torra acentuada e moagem fina e uniforme, preserva seu sabor característico. Intensidade 8.', 34.49, 34.49, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/sg-11134201-8259h-mqnem3jdjnr65b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555155%2F58251994159', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19898994191', 'Tintura Keraton Selfie 12.11 Louro Especial Cinza Intenso', 'Keraton Selfie buscou usar em sua formulação o Óleo de Macadâmia que é rico em Ômega 3 e 7 que hidrata e reconstrói o fio, criando um condicionamento de longa duração Cistina (a parte mais rica da Queratina), que age de fora para dentro da fibra capilar protegendo-a da perda da elasticidade. Com isso, os cabelos ficam macios, maleáveis, saudáveis e brilhantes. Cores de longa duração e 100% de cobertura. Modo de Uso Faça a prova de toque e o teste de mecha antes da aplicação. Siga as instruções da embalagem. #html-body [data-pb-style="646BA6464DD99"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA6464DDAE"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}#html-body [data-pb-style="646BA6464DDBE"]{font-weight: 400;}#html-body [data-pb-style="646BA6464DDCD"]{font-weight: 400;}#html-body [data-pb-style="646BA6464DDDC"]{font-weight: 400;}#html-body [data-pb-style="646BA6464DDF4"]{font-weight: 400;}', 25.87, 25.87, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rbly-lmggxqoz2g9ce6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F19898994191', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897723016', 'Sapatilha Esportiva Kolosh C3101A', 'Produto marca Kolosh. A nova coleção Kolosh entrega conforto combinado com muita informação de moda, podendo compor os mais lindos looks! De olho nas novas tendências de moda, a nova sapatilha bailarina chega com um design que esbanja delicadeza e versatilidade, com seu calce facilitado pela tira no peito do pé, com detalhe em seu ilhós metalizado garantindo modernidade e elástico lateral permitindo um perfeito ajuste no pé. Além disso, conta com o adicional da almofada de calcanhar atuando no maior conforto ao andar, junto da aplicação do pin metalizado da marca na lateral do produto, conferindo um toque moderno. Conta com a Palmilha Impulse de memória inteligente, que adapta-se perfeitamente no formato do pé e proporciona um andar cheio de leveza o dia todo, aliada ao seu solado em Trbicolor feito em material antiderrapante, que traz maior aderência e segurança na pisada, além de manter a temperatura térmica o dia todo! Peso: 0,554 kg Altura da sola: 4,00 cm Altura do salto: 1,0 cm', 189.9, 189.9, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-82611-mlwg85rwwq2w0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F23897723016', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18598990532', 'Esmalte Impala Bailarina Plie', 'Esmaltes Impala trazem o que há de mais tecnológico, de maior qualidade e inspirados nas últimas tendências para que suas mãos, seus pés e principalmente você, possam estar sempre bem. Todos possuem ação duradoura e brilho prolongado. Modo de uso: Com as unhas limpas, aplique uma ou duas camadas do esmalte, de acordo com a intensidade desejada. #html-body [data-pb-style="646BA64B196F3"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-size: Cover; background-attachment: Scroll; border-style: None; border-width: 1px; border-top-left-radius: 0px; border-top-right-radius: 0px; border-bottom-right-radius: 0px; border-bottom-left-radius: 0px; margin: 0px 0px 10px; padding: 10px; background-position: Left top; background-repeat: No-repeat no-repeat;}#html-body [data-pb-style="646BA64B19708"]{border-style: None; border-width: 1px; border-top-left-radius: 0px; border-top-right-radius: 0px; border-bottom-right-radius: 0px; border-bottom-left-radius: 0px; margin: 0px; padding: 0px;}', 15.03, 15.03, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7rble-lmg3tu1vvya399', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F18598990532', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21598993896', 'Cortador De Unha Marco Boni 1890PG', 'O Cortador de Unhas Marco Boni é feito de aço niquelado, indicado para uso no dia-a-dia. Possui chaveiro e lima. Modo de uso: Com cuidado, posicione o cortador em um ângulo e corte só um pouco de suas unhas de cada vez. Para cortar as unhas das mãos, prefira um cortador menor. Já para as unhas dos pés, prefira um cortador maior. #html-body [data-pb-style="646BA648F0417"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA648F042B"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 16.5, 16.5, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbnd-lmg96fz2xk6203', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F21598993896', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
