INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41278726899', 'ALISANTE HENÊ PELÚCIA FORTE POUCH 180G EMBELLEZE - 3 UNIDADES (EMBALAGEM NOVA)', 'ESSE KIT CONTÉM: 3 ALISANTE HENÊ PELÚCIA FORTE POUCH EMBELLEZE 180G INDICAÇÃO Antes de usar, faça a Prova de Toque. Aplique uma pequena quantidade do produto no antebraço e atrás da orelha. Deixe na pele por 60 minutos, lavando-a em seguida. Após ter lavado, aguarde 24 horas. Se nesse período surgir irritação na pele, coceira ou ardência no local ou na proximidade, fica provada a hipersensibilidade. Nesse caso, NÃO use o produto. AÇÃO Alisa e tinge de preto. ATIVOS Azeite de Oliva Preto. BENEFÍCIOS Óleo de oliva tem ação hidratante e nutritiva que ajuda na flexibilidade natural e brilho dos cabelos. RESULTADO Cabelão liso escorrido, preto e com brilho pra lacrar MODO DE USO 1 - Aplique o Henê Pelúcia, mecha por mecha. 2 - Puxe com pente fino, da raiz às pontas, esticando bem os fios. Cubra com uma touca plástica por 60 minutos (o efeito será o mesmo se o tempo for maior). 3 - Enxágue bem os cabelos e lave-os com shampoo e condicione. 4 - Se você quer um efeito bem liso, pode fazer uma escova. E se você quer um penteado ondulado, é só deixar os cabelos secarem em bobs. 5 - Aconselhamos 2 aplicações por semana até atingir o resultado desejado.', 59.7, 54.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8260a-mklcd6ev1bluf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F41278726899', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201384332', 'Par Bucha Barra Estabilizadora Ford New Fiesta Sedan 2011 a 2013', '2x C1BC5484BB Par Bucha Barra Estabilizadora Ford New Fiesta Sedan, 2011/2013, 1.6 16V Flex - 115cv Ford New Fiesta Sedan, 2016/2017, 1.6 16V Flex - 128cv Ford New Fiesta Sedan, 2014/2015, 1.6 16V Flex - 130cv Catálogo de Aplicações GoParts DUVEL FORD - DISTRIBUIDOR OFICIAL FORD Os produtos já seguem com a sua nota Fiscal #NF Produto novo, original e sem uso. Disponível á pronta entrega, envio imediato Por gentileza, se houver dúvidas da utilização do produto entre em contato conosco antes de efetuar a compra no campo de "Perguntas" Assim evitaremos futuros transtornos. Pedidos com CPF(Pessoa Física) dentro do Estado do Maranhão. Todos os nossos produtos são originais, com embalagem Ford. Todos os produtos tem garantia direto da Ford. Temos os produtos a pronta entrega. Verifique se seu endereço está correto no cadastro do Shopee antes de efetuar a compra. Todos os pedidos vão acompanhados com a nota fiscal em nome do CPF de quem efetuou a compra. Nosso horário de atendimento é de Seg à Sexta das 8:00 às 18:00 e sábado de 8:00 às 12:00', 52.47, 52.47, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rdvy-mco1pyqndeab59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1685347172%2F58201384332', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
