INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18599251160', 'Carrinho Mickey Fofomovel Vinil Macio Lider Brinquedos', 'O Fofomóvel Minnie da Líder Brinquedos é perfeito para encantar os pequenos com muita diversão. Inspirado na personagem Minnie, o brinquedo possui design colorido e divertido, ideal para estimular a imaginação e acompanhar as primeiras brincadeiras das crianças. Produzido em material atóxico, combina vinil e plástico, garantindo segurança e resistência durante o uso. Indicado para bebês a partir de 4 meses, é um brinquedo lúdico que ajuda no desenvolvimento sensorial e na interação durante a brincadeira. CARACTERÍSTICAS: - Marca: Líder Brinquedos - Modelo ou Referência: 2882 - Material: Vinil atóxico e plástico atóxico - Idade recomendada: +4 meses - Peso: 1228 g - Medidas da embalagem: 22cm x 27cm x 24 cm (C x L x A) - Conteúdo da embalagem: 1 fofomóvel Minnie - INMETRO: CE-BRI/IQB 00275552668', 129.99, 129.99, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lv2agpc2ak5r21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406894684%2F18599251160', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
