INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18451695341', 'Jogo Match Color Multikids - BR1677', 'Momentos de diversão são garantidos com o jogo Match Color da Multikids! Seja o mais rápido a replicar as cores no tabuleiro! Balance o dado para revelar um padrão de 9 cores que deve ser rápida e corretamente replicada pelos jogadores no tabuleiro, deslizando uma peça por vez. O jogador que replicar primeiro deverá abaixar a tampa do tabuleiro, gritar Match Color! e se consagrar o vencedor! Habilidade e rapidez em um jogo divertido, colorido e estratégico. - Não utiliza pilhas. - Quantidade de Jogadores: 2 jogadores - Estimula a concentração, agilidade e reconhecimento de cores pelas crianças. Ficha Técnica Marca: Multikids Modelo: BR1677 Cor: Multicolor Faixa etária: +5 anos Desenvolvimento: Motor Largura do produto: 26.0cm Altura do produto: 20.0cm Peso do produto: 400.0g Comprimento do produto: 42.0cm Composição do Material: Plástico, Acrílico Conteúdo da Embalagem: 1 Jogo Match Color com 70 peças Multikids - BR1677 * Imagens meramente ilustrativas. *', 120.89, 109.9, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/de67e77801012de35a8a0bda67c15949', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389315825%2F18451695341', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19298038283', 'Kit 3 Fralda Infantil Turma da Mônica Baby Mega Tamanho M 50 Fraldas Descartáveis', 'Fralda Infantil Turma da Mônica Baby Mega Tamanho M A Turma da Mônica Baby uniu proteção e conforto em uma nova opção de fralda, para garantir que seu bebê cresça feliz e tenha as melhores lembranças da sua infância. A Nova fralda Turma da Mônica Baby possui a nova Tecnologia QuatroSec para que ele fique calmo, tranquilo e seguro durante o dia e a noite toda. Conta com um exclusivo sistema de canais que distribui mais rápido o xixi, barreiras anti-vazamento e uma fina camada extra que ajuda a manter o bebê sequinho por até 12 horas, além de cintura elástica que proporciona um perfeito ajuste no corpinho. A Nova fralda Turma da Mônica Baby possui a nova Tecnologia QuatroSec; com um exclusivo sistema de canais que distribui mais rápido o xixi, barreiras anti-vazamento e uma fina camada extra que ajuda a manter o bebê sequinho por até 12 horas, além de cintura elástica que proporciona um perfeito ajuste no corpinho. A Turma da Mônica Baby é uma marca de excelência no mercado de fraldas infantis há mais de 25 anos. A marca e sua turma estão presentes no coração dos brasileiros há mais de 3 gerações, e agora também faz parte do portfólio da Ontex. Os novos produtos foram pensados e elaborados para as mamães e os papais que, assim como nós, valorizam a tradição e os valores culturais aprendidos na infância, alinhado com o conforto e a qualidade dos produtos Turma da Mônica para seu bebê. Modo de uso: 1. Coloque o bebê sobre a fralda aberta com as fitas na parte traseira. 2. Abra as fitas agarradinhas e ajuste a fralda no corpinho do bebê posicionando as fitas sobre a faixa frontal branca.', 158.37, 158.37, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-823oz-mp4hsd3200e90c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F19298038283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
