INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799610402', 'Kit 2 Shampoo Nutri Preenchedor L''Oréal Paris Elseve Cachos Longos dos Sonhos 400ml', 'Shampoo L''Oréal Preenchedor Elseve Cachos dos Sonhos 400ml Sonha com cachos longos, fortes e definidos O Shampoo Nutri Preenchedor de L’Oréal Paris Elseve Cachos dos Sonhos limpa as impurezas e preenche o cabelo com nutrição profunda até as pontas, para cachos mais longos, fortes e definidos desde o primeiro uso. Tecnologia Sua fórmula trata e sela os fios até as pontas para salvar os últimos 3 cm dos seus cachos. Com Ácido Hialurônico preenche a fibra capilar com hidratação profunda e Óleo de Rícino que nutre profundamente e sela os fios até as pontas fortalecendo e definindo os cabelos. Testes instrumentais, uso conjunto do shampoo + condicionador + creme para pentear. Benefícios: - Limpa as impurezas e preenche o cabelo com nutrição profunda até as pontas. - Fórmula que trata e sela os cachos até as pontas para salvar até os últimos 3 cm dos seus cachos. - Com Ácido Hialurônico e Óleo de Rícino.', 69.98, 69.98, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-823oa-momumm02urcx18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F19799610402', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
