INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14109707998', 'Quebra Cabeça Puzzle 60 Peças Barbie 04172 - Grow', 'DESCRIÇÃO DO PRODUTO Não deixe de brincar e se divertir com este quebra-cabeça! São 60 peças, para você encaixar uma a uma até formar uma linda imagem. Mais que um passatempo divertido, os quebra-cabeças desenvolvem o raciocínio, relaxam e se transformam num autêntico hobby. CARACTERÍSTICAS TÉCNICAS Conteúdo da Embalagem: 60 peças Dimensões Aproximadas do Produto: 30,8 x 22,4 cm (Altura x Largura x Comprimento/Profundidade) Dimensões da Aproximadas da Embalagem: 23 x 15 x 7 cm (Altura x Largura x Comprimento/Profundidade) Material/Composição: Papel Cartão Idade Mínima Recomendada: A partir de 4 anos Marca: Grow Referência: 04172 Garantia: 3 meses contra defeitos de fabricação Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto 100% original, lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 38.31, 33.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/b068e2e44ee6941d214575c797c35a80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F14109707998', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23099045786', 'Tapete Bandeja Kicks Modelo G1 5 Peças Tpe Flexível 2016 Até 2025', 'Tapete Tipo Bandeja para Nissan Kicks (2016 a 2021) – 5 Peças | Fabricado pela GRID Acessórios Proteja o interior do seu Nissan Kicks com este jogo de tapetes tipo bandeja desenvolvido pela GRID Acessórios, marca reconhecida há mais de 20 anos pela qualidade e durabilidade de seus produtos automotivos. Feito sob medida, o kit oferece encaixe perfeito, acabamento premium e máxima proteção contra sujeira, líquidos e desgaste. Compatível com: Nissan Kicks (2016 a 2021 – modelo antigo) Marca: GRID Acessórios Material: TPE Flexível – resistente, ecológico e de fácil limpeza Cor: Preto Conteúdo da embalagem: • 2 tapetes dianteiros • 2 tapetes traseiros • 1 tapete para túnel central Diferenciais do produto: • Produzido em TPE flexível, resistente à água, lama e abrasão • Design tipo bandeja com bordas elevadas, evitando vazamentos e protegendo o carpete original • Encaixe sob medida, sem necessidade de cortes ou adaptações • Fácil limpeza e longa durabilidade • Material ecologicamente correto e livre de odores Produto fabricado pela GRID Acessórios, referência nacional em acessórios automotivos, com compromisso com qualidade, tecnologia e sustentabilidade. Garanta agora o Tapete Tipo Bandeja GRID e mantenha seu Nissan Kicks sempre limpo, protegido e com visual sofisticado. Garantia de fábrica: 3 meses', 417.99, 329.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Mat', 'https://cf.shopee.com.br/file/br-11134207-820mh-mqm7v0nsgqv4f2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1101226660%2F23099045786', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
