INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49400976025', 'Lovito Kids Vestido Boho de Boa Textura para Primavera/verão Vestido Azul para menina L162LD200', '✅DESTAQUES -❤️Básico -❤️Boa Textura -❤️Primavera e verão -❤️Cintura elástica ✅DESCRIÇÕES Estampa / Padrão:Floral Estilo:Boho Tipo de vestido:alargado Tamanho Plus:Não Material:Poliéster Composição:95% Poliester + 5% Elastano Tipo de modelagem: Corte Reto Transparência:Não Esticar:Não elástico Feito na China ✅O PACOTE INCLUI 1XVestir ✅INTRODUÇÃO LOVITO A Lovito é uma marca em crescimento que acredita no poder das meninas. Estamos comprometidos em oferecer opções de roupas fashion e acessíveis, para todos os estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, liberadora e fazer você se sentir incrível. Afinal, o melhor acessório para qualquer look é a autoconfiança! ✅NOTAS DE COMPRA Antes de comprar, dê uma olhadinha na tabela de medidas disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, converse conosco e responderemos o mais rápido possível.😊', 48.0, 33.5, NULL, 'Baby & Kids Fashion > Girl Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-824hq-mpxi5ksx85qmd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1651638006%2F49400976025', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
