INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259234571', 'Freezer e Geladeira Portátil EOS 50 Litros Dupla Ação Quadrivolt Preto EFC50 110V/220V/12V/24V', '❄️ Freezer e Geladeira Portátil EOS 50 Litros Dupla Ação Quadrivolt Preto EFC50 🚗🏕️ Mais praticidade, mobilidade e eficiência para suas viagens, campings e uso diário! O EOS EFC50 oferece excelente capacidade interna, resfriamento rápido e funcionamento versátil, podendo ser usado como freezer ou geladeira portátil. ✨ Destaques do Produto: ✅ Capacidade de 50 Litros ✅ Função freezer e geladeira portátil ✅ Modos de resfriamento e congelamento ✅ Compressor DC de alta eficiência ✅ Resfriamento rápido e estável ✅ Quadrivolt: 110V / 220V / 12V / 24V ✅ Compatível com baterias externas ✅ Modo ECO para economia de energia ✅ Sistema inteligente de proteção da bateria em 3 níveis ✅ Memória de configuração após queda de energia ✅ Iluminação interna em LED ✅ Rodas grandes e alça retrátil para transporte fácil ✅ Dreno inferior para limpeza prática ✅ Proteção contra superaquecimento ✅ Design moderno, robusto e funcional 📏 Medidas (LxAxP/cm): 65,5 x 53 x 44 cm 🚙 Ideal para viagens, camping, motorhome, pescarias e uso profissional, garantindo praticidade e refrigeração eficiente em qualquer lugar.', 1857.91, 1857.91, NULL, 'Home Appliances > Kitchen Appliances > Freezers', 'https://cf.shopee.com.br/file/sg-11134201-820nx-mnaegomrah38c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1527564302%2F58259234571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
