INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22108389843', 'Suporte Baú 80 Litros Removível Biz 125 2006/2010', 'O Suporte de Baú 80 litros Removível BIZ 125 2006 à 2010 Pro Tork é fabricado com matéria-prima de alta qualidade, garantindo máxima resistência. Especificações: - Indicado para Baús de 80 Litros; - Cor: Preto; - Modelo: Removível; - Desenvolvido em chapas de aço altamente reforçadas; - Oferece a possibilidade de retirar o suporte afrouxando quatro parafusos borboleta; - Produto de fácil instalação; - Foto Ilustrativa; - Marca: Pro Tork. Aplicação: - BIZ 125 2006; - BIZ 125 2007; - BIZ 125 2008; - BIZ 125 2009; - BIZ 125 2010; Instalação: - A instalação deve ser feita por um profissional especializado. A Sportbay não se responsabiliza por instalação mal realizada.', 168.32, 127.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Cases', 'https://cf.shopee.com.br/file/sg-11134201-22110-m6soh9iipikv31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F22108389843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394011946', 'Escapamento Escape Power Cromo Forte Honda Biz 100 1998 Até 2005', 'O Escapamento Power Cromo Forte Biz 100 De 1998 - 2005 Eles são produzidos com materiais de excelente qualidade, garantindo maior vida útil ao produto, resistindo por muito mais às ações do tempo, tornando assim o melhor custo beneficio do mercado. Aplicação: - Biz 100 1998; - Biz 100 1999; - Biz 100 2000; - Biz 100 2001; - Biz 100 2002; - Biz 100 2003; - Biz 100 2004; - Biz 100 2005. Instalação: - Produto É Pronto Para Instalação E Não Necessita De Nenhum Tipo De Adaptação; - Para Realizar A Instalação, Leve Sua Moto À Uma Oficina Especializada; - A loja não Se Responsabiliza Pela Má Instalação Do Produto. Obs: - Pode Haver Diferença De Tonalidade Entre A Imagem E O Produto Real Por Conta Do Tratamento De Imagens E A Calibração De Cores Da Tela De Seu Monitor Ou Aparelho.', 231.47, 134.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/sg-11134201-7rfft-m9rer7wpvs0hde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F23394011946', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12427901714', 'Complemento Tampa Lateral Superior Pro Tork Titan 150 Esd/Ex 2013 (Par)', 'As carenagens e peças plásticas Pro Tork são produzidas nos moldes das peças originais da moto, descartando qualquer tipo de adaptação. Fabricado em ABS 100% virgem, as carenagens Pro Tork são extremamente resistentes aos raios UV, tornando-se assim o melhor custo -benefício do mercado. Características: - Marca: Pro Tork; - Modelo: Original; - Tonalidade de cores semelhante ao original; - Valor referente ao par; - Moto compatível: Titan 150 Mix ESD/EX 2013. Aplicação: - Titan 150 Mix ESD 2013. - Titan 150 Mix EX 2013. Atenção! Devido ao desgaste da pintura da motocicleta com o passar do tempo, pode haver uma pequena divergência na tonalidade das cores. Instalação: - A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada.', 210.42, 79.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxmhbb1t3t1b84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F12427901714', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46206513556', 'Kit 2 Raquetes para Beach Tenis 40cm Com 1 Bola - Art Sport', 'O Kit 2 Raquetes para Beach Tennis 40cm com 1 Bola Art Sport é ideal para quem busca diversão e prática esportiva ao ar livre. Com raquetes leves e resistentes de 40cm, oferece conforto e firmeza nas jogadas, sendo perfeito para iniciantes e momentos de lazer na praia, no parque ou no quintal. CARACTERES: Marca: Zein - Art Sport Contém: 2 Raquetes e 1 Bola Composição: ABS Faixa Etária: +3 Dimensão da Raquete: 40cm (altura) Dimensão da Embalagem: 6cm x 26cm x 45cm (LxCxA) Atenção: Imagens meramente ilustrativas', 59.99, 59.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Others', 'https://cf.shopee.com.br/file/br-11134207-820lo-mpm803mvy1oief', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406894684%2F46206513556', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
