INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797653421', 'Brinquedo Infantil Kit de Massinha Mirabel Encanto Cotiplas - 2688', 'Brinquedo Massinha Encanto Festa Disney é uma linha de produtos de brinquedos de modelagem de massinha inspirados no filme "Encanto" da Disney. Inclui personagens e cenários do filme para as crianças criarem e brincarem. Esse modelo vêm com massinha de modelar em várias cores e moldes dos personagens e elementos do filme para as crianças criarem suas próprias versões. É uma forma divertida e criativa de trazer a magia do filme para a vida cotidiana das crianças. ESPECÍFICAÇÕES: Material: Massinha de Modelar Idade recomendada: acima de 3 anos Características: - Marca: Cotiplas - Modelo: 2688 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: 1 - Molde de Tucano 1 - Molde Mirabel 1 - Molde Onça 1 - Molde Castelo 5 – Potes de Massinhas 1 – Rolinho de brinquedo 1 – Utensilio para cortar a massinha 1 - Tesoura de brinquedo brincando de massinha - kit massinha - kit massinha disney - kit de massinha da disney - kit massinha mirabel - kit de massinha da mirabel - kit de massinha para crianças - kit massinha pra criança', 60.46, 52.86, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/sg-11134201-7rdwk-ly2p8yga3abb0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F22797653421', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
