INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197931469', 'Sandália Infantil Feminina Bee Happy Festas Rosa com Tiras Coloridas e 2 Laços', 'Sandália Infantil Feminina Bee Happy Festas Rosa com Tiras Coloridas e 2 Laços 🎀✨ A Sandália Infantil Bee Happy Festas é a escolha perfeita para meninas que amam delicadeza e estilo em cada detalhe. Com base em rosa suave, o modelo ganha destaque com tiras coloridas vibrantes e dois laços decorativos, que deixam o visual ainda mais encantador e elegante. Além da beleza, essa sandália foi pensada para oferecer conforto e praticidade, acompanhando as pequenas em passeios, festas e momentos especiais com leveza e segurança. 🌸 Destaques do produto: Design delicado e feminino com 2 laços decorativos 🎀 Base rosa com tiras coloridas divertidas e modernas Confortável e ideal para festas, passeios e ocasiões especiais Combina charme, estilo e bem-estar para as meninas A Sandália Infantil Bee Happy Festas garante um look adorável e cheio de personalidade, deixando cada passo mais alegre e elegante! 💖', 77.9, 64.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sandals', 'https://cf.shopee.com.br/file/br-11134207-820ld-mm98kh0e78cme2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404144117%2F22197931469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21753568357', 'Cadeira Web Wood em Polipropileno para Sala de Jantar e Cozinha - Seat&co', '🪑 Cadeira Web com Base Wood – La Mobilia Transforme seu ambiente com a Cadeira Web Wood da La Mobilia, um verdadeiro equilíbrio entre sofisticação, conforto e durabilidade. Este modelo é perfeito para quem valoriza design contemporâneo aliado à qualidade da fabricação nacional. Com assento em polipropileno de alta resistência e a exclusiva base Wood (pés de madeira maciça natural com estrutura metálica reforçada), a Cadeira Web é ideal tanto para ambientes residenciais quanto comerciais. Seu design vazado em trama geométrica garante leveza visual, enquanto a ergonomia oferece máximo conforto em longos períodos de uso. 🇧🇷 Produção 100% Nacional – Qualidade Brasileira de Verdade A La Mobilia é uma marca brasileira especializada em móveis de alto padrão com design moderno. Todos os produtos são fabricados no Brasil, com atenção especial aos detalhes, matéria-prima selecionada e compromisso com a durabilidade. ✨ Diferenciais do Produto ✅ Design moderno e sofisticado: encosto com trama geométrica em estilo vazado, leveza visual e excelente ergonomia. ✅ Assento em polipropileno (PP): resistente, fácil de limpar e com acabamento fosco. ✅ Base modelo Wood: pés em madeira natural + estrutura metálica cruzada para estabilidade e firmeza. ✅ Ergonomia com estilo: assento anatômico com braços integrados, garantindo conforto mesmo em longos períodos de uso. ✅ Multifuncionalidade: perfeita para salas de jantar, varandas cobertas, escritórios, recepções, cafés e muito mais. 📏 Dimensões Aproximadas (por cadeira) Altura total: 82 cm Altura do assento: 45 cm Largura: 57 cm Profundidade: 54 cm Peso máximo suportado: até 110 kg Peso unitário: 4,5 kg 📦 Conteúdo da Embalagem 1 Cadeira Web com base Wood (assento em polipropileno + pés de madeira + ferragens) Kit completo de parafusos Manual ilustrado para montagem 🛠️ Montagem Rápida e Segura As cadeiras são enviadas desmontadas, acompanhadas de manual e kit de fixação. Montagem simples, sem necessidade de conhecimentos técnicos. É essencial usar todas as peças fornecidas para garantir segurança e estabilidade. Montagem incorreta pode causar instabilidade e comprometer a garantia. 🧽 Limpeza e Cuidados Utilize apenas pano úmido seguido de pano seco. Não usar produtos abrasivos ou limpeza a vapor. Uso incorreto pode comprometer o produto e anular a garantia. 🛡️ Garantia 3 meses contra defeitos de fabricação 🚚 Envio Rápido e Seguro Estoque próprio Embalagem reforçada Envio imediato para todo o Brasil 🔥 Garanta agora a Cadeira Web com Base Wood da La Mobilia – um produto exclusivo, de design premiado e fabricação nacional, pronto para valorizar e transformar o seu ambiente com elegância e praticidade.', 399.99, 256.76, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcrxvuuvgf0hd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F791969908%2F21753568357', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
