INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49063965190', 'Gulf Orchid Heavenly Lychee Eau de Parfum - Perfume Unissex 100ml', 'Heavenly Lychee - Lichia, cereja e baunilha em uma fragrância frutada irresistível Heavenly Lychee combina a suculência da lichia, cereja e maçã com um coração floral de violeta e rosa, enriquecido pelo toque tropical do abacaxi. A base de baunilha, almíscar, cedro e framboesa proporciona um acabamento elegante, confortável e duradouro. Uma fragrância frutada gourmand unissex, moderna e marcante para todas as ocasiões. Conselho de Aplicação Borrife sobre a pele limpa, principalmente nos pulsos, pescoço e atrás das orelhas. Evite esfregar a fragrância após a aplicação para preservar sua evolução.', 187.81, 187.81, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-8259n-mqm8uaffw45n12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F49063965190', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
