INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13895633071', 'Pincel 3" com cabo plástico - Compel', 'Produto: Pincel 3" com cabo plástico Marca: Compel Descrição: O Pincel 3" com cabo plástico da Compel foi projetado especialmente para profissionais e entusiastas da pintura, este pincel é sua melhor escolha para aplicar esmaltes sintéticos, tinta óleo e vernizes com precisão inigualável. Ideal para trabalhos que exigem um acabamento detalhado e de alta qualidade, confira as vantagens que só ele oferece: Características: • Cerdas Pretas de Alta Qualidade: Garante uma aplicação suave e uma cobertura uniforme que não deixa marcas. • Tamanho Ideal: Medida de 3" (75 mm) perfeito para detalhes, recortes, retoques, vincos e cantos. • Cabo Plástico Anatômico: O cabo vermelho é moldado para conforto e permite um controle excelente durante longos períodos de uso. • Versatilidade: Utilize em uma variedade de superfícies como alvenarias, madeiras e metais. • Excelente Acabamento: Além de cobertura uniforme, proporciona um acabamento superior que destaca a qualidade do seu trabalho. Especificações: Cor das cerdas: preto Medida em Polegada: 3" Medida em MM: 75 mm Material do cabo: Plástico Anatômico Cor do cabo: Vermelho. Dimensões (C x L x A): 1.00 x 7.50 x 22.00 centímetros Peso: 0.05 Kg', 28.02, 28.02, NULL, 'Stationery > Art Supplies > Paint Brushes', 'https://cf.shopee.com.br/file/sg-11134201-82586-mr42qd7uiryd67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F13895633071', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
