INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209439931', 'Lacta Bombom Sortido Sonho de Valsa e Ouro Branco', 'A caixa Sonho de Valsa e Ouro Branco sortidos é a opção ideal para ter sempre por perto e aproveitar cada momento. Ela reúne esses dois sabores icônicos da Lacta em um mix surpreendente, que combina toda a qualidade com aquele momento que dá vontade de comer um docinho! Em qualquer data do ano, a caixa sonho de valsa e ouro branco é perfeita para presentear ou para compartilhar com família e amigos!', 22.49, 14.69, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-8258d-mqnelcm1fua664', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555161%2F58209439931', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098145888', 'Sandália Feminina Salto Baixo Saltinho Sekinah Tiras Cruzadas Macia Confortável', 'Nossa sandália de salto bloco com 5 cm de altura é perfeita para combinar conforto e sofisticação. O design apresenta tiras cruzadas que envolvem o pé com delicadeza , oferecendo firmeza e um toque moderno. Feita com materiais de alta qualidade, essa sandália é ideal tanto para ocasiões casuais quanto para eventos mais formais , proporcionando estilo e praticidade em cada passo. **** INFORMAÇÕES TÉCNICAS *** + Cor – Cor Original da Foto do Produto. + Material – Sintético + Peso - 550 g + Solado – Antiderrapante + Palmilha – Conforto com aplique da logo. + Numeração: será enviada pelo critério de escolha + Caixa embalagem: Cada par será enviado em sua caixa individual. + Frete: Conforme regras da Plataforma. *** Tabela de medidas *** Numeração em Centímetros 34 ------------- 23,0 cm 35 ------------- 23,5 cm 36 ------------- 24,0 cm 37 ------------- 24,5 cm 38 ------------- 25,0 cm 39 ------------- 25,5 cm 40 ------------- 26,0 cm ALTURA DO SOLADO : 5 cm', 79.99, 56.99, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m54bfxo77mwib3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F375175329%2F23098145888', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794935113', 'Salgadinho Batata Frita Pringles® Original', 'A Pringles Original é o salgadinho de batata perfeito para qualquer momento! Com seu formato icônico e sabor irresistível, é ideal para levar na bolsa e saborear a qualquer hora e em qualquer lugar. A lata em tubo foi desenhada para manter as batatas sempre crocantes, protegendo-as da umidade e evitando que quebrem. Desfrute da Pringles Original sozinho ou compartilhe com os amigos!', 7.49, 7.49, NULL, 'Food & Beverages > Snacks > Chips & Crisps', 'https://cf.shopee.com.br/file/sg-11134201-825bb-mqneljqjnv2lbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1660302938%2F23794935113', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204691672', 'Óleo PAG 46 Para Compressor Ar Condicionado R134 E 1234YF', 'Produto: Oleo para Compressor R134a R1234yf. PAG46 Compatíveis com compressores elétricos Óleo produzido no Japão com a mais alta e renomada tecnologia mundial, atende todas os padrões de todas as montadoras tais como BMW Mercedes Jaguar Audi Land Rover Volkswagen Fiat Jeep e Demais montadora. Como distribuidor autorizado no Brasil. A Idemitsu é uma empresa japonesa que fabrica óleos lubrificantes para compressores de ar condicionado, refrigeração comercial e automotiva. Os óleos Idemitsu para compressores de ar condicionado são desenvolvidos para cada sistema de refrigeração. ******************Vantagens dos óleos Idemitsu***************************** *Proteção contra desgaste e temperaturas extremas *Aumento da vida útil do compressor e do sistema *Redução de custos de manutenção *Produto quimicamente diferente, com uma estrutura estável e não reativa Aplicações *Sistemas de A/C com R1234yf e R134a *Proteção contra desgaste e temperaturas extremas *Redução de custos de manutenção **************************Características dos óleos Idemitsu ********************* *Desenvolvem tecnologias exclusivas com especialização na área de PAG *Garantem o desempenho nas mais variadas temperaturas Proteção contra o desgaste dos compressores', 78.0, 78.0, NULL, 'Spare Parts and Accessories for Vehicles > Others', 'https://cf.shopee.com.br/file/sg-11134201-8261w-mkbrjumzpnuqee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1698877873%2F58204691672', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194697670', 'MODULO AMPLIFICADOR TARAMPS BASS 1200 1 CANAL POTENCIA 1.200W RMS', 'O módulo amplificador BASS 1200 é uma solução robusta e eficiente para quem busca excelência em frequências subgraves e graves. Com 1200 W RMS e disponível nas versões de 2 Ohms ou 4 Ohms, possui uma resposta de frequência de 8 Hz a 250 Hz, ideal para subwoofers. As entradas de áudio via RCA e fio garantem mais versatilidade, permitindo o uso com a maioria dos players do mercado, incluindo multimídias originais, sem necessidade de adaptadores. Equipado com ajuste de ganho (0.2 a 4V), crossover com ajuste subsonic de 8 a 30Hz e LPF de 60 a 250Hz, este amplificador também oferece Bass Boost variável, permitindo escolher a frequência central entre 35 e 60Hz e aumentar os graves em até 10dB. A carcaça em alumínio, combinada com um Smart Cooler, garante eficiente dissipação de calor e operação silenciosa. Além disso, o BASS 1200 acompanha o acessório Monitor Level Remote, proporcionando controle prático e em tempo real do volume do amplificador. Este acessório pode ser facilmente fixado no painel do veículo, ao alcance das mãos, e permite monitorar as condições de operação do amplificador através dos LEDs integrados: On, Clip e Proteção. Experimente graves muito mais poderosos com o novo BASS 1200 da Taramps. Informações técnicas: Versão 2 Ohms: Potência Nominal @14,4VDC - 2 Ohms: 1200W RMS - 4 Ohms: 900W RMS Versão 4 Ohms: Potência Nominal @14,4VDC - 4 Ohms: 1200W RMS - 8 Ohms: 800W RMS Número de canais: 01 Sensibilidade de entrada: (RCA): 4 V (min.) / 250 mV (máx.) - (FIO): >10 V (min.) / 3 V (máx.) Relação de sinal/ruído: >90 dB Resposta de frequência: 8 Hz ~ 250 Hz (-3 dB) Crossover high pass (HPF): 8 Hz ~ 30 Hz (-12 dB/8ª) Variável Crossover low pass (LPF): 60 Hz ~250 Hz (-12 dB/8ª) Variável Bass Boost: Paramétrico (35 ~ 60 Hz) 0 ~ +10 dB Impedância de Entrada: 10K Ohms Sistema de proteção: Sobrecarga na saída, tensão de alimentação baixa e alta e proteção térmica Tensão de alimentação mínima: 9 VDC Tensão de alimentação máxima: 17 VDC Consumo em repouso: 2 Ohms: 1,60A - 4 Ohms: 1,80A Consumo máximo musical: @14,4 VDC 2 Ohms: 52,5A - 4 Ohms: 55A Consumo máximo em sinal senoidal: 2 Ohms: 110A - 4 Ohms: 110A Dimensões (LxAxP): 239 x 73 x 157 mm Peso: 2,0 Kg *Não será aceita a devolução de equipamento que já foi fixado e apresente marcas de parafuso em algum ponto de fixação; *Não se responsabilizamos por instalação mal realizada; *Não se responsabilizamos por mau uso do produto; *Para acionar a garantia será necessário encaminhar o produto com a nota fiscal para uma autorizada da marca; *Só aceite receber a mercadoria após verificar se a mesma coincide com a que consta no pedido e se está em perfeito estado;', 704.99, 704.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-821f3-mgs2ijmg1o2114', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406280808%2F22194697670', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099371156', 'Box Baú com Colchão e Espuma D45 Castor Black White Queen 158cm', 'O Colchão de Espuma D45 Black & White Double Face Castor é indicado para pessoas de até 150kg proporcionando conforto firme, o que lhe confere firmeza suficiente para preservar sua coluna durante o sono sem comprometer seu conforto. Fabricado com matérias-primas de alta qualidade e durabilidade, o Black White Double Face garante conforto e segurança por muito mais tempo pois possui a garantia Castor. Procurando uma base de cama que ofereça não só suporte robusto mas também soluções práticas de armazenamento? A base baú da Lucas Colchões é perfeita para quem precisa otimizar o espaço no quarto. Ideal para guardar roupa de cama, travesseiros ou qualquer outro item que precise de armazenamento extra. Facilidade de transporte e instalação em locais com acesso limitado, como escadas estreitas e elevadores pequenos. Essa característica torna a base bipartida ideal para apartamentos e casas com espaço de circulação restrito. Especificações Técnicas do Colchão: - Marca: Castor; - Proteções: Antiácaro - Antialérgico - Antifungo - Antimofo; - Acabamento: Bordado em Matelassê; - Matéria prima: Espuma/Tecido; - Densidade: D45; - Tipo de conforto: Firme; - Peso máximo recomendado: até 150kg (por pessoa); - Garantia: 12 meses; - Dimensões do produto (larg. x comp. x alt.) Queen: 158x198x27cm. Especificações Técnicas Base Box Baú: - Marca: Lucas Colchões; - Material: Madeira tratada; - Peso máximo recomendado: até 150 Kg (por pessoa); - Altura do baú: 37cm; - Profundidade do baú: 25cm; - Altura dos pés: 5cm; - Revestimento: Sintético; - Garantia: 3 meses; - Dimensões (larg. x comp. x alt.) Queen: 158x198x42cm Bipartido (2 Partes de 79). Importante: as cores podem variar conforme a tela; Não oferecemos montagem