INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397747727', 'Kit 2 Fralda Descartável Mió Baby Tamanho M com 32 Unidades', 'A Mió Fralda do mundo é nossa! Já pensou em uma fralda que oferece qualidade premium, conforto e preço acessível? Era com isso que a gente sonhava quando começamos a idealizar nossa fralda. E olha só: conseguimos! Proteção Dia e Noite Imagine uma fralda que abraça seu bebê com conforto o dia todo e durante a noite também. A Mió Baby foi feita pensando no bem-estar dos pequenos, oferecendo até 12 horas de proteção para que eles possam explorar o mundo sem preocupações. Com materiais suaves e uma absorção incrível, Mió Baby é a escolha perfeita para acompanhar cada momento do seu bebê, garantindo sorrisos o tempo todo. ? Fecho da Mió qualidade? O sistema de fecho da fralda Mió Baby foi projetado para ser tão fácil quanto um sorriso de bebê. Feito para ser confortável para os pequenos e prático para os pais, garante um ajuste seguro que não abre nem vaza. Com Mió Baby, trocar fraldas se torna uma tarefa simples e segura, para que você possa aproveitar cada momento com seu bebê. Não deixe de aproveitar Descubra Mió Baby: fraldas que oferecem conforto e proteção por até 12 horas, dia e noite. Com um sistema de fecho seguro e fácil de usar, Mió Baby mantém seu bebê feliz e seguro em todos os momentos. Escolha a confiança e o cuidado que seu bebê merece.', 69.98, 69.98, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-823rd-mojpkd561p8s43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F22397747727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
