INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19498021082', 'Película para Huawei Watch Fit 3 - Hydrogel HD - Gshield', 'DESCRIÇÃO A Película de Hydrogel da Gshield oferece proteção avançada para a tela do seu smartwatch, garantindo uma experiência duradoura e sem preocupações. Com tecnologia inovadora de hidro nano PET e TPU Soft Gel, essa película protege contra riscos indesejados. O revestimento oleofóbico não só aprimora a resistência a arranhões, mas também minimiza marcas de digitais, proporcionando uma visualização sempre clara e nítida. A película se ajusta perfeitamente às extremidades curvas do seu dispositivo, assegurando uma cobertura total sem comprometer a estética e a funcionalidade. Optar pela Película de Hydrogel Gshield é escolher um escudo sofisticado que combina tecnologia de ponta e durabilidade, mantendo a tela do seu relógio sempre impecável. Cuide do seu smartwatch com estilo e confiança, escolhendo a excelência em proteção que só a Gshield oferece. ESPECIFICAÇÕESMaterial: Hidro nano pet + TPU Soft Gel Marca: GshieldEspessura: 0,19mm Proteção: Contra pequenos impactos e riscos à tela Grau de transparência: 97% High DefinitionCertificações: US MilitaryDimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais.', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7rbmz-m5je1p3q8bdj1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F19498021082', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17729144238', 'Película Defender Glass para Samsung Galaxy S22 Plus - Preta - Gshield', 'Proteja a seu dispositivo com a melhor película para Samsung Galaxy S22 Plus A Película Defender Glass da Gshield é fabricada com vidro duplamente temperado e bordas laterais em poliuretano de alta densidade com elevação de 2 milímetros que garantem maior resistência à impactos e evita que a película trinque com facilidade nas extremidades. As bordas laterais possuem um diferencial único de proteção e se diferem das películas 3D e 5D convencionais, que são apenas jateadas de tinta e não possuem elevação. Além disso a película Defender Glass conta com uma camada oleofóbica e é de fácil instalação.', 43.99, 43.99, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/2d6a553c9d4a51254bdcc964e8a4307e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F17729144238', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
