INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597569066', 'Disco de Freio Traseiro Cb 600f Hornet Sem Abs 2008 A 2014 + Pastilhas Pro Tech Racing (Metálica) Diafrag', 'Disco de Freio Traseiro + Pastilha de Freio Traseira Compatível com: HONDA CB 600F HORNET 2008 (Sem Abs) CB 600F HORNET 2009 (Sem Abs) CB 600F HORNET 2010 (Sem Abs) CB 600F HORNET 2011 (Sem Abs) CB 600F HORNET 2012 (Sem Abs) CB 600F HORNET 2013 (Sem Abs) CB 600F HORNET 2014 (Sem Abs) Conteúdo da embalagem: 01 Disco de Freio Traseiro GP7 01 Par de Pastilhas de Freio Traseira DIAFRAG Pro Tech Racing (Metálica) Características do Disco de Freio: - Produzidos em Aço Carbono de alta resistência ao desgaste; - Excelente frenagem e equilíbrio; - Discos ventilados que evitam o superaquecimento; - Frenagem mais complexa; - Aumenta a frenagem mesmo em terrenos úmidos; - Bom funcionamento do sistema de freios; - Qualidade Original; Especificações Pastilhas: - Modelo: PRO TECH RACING - Material: Metálica - Produzido com melhores equipamentos garantindo segurança e durabilidade. - Oferecendo o melhor custo beneficio, unindo qualidade e eficiência na sua utilidade. - Possui medidas originais - Melhor dissipação de calor e atrito com o disco de freio - Ideal Para Reposição - Maior segurança ao motociclista - Alta Qualidade E Resistência Importante Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto. Verifique, antes da compra, se as medidas das pastilhas são compatíveis com a da sua moto.', 229.9, 183.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7rd5p-lvq3oj71huik76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F22597569066', NULL, NULL, '2026-07-28T02:11:31.7084