INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8362249788', 'Desengraxante Spray Sandet 955 Limpa Motor Remove Graxa E Óleo 750ml', 'DESENGRAXANTE SINTÉTICO SANDET 955 750ML DESCRIÇÃO: Produto para remoção de graxas e oleosidade em geral, em maquinário leve ou pesado. Limpeza de motores, quinta roda, peças, siderúrgicas, metalúrgicas e oficinas FINALIDADE: - Indicado para remoção de graxas e óleos em maquinários leves ou pesados (escavação, terraplanagem, usina de álcool e açúcar, lançadeiras de asfalto, entre outros), chassis de ônibus e caminhões, limpeza de motores, siderúrgicas ou metalúrgicas. MODO DE USO: - Pode ser utilizado puro em casos de sujidade extrema. - Para sujidades mais leves pode ser diluído em água no momento da aplicação, agitando-se bem para a perfeita diluição. - A aplicação pode ser feita através de esfregões, ou imersão. - Enxaguar bem após a aplicação.', 59.92, 59.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Degreasers', 'https://cf.shopee.com.br/file/sg-11134201-22110-gicp8ppagakvd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F8362249788', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
