INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294467653', 'Politriz Orbital BLACK+DECKER KP12K 254mm 120W 220V', 'A Politriz Orbital BLACK+DECKER KP12K é ideal para polimentos em carros, motos e móveis, proporcionando acabamento uniforme e brilho com praticidade. Indicada para cuidados automotivos, conservação de superfícies e manutenção residencial, facilita o polimento em áreas amplas graças ao seu disco de 254mm, tornando o trabalho mais rápido e eficiente. Seu motor de 120W oferece desempenho adequado para polimentos em geral, enquanto a baixa vibração proporciona maior conforto durante o uso. A empunhadura circular melhora o controle e a visualização da área de trabalho, e a base estável facilita a adaptação dos acessórios. Seu design prático torna o equipamento uma excelente opção para quem busca facilidade e qualidade no acabamento. Principais características • MOTOR DE 120W: desempenho eficiente para polimentos em geral • DISCO DE 254MM: cobre áreas maiores com mais rapidez • BAIXA VIBRAÇÃO: maior conforto durante o uso prolongado • EMPUNHADURA CIRCULAR: melhor controle e visualização do trabalho • BASE ESTÁVEL: facilita a adaptação dos acessórios • IDEAL PARA POLIMENTO: indicada para carros, motos e móveis Robusta, eficiente e confiável, a Politriz Orbital BLACK+DECKER KP12K é ideal para quem busca praticidade e ótimo acabamento em polimentos automotivos e domésticos. Seu design confortável e funcionamento estável garantem uma experiência de uso segura e resultados de qualidade.', 399.0, 389.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820li-mq6f9uqaz0n598', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1475265282%2F22294467653', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
