INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694437436', 'Kit 2 Und Neocoflan Aero 85ml', 'ONeocoflan Aerossol 85mlé um medicamento anti-inflamatório não esteroidal (AINE) de uso tópico, ideal para otratamento de dores musculares, articulares e inflamatórias.Sua formulação promove alívio eficaz em casos de torções, contusões, lesões esportivas e desconfortos associados a processos inflamatórios. O formato emspray aerossolfacilita a aplicação, proporcionando ação rápida e precisa, sem necessidade de contato manual direto. Atenção:Neocoflan é um medicamento. O uso deve ser feito soborientação médica. Leia a bula antes de utilizar. CATEGORIAS Anti-inflamatóriosSaúde Muscular e Articular', 49.7, 49.7, NULL, 'Health > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gr-mf328o3x9moe39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F23694437436', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599358590', 'Kit 2 Zerolac Enzima Lactase 10.000 30 Caps Original Zero Açúcar', 'Kit 2 und Zerolac 10.000 FCC com 30 caps Zerolac® é uma enzima lactase na concentração de 10.000 FCC* Que auxilia na digestão de alimentos a base de leite (manteiga, leite, requeijão e derivados). *FCC ALU Apergillus oryzae - enzima lactase Benefícios: Zerolac® possibilita que pessoas intolerantes à lactose consumam leite e derivados sem desconfortos gastrointestinais, tornando possível se beneficiar de seus nutrientes essenciais. Veja como é fácil utilizar Zerolac®: 1 - Ingerir 1 cápsula de Zerolac® com água antes do consumo de alimentos lácteos ou derivados. 2 - A dosagem deve ser ajustada conforme a necessidade individual. 3 - Consumir conforme orientação do médico ou nutricionista. 4 - A lactase está autorizada para maiores de 19 anos. Saiba como Zerolac® pode te ajudar! 1 - Zerolac® é uma aliado no combate aos sintomas da intolerância à lactose. 2 - Zerolac® promove a adequada quebra da lactose. 3 - Zerolac® contribui para a diminuição do desconforto gastrointestinal, gases e diarreia. 4 - Zerolac® tem alta concentração da enzima lactase 10.000 FCC. 5 - 1 cápsula de Zerolac® possibilita a ingestão de 34g de lactose - em média, 3 copos de leite ou derivados.', 58.75, 51.99, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rdy3-lyzkaipy1dpzc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F20599358590', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
