INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19298319548', 'LÂMPADA UNITÁRIA BOSCH ORIGINAL H4 GIGALIGHT PLUS 150 12V 60/55W FAROL ALTO BAIXO 150%+ LUZ', 'A LÂMPADA AUTOMOTIVA BOSCH GIGALIGHT PLUS 150 H4 12V FOI DESENVOLVIDA PARA QUEM BUSCA MÁXIMA PERFORMANCE E SEGURANÇA NA CONDUÇÃO NOTURNA. COM ATÉ 150% MAIS LUMINOSIDADE EM COMPARAÇÃO ÀS LÂMPADAS HALÓGENAS CONVENCIONAIS, ELA OFERECE VISÃO SUPERIOR DA ESTRADA, DESTACANDO MELHOR OBSTÁCULOS, PEDESTRES E SINALIZAÇÕES. - FACHO MAIS LONGO E CONCENTRADO, AMPLIANDO A VISIBILIDADE NOTURNA - VIDRO DE QUARTZO UV E CONSTRUÇÃO REFORÇADA PARA MAIOR DURABILIDADE E RESISTÊNCIA TÉRMICA - SUBSTITUIÇÃO DIRETA — INSTALAÇÃO SIMPLES E RÁPIDA PRINCIPAIS CARACTERÍSTICAS: * MARCA: BOSCH * MODELO: GIGALIGHT PLUS 150 – 1987301136 * CONECTOR: H4 * TECNOLOGIA: HALÓGENA * VOLTAGEM: 12V * POTÊNCIA: 60/55W * ATÉ 150% MAIS LUZ QUE LÂMPADAS PADRÃO * TONALIDADE DE COR: AMARELA COMPATIBILIDADE: - INDICADA PARA VEÍCULOS QUE UTILIZAM LÂMPADAS H4 NOS FARÓIS PRINCIPAIS. POR QUE ESCOLHER BOSCH GIGALIGHT PLUS 150? PORQUE COMBINA POTÊNCIA, QUALIDADE E SEGURANÇA, COM A CONFIABILIDADE DE UMA MARCA LÍDER MUNDIAL EM TECNOLOGIA AUTOMOTIVA. IDEAL PARA QUEM EXIGE MÁXIMO DESEMPENHO E ILUMINAÇÃO SUPERIOR EM QUALQUER CONDIÇÃO DE DIREÇÃO.', 134.1, 120.69, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfmk4jxkfls7c4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F432660571%2F19298319548', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55108440157', 'Vaso para Planta Canelado 34x26 Coluna Decorativo Jardim Sala Moderno Resistente', 'Vaso para Planta Canelado Coluna com Pé – Decorativo Moderno 34cm ENVIO IMEDIATO !!! Transforme qualquer ambiente com elegância e sofisticação! O vaso canelado modelo coluna é perfeito para quem busca uma decoração moderna, valorizando salas, varandas, jardins e áreas internas ou externas. Com design exclusivo e acabamento canelado, ele traz um visual premium e atual, ideal para compor espaços com muito estilo. O suporte (pé) já embutido garante mais estabilidade e destaque para suas plantas. Fabricado em material resistente e de alta qualidade, é leve, durável e não desbota, podendo ser usado tanto com plantas naturais quanto artificiais. Medidas do Vaso: • Altura: 34 cm • Diâmetro da boca: 25 cm • Diâmetro central: 26 cm • Base: 16 cm • Capacidade aproximada: 14 litros Benefícios: • Design moderno canelado (alto padrão decorativo) • Suporte com pé já integrado (não precisa montar) • Resistente ao sol, chuva e variações climáticas • Não desbota e mantém a cor por muito mais tempo • Leve, prático e fácil de limpar • Ideal para ambientes internos e externos Perfeito para decorar com elegância e praticidade, esse vaso é a escolha ideal para destacar suas plantas e deixar seu espaço ainda mais bonito! Palavras-chave: vaso canelado, vaso coluna, vaso decorativo, vaso com pé, vaso grande 34cm, vaso para plantas, vaso polietileno, vaso moderno, vaso jardim, vaso sala decoração, vaso externo resistente, vaso alto decorativo', 49.9, 39.9, NULL, 'Home & Living > Gardening > Pots & Planters', 'https://cf.shopee.com.br/file/br-11134207-820m0-mo5bo1h1enls81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F608615567%2F55108440157', NULL, NULL, '2026-07-28T02:1