INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '2960887261', 'Caneta para tecido Acrilpen Preta 520 Acrilex', 'Caneta para pintar e marcar tecidos permanentemente tecidos como algodão. Detalhes: - Excelente fixação. - Super resistência à lavagens. Modo de usar - Lavar o tecido antes da pintura, para retirar os resíduos de goma. - A ponta da caneta Acrilpen permite conseguir diferentes espessuras de traços. Usando na posição vertical obtemos traços finos, inclinando-a obtemos traços mais grossos. - Após a pintura, aguarde 72 horas para lavagem. - Após o uso, guardá-la na posição horizontal. Uso específico - Caneta para pintar e marcar tecidos permanentemente. - Para tecidos de algodão. - Não utilizar em tecidos sintéticos ou engomados. Outros usos - Também pode ser usada em papel, papelão, madeira, cerâmica, gesso, etc.', 20.92, 20.92, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-8261g-mjube5kscb9cca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F2960887261', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
