INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697763632', 'Guarda-Roupa 6 Portas 4 Gavetas Kappesberg Adapt Nogueira', 'Para quem sempre sonhou com um quarto planejado, o Modulado Adapt da Kappesberg é a escolha ideal. Produzido em MDP, material de alta qualidade, o Roupeiro 6 portas N538 é ideal para quem busca por organização e uma melhor otimização do espaço. Espaçoso e muito versátil, ele garante beleza e funcionalidade, além de uma melhor organização. Com seis portas e uma divisão interna igual dos dois lados, ele conta com uma ótima distribuição de espaço entre prateleiras, gavetas e cabideiros, permitindo guardar calçados, peças de roupa dobradas ou penduradas em cabides, deixando seu espaço sempre organizado. E com pintura touch de sete camadas e acabamento fosco na cor nogueira, além de combinar facilmente com todos os ambientes, garante a sensação de aconchego e conforto. Os destaques ficam por conta do sistema de amortecimento nas portas, proporcionando um fechamento suave e sem ruídos, do puxador em MDF, e da montagem interna ajustável, podendo ampliar a quantidade de gavetas ou prateleiras, completando os diferenciais do produto e deixando você com o quarto que sempre sonhou. Renove seu quarto com toda a qualidade e beleza que o Modulado Adapt da Kappesberg oferece e aproveite cada momento. Informações importantes: As imagens são meramente ilustrativas, não acompanha acessórios; Pode haver variação de cor de acordo com a calibragem da tela onde o produto está sendo visualizado; Todos nossos móveis são entregues desmontados; A montagem é sempre por conta do cliente (orientamos a contratação de um profissional qualificado, o manual de montagem acompanha o produto); O vídeo do produto pode ser genérico, então atente-se às imagens do anúncio para optar pela cor/modelo.', 3607.46, 2199.99, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-824gc-me63yqeat05c6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F22697763632', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193271767', 'Armário Aéreo Celeste Kappesberg 100% MDF 1 Porta Branco 40cm', 'Sua cozinha com toda a beleza e praticidade do Aéreo 1 Porta 40cm N743 da Cozinha Celeste da Kappesberg. Produzido em chapa MDF de 15mm, ele garante robustez, firmesa e qualidade, além de um acabamento perfeito. Com sete camadas de pintura na cor branco, tanto na parte interna quanto na externa, seu acabamento em brilho, além de combinar com todos os ambientes, aumenta a luminosidade do espaço, deixando sua cozinha perfeita. Compacto e funcional, o aéreo possui uma porta e duas prateleiras, além do espaço ideal para organizar louças e mantimentos. Fechando uma ótima combinação com o balcão de mesmo tamanho, destaque fica para as dobradiças com amortecimento, garantindo um fechamento suave e sem ruídos, incluindo mais durabilidade. E seu puxador metálico quadrado na cor dourada completa o design e a qualidade da cozinha, deixando seu ambiente ainda mais estiloso. Renove seu espaço e o deixe ainda mais completo com a Cozinha Celeste da Kappesberg. Informações importantes: As imagens são meramente ilustrativas, não acompanha acessórios; Pode haver variação de cor de acordo com a calibragem da tela onde o produto está sendo visualizado; Todos nossos móveis são entregues desmontados; A montagem é sempre por conta do cliente (orientamos a contratação de um profissional qualificado, o manual de montagem acompanha o produto); O vídeo do produto pode ser genérico, então atente-se às imagens do anúncio para optar pela cor/modelo.', 414.33, 359.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-8262o-mm9cz6c6d81vb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F22193271767', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
