INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10747154020', 'Filtro de Ar Wega FAP4867 / Tecfil ARL9600', 'Filtro de Ar Wega FAP4867 / Tecfil ARL9600 Obs: Na falta de Filtro Wega estaremos prosseguindo com o envio da marca Tecfil,Ambos de qualidade similar. O Filtro de Ar Motor tem a função de separar e eliminar as partículas impuras do ar aspiradas pelo motor. Cerca de 10 mil quilômetros, em média. Os filtros do ar não podem ser limpos com jato de ar, pois isso romperá os poros do meio filtrante. Aplicações: Ford Transit 2.4 TDCi 2008 -->Ford Transit 2.2 TDCi 2012 -->Ford Transit 2.2 TDCi Duratorq 2012 -->Ford Transit TDCi diesel - (Chassi / Van / Furgão) - mecânico 2.2 2012 -->Ford Transit TDCi diesel - (Chassi / Van / Furgão) - mecânico Duratorq 2.2 - 125 cv 2012 -->', 81.89, 81.89, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/bfad7a7eea9d7d9a36e9e66d76679fe2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F295637446%2F10747154020', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
