INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257675505', 'Copo de Treinamento Kuka Fun Antivazamento Azul 330ml', 'O que é e para que serve o Copo de Treinamento Antivazamento Kuka Linha Fun? Desenvolvido especialmente para crianças que estão aprendendo a comer sozinhas, o Copo de Treinamento Antivazamento Kuka possui um bico, feito em silicone, e tampa com válvula que evita vazamentos, permitindo que o líquido saia apenas com a sucção da criança. Ainda, conta com um design exclusivo, capuz protetor flip top e formato anatômico, leve e fácil de segurar. Dessa forma, a criança ganha autonomia para se alimentar até durante as atividades do dia a dia, sem perigo e sem sujeira. Como usar o Copo de Treinamento Antivazamento Kuka Linha Fun? Antes do primeiro e após cada uso do copo de treinamento Kuka, separe os componentes (tampa, copo e válvula), lave com água, detergente neutro e enxágue bem. Coloque o líquido no copo e feche bem a tampa. Especificações Modelo: Linha Fun Antivazamento. Marca: Kuka. Cor: Azul. Conteúdo da embalagem: Copo, tampa com bico de silicone e capuz de proteção. Informações importantes Este produto possui refil avulso para reposição. Evite acidentes: Não permita que a criança corra com o copo e/ou sem supervisão constante de um adulto Nunca utilize o copo com líquidos carbonados (refrigerantes e outros) ousucosque contenham polpa. Caso o copo fique virado com o bico para baixo, algumas gotas poderão sair pelos orifícios. Após cada uso, lave o copo conforme as instruções da embalagem. Devido a característica do material, o copo poderá absorver os pigmentos de alguns alimentos. Isto não compromete a utilização do produto. Verifique regularmente o estado do copo e tampa. Caso haja sinal de desgaste em algum dos itens, descarte-o imediatamente. Substitua o copo após 1 a 2 meses de uso por motivos de higiene e segurança. Este copo pode ser usado para aquecimento de líquidos no forno micro-ondas, sem a tampa e pode ser lavado em lava-louças.', 27.26, 27.26, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/sg-11134201-82608-mmaefkq71blx6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F58257675505', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256333148', 'Pote Térmico Buba com Talher 320ml', 'Pote térmico com talher Buba Gumy conserva a temperatura do alimento por mais de 5 horas. Ideal para passeios e viagens, Produto novo. 320 mL. Livre de BPA, ftalatos, 100% atóxico. CARACTERÍSTICAS TÉCNICAS Conteúdo da Embalagem: Pote Térmico com Talher Buba Gumy Dimensões Aproximadas do Produto: 12 x 9 x 9 (Altura x Largura x Comprimento/Profundidade) Dimensões da Aproximadas da Embalagem: 12 x 10 x 23 (Altura x Largura x Comprimento/Profundidade) Material/Composição: Pote Aço Inoxidável, Tampa e Base Polipropileno, Talher e Suporte Polietileno, Anel interno Silicone Temos diversos infantis em nossa loja! Marca: Buba', 98.3, 86.99, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/sg-11134201-825zy-mlgqv84uvcpbb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F58256333148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
