INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499264148', 'Rack para TV até 50 Polegadas com 4 Portas Suspenso Multimóveis MP1070', 'Transforme sua sala num cinema particular com o Rack para TV até 50 Polegadas 4 Portas Suspenso Multimóveis MP1070. Fabricado em MDP e com acabamento acetinado (cerca de 20% de brilho), este rack oferece durabilidade e resistência, além de um design clean que proporciona um visual moderno e sofisticado para sua sala. Com suas 4 portas, você terá amplo espaço interno para guardar seus objetos e manter sua sala sempre organizada. Suporta TV de até 50 polegadas (até 15kg). Por ser suspenso, este rack permite a montagem na altura que você preferir, além de facilitar a limpeza do ambiente! Conteúdo da Embalagem: 1 (um) Rack Manual de Montagem Kit Ferragem Dimensões do produto montado: Altura: 39,5 cm | Largura: 123,5 cm | Profundidade: 31,5 cm *Você pode consultar as medidas detalhadas na imagem técnica do produto. *Devido às variações de tamanho dos televisores no mercado, sugerimos que compare o tamanho da sua TV com o rack antes de efetuar a compra. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 329.99, 249.99, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-7rd5n-lw77wvsbjyhwb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F20499264148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994264678', 'Estanho em fio para solda espessura 1 mm - BOM-5552 Bomvink', 'Produto: Estanho em fio para solda espessura de 1 mm 40 g - BOM-5552 Marca: Bomvink Descrição: O Estanho em fio para solda espessura de 1 mm 40 g BOM-5552 da Bomvink é ideal para soldagens de alta qualidade e eficiência. Este produto excepcional combina características avançadas com facilidade de uso, garantindo juntas de solda impecáveis e resistência duradoura em todos os seus projetos eletrônicos e elétricos. Com estrutura composta por 40% de estanho, o fio de solda BOM-5552 inclui breu e fluxo integrados, reduzindo significativamente a emissão de fumaça e a incidência de respingos durante o uso. Além disso, o baixo ponto de fusão facilita uma soldagem rápida e segura, minimizando potenciais danos a componentes delicados. Características: • Juntas de Solda Suaves e Arredondadas: Garante acabamentos mais limpos e profissionais, assegurando forte aderência e longevidade; • Menos Fumaça e Respingos: O uso integrado de breu e fluxo no fio diminui a poluição do ar e oferece um ambiente de trabalho mais limpo e seguro; • Uniformidade em Espessura: A consistência do fio promove aplicações precisas e resultados uniformes em todas as soldagens; • Baixo Ponto de Fusão: Facilita a aplicação rápida, ideal para trabalhos que exigem agilidade e eficácia, reduzindo o risco de danos; • Resistência Ã Corrosão: Aumenta a durabilidade das juntas soldadas, especialmente em condições ambientais adversas. Especificações: Diâmetro do fio de estanho: 1 mm Percentual de estanho: 40%. Dimensões (C x L x A): 2.70 x 5.50 x 5.50 centímetros Peso: 0.10 Kg', 30.07, 30.07, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-825as-mql1ede59a1b96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F23994264678', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
