INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24145222481', 'Livro Luara - Cozy moments', 'Inspirado no fenômeno dos livros de colorir para relaxamento do TikTok, o livro da influenciadora Luara Fonseca, Luara - Cozy Moments, é perfeito para quem ama transformar momentos simples em uma verdadeira experiência calmante. Impressas em papel de alta gramatura, para garantir a melhor qualidade de pintura, as 48 páginas, com 23 ilustrações exclusivas e uma página para você testar cores e texturas, retratam momentos cotidianos e aconchegantes, permitindo que você explore sua criatividade ao máximo, seja colorindo com lápis de cor ou marcadores. Livre para todos os públicos, este livro é ideal para aliviar o estresse e se_x000D_ desconectar da correria do dia a dia._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2025_x000D_ Autor: Ciranda Cultural _x000D_ Ilustrador: Aline Yurika_x000D_ Idioma: Português_x000D_ Páginas: 48_x000D_ Dimensões: L 23.50 x A 23.50 x E 0.50_x000D_ ISBN: 9786526124567_x000D_ Coleção: Comfy & cozy books_x000D_ Linha Editorial: Ciranda Cultural - Lab_x000D_ Faixa Etária: + 9 anos_x000D_ Assuntos (tags): Colorir, Relaxar, Diversão, Pintar, Pintura_x000D_ BISAC: Jogos e Atividades / Jogos e Atividades / Livros de Colorir_x000D_ Linha de Produto: Comfy and cozy books_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 24.9, 11.9, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/sg-11134201-7rfgl-m9uhzrq1lgra28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F24145222481', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
