INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8970309263', 'Livro - Meus queridos contos clássicos - Capa comum - Ciranda Cultural', 'O mundo encantado de fadas, gigantes, bruxas e piratas está de portas abertas para você. Embarque em uma maravilhosa viagem mágica e com aventuras. Histórias: Alice no pais das maravilhas O gato de botas Branca de neve João e o pé de feijão A bela adormecida O patinho feio A pequena sereia Pinóquio Cinderela A bela e a fera Cachinhos dourados Peter Pan Os tres porquinhos João e Maria. Editora: Ciranda Cultural Edição: 3, 2020 Autor: Ciranda Cultural Idioma: Português Páginas: 128 Dimensões: L 15.50 x A 22.30 x E 1.00 ISBN: 9786555002454', 19.9, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/864d57785eee9a9bc04ad9e07c080abd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8970309263', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8167339907', 'Livro - Histórias de Tia Nastácia - Capa comum - Ciranda Cultural', 'A turma do Sítio do Picapau Amarelo tem por perto uma sábia representante da cultura popular. Além de fazer bolinhos deliciosos, Tia Nastácia sabe contar muitas histórias fantásticas do nosso folclore, que ganham interpretações e comentários nada convencionais dos netos de Dona Benta e de uma boneca de pano bastante esperta. Editora: Ciranda Cultural Edição: 1, 2019 Autor: Monteiro Lobato Idioma: Português Páginas: 160 Dimensões: L 15.50 x A 22.30 x E 0.70 ISBN: 9788538090281', 24.9, 24.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/4408a60d5809d83db7fc7a9b76c6278b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8167339907', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18598020640', 'Kit com 3 Cuecas Boxer Mash 710.01 Colorido', 'Características: Cueca boxer básica com design moderno e elegante. Tecnologia sem costura. Ajuste perfeito ao formato do corpo. Cores: Preto: 2 preto e 1 marinho Branco: 2 preto e 1 branco Marinho: 2 marinho e 1 branco Cinza: 2 branco e 1 cinza Composição: 92%Poliamida, 05% Elastano e 03%Polipropileno.', 136.7, 136.7, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/sg-11134201-7rfgp-m49boxr45uus62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F18598020640', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093110641', 'Kit com 4 Cuecas Infantil Boxer Lupinho 136-001', 'Características: Cueca boxer infantil. Confeccionada em microfibra super leve e macia. Sem costura, anatômica, proporciona ajuste perfeito. Acabamento com elasticidade multidirecional garante extremo conforto. Cintura em elástico duplo personalizado, com logotipo da marca. Cores: Marinho: Todas marinho Preto: Todos preto Branco: Todos branco Azul: Todos azul Composição: 93% Poliamida, 04% Poliéster e 03% Elastano.', 145.6, 145.6, NULL, 'Baby & Kids Fashion > Boy Clothes > Underwear & Innerwear', 'https://cf.shopee.com.br/file/sg-11134201-7rd4w-lwr72h6v8kop98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F22093110641', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20865952805', 'Alfaparf milano professional semi di lino beauty genesis caixa de ampola para brilho 12x13ml', 'Caixa de Ampola para Brilho Alfaparf Milano Professional Semi Di Lino Beauty Genesis renovador com células estaminais vegetais de Argan, com a particular capacidade de se autorrenovarem continuamente, para cabelos sublimes, com um aspecto luminoso e saudável. Contém Urban Deference Pro, o novo princípio ativo capaz de proteger a fibra capilar contra os agentes poluidores. Semi di Lino linha de tratamento original para cabelos luminosos, está sendo renovada e aprimorada. Possui um complexo biotecnológico multifuncional, que oferece proteção avançada contra o estresse dos poluentes e cuida do seu cabelo dia a dia, para um resultado extraordinário! * RESULTADO: Multifuncional. * SUGESTÕES DE USO: 1.Distribua o produto diretamente no couro cabeludo, em cada parte do cabelo dividido; 2.Massageie com a ponta dos dedos; 3.Penteie como de costume; 4.Não enxágue. * OBSERVAÇÕES: Imagem Meramente Ilustrativa * ITENS INCLUSOS: 1 Alfaparf Milano Professional Semi Di Lino Beauty Genesis Caixa de Ampola para Brilho 12x13ml', 257.9, 190.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-22110-9ujwqd0ysikvc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F20865952805', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259706390', 'Pão de Queijo Recheado com Goiabada Daki', 'Pronto em minutos, para qualquer hora do dia, recheado com goiabada cremosa, a combinação mais famosa do Brasil! Experimente o nosso pão de queijo quentinho com goiabada cremosa e derretida, uma explosão de sabores em cada mordida. Ideal para um lanche rápido, café da manhã especial ou para acompanhar aquele cafezinho no fim da tarde. *Pão de queijo com casquinha crocante e miolo macio. *Recheio generoso de goiabada. *Fácil e rápido de preparar.', 14.49, 14.49, NULL, 'Food & Beverages > Fresh & Frozen Food > Frozen Processed Food', 'https://cf.shopee.com.br/file/sg-11134201-8258e-mqnektc0x1xf19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555116%2F58259706390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998670266', 'Blush Cremoso e em Pó Cereja - Duo Blush Cherry Paint Océane Edition 10,2g', 'O Duo Blush Edition Une As Versões Cremosa e em Pó em Um Só Produto. Isso Sim É o Que a Gente Chama de Beleza Smart! com Ele, Você Adiciona Cor às Maçãs do Rosto e Ainda Tem a Liberdade de Combinar As Texturas para Criar Efeitos Únicos, Cheios de Estilo e Personalidade. E Sabe o Que Diferencia Esse Produto Dos Outros Blushes Que Você Vê Por Aí? com Duo Blush, Sua Maquiagem Fica Mais Versátil e Você Consegue Criar Diversos Visuais com o Mesmo Produto. Quer Ver Só? - Aplicando Apenas o Blush em Pó, o Resultado É Um Visual Mais Delicado. - Se Preferir Usar Só o Blush Cremoso, a Maquiagem Ganha Um Acabamento Bem Natural, com Aspecto Viçoso e Hidratado. - e Quando Você Combina As Duas Versões, Rola Um Up Na Intensidade da Cor! E Por Falar em Cor, a Pigmentação Desse Blush 2 em 1 É Surpreendente e Tem Uma Fixação Super Duradoura. Ele Dá Aquele Belíssimo Toque de Cor para o Rosto e Você Não Vai Precisar Retocar com Frequência. e a Gente Ama Quando Praticidade e Beleza Andam Juntas, Não É Mesmo? A Cor Cherry Paint É Um Tom Cereja Vibrante com Acabamento Matte Na Versão em Pó. a Versão Cremosa, Por Sua Vez, Tem Um Efeito Natural Lindo. e Além Disso, a Fórmula do Produto É Vegana, Cruelty-Free e Faz Parte da Linha Océane Edition, Que Já É Super Conhecida Por Suas Makes Inovadoras. O Produto Está Disponível em 6 Cores, Incluindo a Cherry Paint. Seu Estojo Tem Fechamento com Imã, Ideal para Transportar No Nécessaire com Toda Segurança. Além Disso, Ele Vem com Espelho Embutido para Quem Tem o Hábito de Retocar Maquiagem Ao Longo do Dia. Gostou? Então Vem Conhecer Esta e Outras Opções de Blush Que Océane Tem em Seu Portfólio. Um Deles Vai Ser Seu Próximo Favorito de Make! Posso Usar Só Uma Das Texturas do Blush? Pode Sim! Se Você Curte Usar Apenas o Blush em Pó ou Prefere a Versão Cremosa, Tá Tudo Certo. Mas Que Tal Explorar Novas Combinações? Ao Sobrepor As Duas Texturas, Você Descobre Um Novo Universo de Pigmentação Ainda Mais Vibrante. com o Duo Blush Edition, Sua Make Pode Ser do Jeitinho Que Você Quiser. Qual Textura Vem Primeiro, a em Pó ou a Cremosa? Sua Maquiagem, Suas Regras! Mas Se Você Quiser Uma Dica Fácil para Dar Outro Acabamento para Sua Make, Aqui Vai: Comece Aplicando o Blush em Pó e Finalize com a Versão Cremosa Só No Alto Das Maçãs do Rosto. o Acabamento É Radiante e Natural e o Efeito Fica Simplesmente Incrível!', 139.9, 139.9, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-8259l-mr22nq81jhfw55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F22998670266', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19197685364', 'Gabinete Gamer Pichau Pouter 3 Lateral De Vidro Preto, PG-P03-BK', 'GABINETE GAMER PICHAU POUTER 3 LATERAL DE VIDRO PRETO Chegando para mudar o seu conceito em gabinetes, te apresentamos o Pichau Pouter 3 Black. Ele traz qualidade, estilo e versatilidade para seu setup. Sua gameplay vai ficar ainda melhor com o Pouter ao seu lado! DESIGN Possuindo um design futurista e robusto, este gabinete possui a lateral e a frontal de vidro temperado com encaixe magnético, permitindo a você exibir todo o setup do seu PC e tornando a limpeza muito mais prática. Ele já vem com três ventoinhas instaladas na parte frontal, além de um acabamento de alta qualidade. ESPAÇO O Pichau Pouter 3 Black tem formato E-ATX o que garante um excelente espaço interno, garantindo que você possa montar seu setup sem preocupação e sem bagunça com tudo que você precisa! MATERIAL Quer mais? Pois o Pouter 3 Black também conta com uma estrutura feita em aço SPCC de 0,6mm que será extremamente durável permitindo que ele te acompanhe por muito tempo e esteja ao seu lado em todas as suas vitórias! Informações adicionais: Marca: PICHAU Modelo: PG-P03-BK Formato: Mid-Tower Material: SPCC 0,6 mm Placa mãe suportada: ITX, Micro-ATX, ATX e E-ATX(Até 285 mm de largura) Entradas: - 2 x USB 3.0 - Áudio HD Painel frontal: ABS + Vidro Painel lateral: Vidro 3mm com dobradiça Baias: 3,5" + 2,5" (HDD e SSD): 2 + 3 ou 1 + 4 Slots de expansão: 7 Ventoinhas inclusas: Frente: 3 x 120 mm Ventoinhas suportadas: - Frente: 2 x 140 mm ou 3 x 120 mm - Superior: 2 x 140 mm ou 2 x 120 mm - Traseira: 1 x 120 mm - Tampa PSU: 2 x 120 mm Water cooler suportado: - Frente: 360/280/240 mm - Superior: 280/240 mm - Traseira: 120 mm Altura máxima do cooler do processador: 165 mm Comprimento máximo da placa de vídeo: 340 mm Radiador frontal + ventoinha (espessura): 49 mm Radiador superior + ventoinha (espessura): 58 mm Radiador Traseiro + ventoinha (espessura): 60 mm Sistemas de gerenciamento de cabos: 22 mm Fonte de alimentação suportado: ATX Conteúdo da embalagem: - Gabinete Gamer Pichau Pouter 3 - Guia de Instalação - Kit de parafusos para instalação Dimensões: - Largura: 210 mm - Altura: 396 mm - Comprimento: 490 mm Ventoinhas: - Dimensões: 120 x 120 x 25 mm - Rotação: 1200 ± 10% RPM - Comprimento dos cabos: 350 mm - Cor Moldura: Preta - Cor das pás: Pretas - Quantidade de pás: 7 - Tipo de rolamento: Sleeve - Fluxo de ar: 40,8 CFM - Pressão de ar: 0,82 mmH2O - Nível de Ruído: 23,6 dbA - Expectativa: 40000 horas - Consumo: 1,65W - Conectores: Molex Sobre a Pichau Informática Com mais de 18 anos de atuação no mercado nacional de tecnologia, a Pichau se destaca por seu compromisso com a inovação, qualidade e a satisfação do cliente. Referência em performance e confiabilidade, a empresa segue evoluindo para entregar produtos de excelência em diversas áreas, incluindo o esporte.', 599.99, 306.65, NULL, 'Computers & Accessories > Desktop & Laptop Components > PC Cases', 'https://cf.shopee.com.br/file/sg-11134201-7rd58-lvj3bj3sbzfz56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F627750190%2F19197685364', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094243195', 'Gabinete TGT T100, Preto, TGT-T100-BK', 'Gabinete TGT T100 Procurando um novo gabinete para deixar seu setup ainda mais incrível? Prepare-se para conhecer o TGT T100. Moderno e eficiente, ele é o upgrade que você estava esperando! DESIGN O TGT T100 combina detalhes minimalistas com um acabamento texturizado. Seu painel lateral conta com entradas de ventilação estratégicas, e seu painel frontal possui portas USB e entrada para fones de ouvido, garantindo fácil acesso para conexões rápidas! ESPAÇO Apesar do formato compacto, o gabinete TGT T100 oferece um interior bem distribuído para acomodar placas-mãe Micro-ATX/ITX, placas de vídeo de até 250mm, um HDD de 3,5” e um SSD de 2,5”! MATERIAL Construído com uma estrutura resistente de aço SPCC de 0,35mm, o T100 garante durabilidade e proteção para seus componentes. Seu painel lateral ventilado facilita a dissipação de calor, enquanto o acabamento frontal escovado adicionará um toque elegante ao seu setup! Marca: TGT Modelo: TGT-T100-BK Placa mãe suportada: Micro-ATX / ITX Entradas: - 2x USB 2.0 - Áudio Baias: - HDD 3.5": 1 - SSD 2.5": 1 Comprimento Máximo da VGA: 250 mm Ventoinhas: Não inclui ventoinhas Dimensões: - Largura: 165 mm - Altura: 265 mm - Comprimento: 340 mm Sobre a Pichau Informática Com mais de 18 anos de atuação no mercado nacional de tecnologia, a Pichau se destaca por seu compromisso com a inovação, qualidade e a satisfação do cliente. Referência em performance e confiabilidade, a empresa segue evoluindo para entregar produtos de excelência em diversas áreas, incluindo o esporte.', 296.44, 76.37, NULL, 'Computers & Accessories > Desktop & Laptop Components > PC Cases', 'https://cf.shopee.com.br/file/sg-11134201-7rdww-mc6emcvfrc1s54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F627750190%2F22094243195', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593180747', 'Cabeceira Cama Box Queen 160cm Orgânica Lanna W01 Bouclê Cinza - Lyam Decor', 'Nada é tão pessoal e íntimo como o nosso quarto, não é mesmo? Por isso, apostar em peças atemporais e com design minimalista é essencial para se criar um quarto de casal aconchegante e prazeroso. Pensando nisso, a Lyam Decor traz a Cabeceira Cama Box Queen 160cm Orgânica Lanna, com linhas curvas que remetem ao design orgânico, justamente para proporcionar um ambiente leve e harmonioso. Com a cabeceira casal Lanna esse espaço da casa terá a sensação de conforto e bem-estar para que o descanso seja proveitoso, além de dar aquele toque de elegância na decoração. Aproveite e adquira já a sua! Dimensões da Cabeceira (L x A x P) 160 x 120 x 8 cm Características da Cabeceira: Estrutura em madeira de reflorestamento de eucalipto. Revestimento em Bouclê na cor Cinza. Estofamento com espuma D-18 para maior conforto e maciez. Design curvo, estilo orgânico. Pés sapatas plásticas. Dimensões do Frame (L x A x P) 5,5 x 13,5 x 16,5 cm Altura do chão à base: 66 cm Características do Frame: Produzido em chapa de ferro de 1,5mm. Acabamento em esmalte PU na cor alumínio. Acessórios para fixação: 04 Parafusos cabeça chata auto atarraxantes 5,0x25mm e 04 arruelas 1/4. - Por se tratar de estofado as medidas podem ter uma pequena variação de até 3 cm. - A tonalidade do produto real poderá ter ligeira variação devido o lote de tecidos. - Indicado para uso residencial, sua limpeza deve ser feita com pano levemente umedecido em água limpa, sem esfregar, não utilizar produtos abrasivos, desengordurantes, álcool ou solvente. Observações importantes: - Produto para uso residencial em ambiente interno, não devendo ficar exposto diretamente ao sol, calor e umidade excessivos. - Pode haver alguma diferença de tonalidade entre a imagem e o produto real, por conta do tratamento de imagens e a calibração de cores do seu monitor. - As imagens são meramente ilustrativas, não acompanham objetos de decoração e eletrônicos. - Ao receber a mercadoria, o cliente deve verificar as condições da embalagem, caso haja alguma avaria não assine o comprovante de recebimento e entre em contato com nossa loja para orientações. - Montagem, desmontagem e outras instalações serão de responsabilidade do cliente. Não nos responsabilizamos, no ato da entrega, por subir escadas/elevadores ou pelo transporte por guincho em apartamentos. Eventuais despesas são de responsabilidade do comprador. - Confira as dimensões do produto e certifique-se de que passará normalmente por supostos elevadores, portas, escadas e/ou corredores de sua residência. - Para mais informações, acesse nossa Central de Atendimento.', 647.9, 570.16, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rdyj-lygtqjlpphei4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1107280577%2F23593180747', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18086482769', 'Pulseira Hipoalergênica De Aço Inoxidável Vnox De Dupla Camada Redonda Para Menina Feminina , Ouro 18K', 'O Vnox da joia fala com joias Aço inoxidável de grau 316L (Seguro na pele e nas crianças, hipoalergênico e sem desbotamento) Tamanho da caixa: 16 + 5 cm ✈️Processamento e envio de processamento de envio✈️ Tempo de chumbo: 1 A 3 dias Envio em cerca de 7 dias O dinheiro em dinheiro na entrega está disponível Faqs FAQS O mesmo se desvanece? (O Banhado a ouro é difícil de desbotar. Manterá em boas condições dentro de 1-3 anos se você se importa com isso. Antes de enviarmos, cada um de nosso produto passa por testes QC. Se você tiver algum problema de qualidade após o recebimento do pacote, não hesite em contactar-nos a qualquer momento.) Ocasião de usar? (Dialy Wear/party/presente/engajamento/aniversário/casamento é adequado,Deixe VNox jóias transmitir seu amor)', 29.88, 14.94, NULL, 'Fashion Accessories > Bracelets & Bangles', 'https://cf.shopee.com.br/file/sg-11134201-7rbkg-lodtax8954q2bd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F239158067%2F18086482769', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
