INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298473973', 'Anne Vale do Arco-íris | Ciranda Cultural', 'Os seis filhos de Anne e Gilbert já estão crescidos e perseguindo aventuras. Em uma delas descobrem o Vale do Arco-íris e frequentemente vão até lá para brincarem. Então, novas crianças chegam a Glen St. Mary: os travessos Meredith. Contrariando as expectativas uma amizade nasce entre as crianças, enquanto o viúvo John Meredith procura por uma esposa. Em um celeiro, está escondida Mary Vance, que conquista os pequenos Blythe e Meredith, que juntos no Vale do Arco-íris, tramam um plano para que a nova amiga não volte ao orfanato272 páginas23x16cm', 19.95, 15.96, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rfhc-m9mc9qgj46211a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23298473973', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
