INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260261915', 'Salgadinho de Batata Pringles sabor Creme e Cebola 37g', 'A Pringles® Sabor Creme e Cebola 37g traz a combinação clássica do sabor creme e cebola em um snack de batata com textura única e crocância característica de Pringles®. Conhecido em todo o mundo, este salgadinho de batata sabor creme e cebola oferece um sabor marcante e equilibrado em cada mordida. Agora em um novo tamanho prático de 37g, é perfeito para levar na mochila, bolsa ou para aproveitar em qualquer momento do dia. Ideal para lanche da tarde ou da noite, para dividir com amigos ou para acompanhar momentos de lazer. Os salgadinhos de batata Pringles® são reconhecidos pelo seu formato icônico e encaixe perfeito na língua, além da crocância que torna cada snack ainda mais saboroso. Uma opção prática de snack salgado crocante para quem gosta de Pringles®.', 5.99, 5.99, NULL, 'Food & Beverages > Snacks > Chips & Crisps', 'https://cf.shopee.com.br/file/sg-11134201-8258v-mqnelgirbklc9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554792%2F58260261915', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
