INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19702003500', 'Sabonete em Barra Protex Carvão Detox 85g', 'Sua fórmula que combina óleo de linhaça + carvão ativado, fortalece as defesas naturais da pele, criando um efeito detox de dentro para fora. Benefícios: Fórmula que combina óleo de linhaça + carvão ativado. Fortalece as defesas naturais da pele. Cria um efeito detox de dentro para fora. Elimina 99.9% das bactérias Naturalmente', 9.89, 9.89, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/333e305429d6159e387087840a0208cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F19702003500', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
