INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497012613', 'Lola Cosmetics Xapadinha Escudo Liso Ativado', 'Bálsamo Disciplinante com alta proteção térmica. Deixo instantaneamente os cabelos mais alinhados, macios e sem frizz. Proporciono efeito liso temporário e antifrizz mesmo em condições de alta umidade. Não possuo química de transformação e protejo dos danos das ferramentas térmicas.*Testes realizados em laboratório para controle do frizz e alinhamento dos fios. * RESULTADO: Disciplinante; Redução de Frizz * SUGESTÕES DE USO: 1. Aplique uma pequena quantidade nos fios limpos e úmidos. 2. Distribua uniformemente em todo comprimento e pontas. 3. Finalize com escova e secador, ou chapinha. * ITENS INCLUSOS: 1 Lola Cosmetics Xapadinha Escudo Liso Ativado', 39.9, 39.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rbmr-lmoxkv9qtfm370', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F23497012613', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
