INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11410401563', 'Par de Joelheira Elástica Preta KSN044 Kestal G', 'Anvisa : Registro isento conforme resolução RDC 27 de 06 de agosto de 2010 - anexo 1. Par de Joelheira Elástica Preta KSN044 Kestal A Joelheira Elástica Kestal protege a musculatura prevenindo lesões durante a prática de atividades físicas. Oferece compressão e ajuste, aumentado a segurança da articulação e mantendo a liberdade de movimentos. Composição: 80% poliéster e 20% elastodieno. Dimensões aproximadas: P - 27cm (circunferência) x 23cm (altura) M - 28cm (circunferência) x 23cm (altura) G - 30cm (circunferência) x 23cm (altura) ITENS INCLUSOS: 01 par da Joelheira Elástica Preta KSN044 Kestal Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 40.0, 40.0, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/92e598c6b1c29e43224caf2d6d341a30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F11410401563', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
