INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19555980999', 'Kit Elastico Extensor Musculação Super Mini Band Odin Fit', 'O kit com 3 Super Bands foi desenvolvido para você que gosta de se desafiar cada dia mais. Com ele você potencializa seus treinos de forma gradativa e fortalece a sua musculatura de acordo com o seu ritmo de treino. O Kit Mini Bands Odin Fit, também conhecido como “Látex Loops” é ideal para o desenvolvimento de resistência, reabilitação e força muscular, sendo um ótimo produto para exercícios funcionais. Prático de usar, e de transportar para qualquer lugar. Especificações do Super Band kit com 3 Intensidades: • 1 elástico (azul) medindo 13mm de largura - baixa intensidade (10 a 35lb - 4,5 a 16kg); • 1 elástico (roxo) medindo 21mm de largura - média intensidade (30 a 60lb - 14 a 27kg); • 1 elástico (Preto) medindo 32mm de largura - forte intensidade (40 a 80lb - 18 a 36kg); Cada elástico possui 208 cm de comprimento e espessura: 4,5mm; Especificações do kit Mini Bands: Dimensões aproximadas: 25cm x 5cm. As Mini Bands possuem 4 intensidades: 1 elástico (Mini band) amarelo - leve intensidade - Resistência: 2,3 a 4,5 kg; 1 elástico (Mini band) vermelho - Média intensidade - Resistência: 6,8 a 14 kg; 1 elástico (Mini band) azul - Forte intensidade - Resistência: 9 a 16 kg; 1 elástico (Mini band) preto - Extra-forte intensidade - Resistência: 14 a 20 kg; Contém: 1 (um) kit de Super Bands com 3 intensidades; 1 (um) kit de Mini Bands com 4 intensidades. Garantia de 3 meses contra defeitos de fabricação.', 240.0, 161.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Yoga & Pilates', 'https://cf.shopee.com.br/file/sg-11134201-22100-a8wakc3rwuiv7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F407831463%2F19555980999', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
