INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44410685764', 'DILA PUMP 318G LIMONADA ADAPTOGEN', 'Descubra a potência do Dila Pump Pré Treino da marca Adaptogen Science, um suporte ideal para elevar seu desempenho nos treinos. Este suplemento em pó, na saborosa variação de limonada, combina ingredientes premium como Beta Alanina, Arginina e Glicerol em pó, proporcionando uma experiência refrescante e eficaz. Com cada porção de 10g, você obtém 6.5g de aminoácidos essenciais que ajudam a melhorar a resistência e o foco, fundamentais para alcançar suas metas fitness. O Dila Pump não contém glúten e é livre de lactose, tornando-se uma excelente opção para quem tem restrições alimentares. Indicado para adultos a partir de 19 anos, é perfeito para atletas e entusiastas do esporte que buscam maximizar seus treinos. Com um pote de 318g, você terá várias porções prontas para impulsionar suas atividades físicas, sempre lembrando que é importante consultar um profissional de saúde antes de iniciar qualquer regime de suplementação.', 149.9, 149.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-7rdw7-mcqs1mlk3bae3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965164614%2F44410685764', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43627028630', 'Galão Tanque Transferência de Combustível 5L Com Bico (2081) - Lupus', 'A Unidade de Abastecimento Manual Para Transferência de Combustível 5L (2081) - Lupus, é indicada para transporte terrestre de produtos perigosos. Fabricado em Polietileno de alta densidade, fazendo com que tenha ainda mais resistência e durabilidade. Além disso possui trava de segurança e certificação UN 3H1/Y/250/20/CN/LD CCSCQ001-20. Características e Diferenciais: • Garante Maior Segurança e Sustentabilidade. • Tecnologia que reduz o desperdício de Combustível. • Garante maior pressão e maior vedação. • Ideal para funções do dia a dia. • Fabricado em Polietileno de Alta Densidade. Descrição do Produto: • Cor: Amarelo. • Uso Sugerido: Diesel. • Equipamento com válvula para dispersão de gases. • Bico com fechamento automático. • Bico de Abastecimento com Encaixe. • Tampa com Trava de Segurança. • Capacidade de 5 Litros. • Fabricado em HDPE. • Ponteiro: Ø 3/4". Referência: 2081. Cód. de Fábrica: 2081. Marca: Lupus.', 143.9, 143.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Others', 'https://cf.shopee.com.br/file/sg-11134201-822yg-mhw6gmrnjimgff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F43627028630', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
