INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14191439922', 'DISTRIBUIDOR DE IGNIÇÃO GM OPALA CARAVAN MOTOR 4CC', 'APLICAÇÃO: CHEVROLET Opala Caravan CARACTERÍSTICAS: Motor 4CC Com Ignição Eletrônica CÓDIGO ORIGINAL: 92300087050 7050 50017 93289518 REFERÊNCIA: AT0512 ANTES DA COMPRA, CERTIFIQUE-SE QUE ESSA PEÇA REALMENTE É PARA SEU VEÍCULO. * Produto Novo * Ótima Qualidade e Durabilidade * Todos os produtos da Venko Parts possuem garantia. * Todos os produtos acompanham Nota Fiscal emitida para o CPF/CNPJ informado na compra. * A instalação requer mão de obra especializada de sua preferência, não nos responsabilizamos por erros de instalação.', 299.9, 299.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8opg6ajd28h03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406154262%2F14191439922', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28841481002', 'Fundo Fotográfico Natal Cenário Natalino 3d Painel Em Tecido Sublimado para Fotos 1,20x1,70m', 'Todos os nossos Fundos Fotográficos Sublimados são confeccionados em tecido especial, com excelente acabamento e imagens nítidas que possibilitam fotos incríveis sem reflexos no resultado final. Por serem muito práticos, os fundos podem ser utilizados em estruturas como tripés (presos por garras) ou fixado em paredes e até mesmo placas de MDF com o auxílio de fita crepe ou dupla face (de formato largo, preferencialmente). Características: Tecido: Malha (estica e não amassa) Composição: 95% Poliéster + 5% elastano Gramatura: 140g m² Acabamento: Pode ser em overloque ou à laser, à depender da demanda. Ambos com acabamento perfeito que garantem sua durabilidade. ** Itens inclusos: 1 fundo fotográfico em tecido Malha ** Indicação de uso: Produção de fotos em estúdio fotográfico Informação complementar: As cores podem variar nas fotografias devido à qualidade da câmera fotográfica, ajustes/configurações da câmera, lente e iluminação do ambiente. Além disso, as configurações brilho e contraste do monitor ou celular onde a imagem está sendo visualizada, também podem dar a impressão das cores serem mais ou menos vivas, mais ou menos intensas. ** Todos os nossos produtos passam pelo processo de sublimação, sendo uma etapa onde passam por uma temperatura muito alta, podendo ter uma pequena variação em seu tamanho de até 5cm.** Nossos fundos fotográficos têm uma qualidade incomparável e é simplesmente incrível! Nosso tecido é maravilhoso, proporciona um toque suave e sem marcas de dobras, as cores são bem vivas e a nitidez da resolução incrível. Praticidade e economia de espaço, podem ser lavados, dobrados, guardados e é só esticar e arrasar nas fotografias. Possui acabamento impecável, não desbota e o caimento é perfeito! Uma combinação de qualidades especiais.', 78.9, 37.9, NULL, 'Cameras & Drones > Camera Accessories > Lighting & Studio Equipments', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfb3776u5s78c4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F776725570%2F28841481002', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
