INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792987693', 'Mesa Office Escrivaninha com Torre e Prateleiras Nt 2105 123,2cm Branco New Branco New', 'PRATELEIRAS EM ÂNGULO, ESTANTE INTEGRADA, AMPLO ESPAÇO DE USO, IDEAL PARA ESTUDO E HOME OFFICE.A Mesa Office NT 2105 da Notável Móveis é a escolha perfeita para quem busca funcionalidade e estilo no ambiente de trabalho ou estudo. Com uma estante integrada e prateleiras espaçosas, esta mesa oferece um amplo espaço de uso, proporcionando a organização ideal para o seu dia a dia. Suas prateleiras em ângulo permitem o armazenamento de livros, pastas e objetos de forma prática e acessível, enquanto seu design moderno se adapta perfeitamente a qualquer ambiente de home office. Desfrute de conforto e praticidade enquanto trabalha ou estuda com a Mesa Office NT 2105 da Notável Móveis. Peso (kg): 31.87 Garantia: 03 Meses Altura (cm): 136.3 Acabamento: Pintura UV Largura (cm): 123.2 Cor da Base: Branco Cor do Tampo: Branco Possui Vidro: Não Possui Portas: Não Possui Estante: Sim Possui Gavetas: Não Possui Rodízio: Não Suporta Até (kg): 40 Modelo Infantil: Não Possui Espelhos: Não Profundidade (cm): 56.8 Escala de Brilho: Brilhante Possui Gaveteiro: Não Ambiente Principal: Escritório Espessura do Tampo (mm): 22 Material Principal: MDP Necessita Montagem: Sim Possui Prateleiras: Sim Acabamento do Tampo: Pintura UV Possui Painel de TV: Não Sapatas Niveladoras: Sim Possui Porta Objetos: Sim Material da Estrutura: MDP Possui Caixa de Tomada: Não Formato da Escrivaninha: Retangular Possui Suporte para CPU: Não Complexidade da Montagem: Média: pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem Possui Borda Arredondada: Não Suporta Braço Articulado: Não Pés com Regulagem de Altura: Não Possui Suporte para Teclado: Não Possui Gaveta para Pasta Suspensa: Não Possui Acabamento na Parte de Trás: Sim Marca: Notável Móveis Cor Interna: Branco Cor: Branco New Cor do Produto: Branco New Cor Predominante: Branco Linha ou Coleção: 2024 Quantidade do Produto: 1', 327.26, 327.26, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-82591-mqjawhh93e9sae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F22792987693', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258882390', 'Cesto Plástico Redondo 105L com Tampa Eldorado Sortido', 'O Cesto Plástico Redondo 105L com Tampa Eldorado é ideal para armazenamento e organização de diversos materiais, oferecendo praticidade e resistência para uso doméstico e profissional. Fabricado em polietileno de alta densidade, o modelo possui estrutura reforçada e tampa rosqueável, que auxilia na proteção do conteúdo contra umidade, sujeira e insetos. Seu design com alças laterais facilita o transporte, sendo indicado para uso em ambientes internos e externos. CARACTERÍSTICAS PRINCIPAISCapacidade de 105 litros Estrutura em polietileno de alta densidade Tampa rosqueável com vedação Formato redondo Alças laterais para transporte Indicado para uso interno e externo Cores sortidas conforme disponibilidade FICHA TÉCNICAMarca: Eldorado Modelo: Cesto Redondo 105L com Tampa Tipo: Cesto plástico multiuso Material: Polietileno (PEAD) Capacidade: 105 litros Formato: Redondo Cor: Sortido Uso: Doméstico e profissional Origem: Nacional Conteúdo da embalagem: 1 unidade DIMENSÕES E PESOAltura: 77 cm Largura: 50 cm Comprimento: 50 cm Peso: 4,3 kg', 199.9, 116.9, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-81zwb-mn2wlpgepiis5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F58258882390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22128105358', 'Quebra Cabeça de 100 Peças Pixar - Toyster 8052', 'Quebra Cabeça Disney Pixar 100 Peças - Toyster As crianças vão adorar este quebra-cabeça de 100 peças da Disney Pixar com personagens de Toy Story, Procurando Nemo, Up Altas Aventuras, Monstros SA, Divertidamente e Wall-E! Elas vão se divertir entre tentativas e acertos de encaixar umas peças nas outras até formar uma imagem completa! Ficha técnica: Fabricante: Toyster Referência: 8052 Número de peças: 100 Tamanho da imagem montada: 34,5 x 22,6 cm Idade recomendada: A partir de 6 anos Dimensões da embalagem: 20 x 14 x 4 cm Certificado Inmetro: CE-BRI/IQB - 002320 NM 300/2002', 29.99, 29.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134201-23030-it5iusgzh4nvbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F947344701%2F22128105358', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10148435991', 'Kit 2 Sabão Líquido Brilhante Limpeza Total 3 Litros', 'Kit 2 Sabão Líquido Brilhante Limpeza Total 3l • Limpeza Profunda + Blindagem da cor • Brancos impecáveis • Limpa profundamente sem desbotar • Cuida das cores • Ajuda a prevenir sinais de desgaste • Cores mais vivas Brilhante Limpeza Combinação total os melhores resultados de limpeza com a proteção das cores dos tecidos. A nova fórmula contém o poder das enzimas, proporcionando uma limpeza profunda e evitando que a sujeira se deposita nas roupas. Além disso, o novo Brilhante Limpeza Total possui a tecnologia Brilho Ativo que evita o amarelamento das roupas brancas e mantém os coloridos muito mais vivos prevenindo os sinais de desgaste das suas peças preferidas. Suas roupas precisam como núcleos muito mais vivas e mais impactantes após cada lavagem. Entre limpeza profunda e blindagem da cor? Escolha os dois! Com Brilhante, você sempre leva mais. Brilhante quer se tornar um aliado nas tarefas diárias de seus consumidores e busca proporcionar maior praticidade através de produtos inovadores e fácil de usar, diminuindo o peso das tarefas e liberando o tempo para as demais atividades do dia a dia. Dicas: Produtos lava roupas não devem ser misturados com produtos a base de cloro. Tempo de molho ideal: Até 2 horas. Recomendado para a maioria dos tecidos e para roupas brancas e coloridas, mas em geral produtos lava roupas não são adequados para lavar lã, seda, couro e algodão cru. Seque suas roupas em local arejado. Para outros tipos de máquina, ajuste a dosagem de acordo com a recomendação do fabricante. - Kit Contém: 2 Sabão Líquido Brilhante Limpeza Total 3l cada - Compre Produtos Brilhante.', 71.38, 67.13, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-824ir-mehkfsst8xdue4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F10148435991', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15657039030', 'KIt Fralda Pampers Confort Sec Tamanho XXG com 120 Unidades', 'Conheça as fraldas Pampers Confort Sec com Extra Sec Pods, até duas vezes mais sequinha, fazendo com que o xixi desapareça! Extra Sec Pods: distribuem o xixi uniformemente, evitando que a fralda fique pendurada. Gel Mágico que absorve e retém a umidade no interior da fralda para noites mais sequinhas. Camada ultra absorvente que absorve rapidamente a umidade mantendo sequinha a pele do bebê. Barreira Anti Vazamento que se adaptam suavemente ao redor das pernas do seu bebê. Ajuste Flexível ajuste cômodo e flexível para dar uma proteção anti vazamentos todas as noites. Exclusiva loção protetora: ajuda a proteger a pele do seu bebê.', 344.49, 312.89, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/e8c3c2b11fa2c6fd07cf2a4fbbb1e842', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F15657039030', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13810530901', 'Kit 12 Desinfetantes Vim Multiuso Cloro Gel Lavanda 700ml', 'O Kit Contém: 12 Desinfetantes Vim Multiuso Cloro Gel Lavanda 700ml cada. - Perfume Prolongado; - Limpeza Ativa; - Higieniza o Vaso Sanitário; - Para desinfecção de todas as suas superfícies e retirada do limo; * Compre produtos Vim .', 220.19, 220.19, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/0843c790b7d6f82b206a6c24dec82b89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F13810530901', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21768573954', 'Hidratante Corporal Neutrogena Norwegian Intensivo com Fragrância 400ml', 'Hidratante Corporal NEUTROGENA® NORWEGIAN FORMULA® Intensivo com Fragrância 400ml O que é e para o que serve? Loção intensiva corporal hidratante com glicerina e aveia prebiótica, hidrata de forma imediata e prolongada, minimizando o aspecto esbranquiçado e descamação causados pelo ressecamento excessivo, deixando a pele macia, nutrida e protegida. Fórmula não oleosa e de rápida absorção, possui fragrância suave. Benefícios e diferenciais -Fórmula avançada com Aveia Prebiótica e Glicerina -Tecnologia TRIPLELIP™ Reparadora: forma uma camada protetora que repara a barreira cutânea -48 horas de hidratação: hidrata de forma imediata e prolongada -Desenvolvido e recomendado por dermatologistas -Fórmula não oleosa e de rápida absorção -Respeita o ph natural da pele -Hipoalergênico -Indicado para a hidratação de todos os tipos de peles, até as mais secas e extrassecas -Fragrância suave -Dermatologicamente testado -Para uso diário Como usar Espalhe a loção intensiva corporal hidratante por todo o corpo massageando suavemente até que seja absorvida pela pele. Dar especial atenção às áreas mais ressecadas como pernas, cotovelos e pés. Composição Aqua, Glycerin, Distearyldimonium Chloride, Petrolatum, Isopropyl Palmitate, Cetyl Alcohol, Dimethicone, Avena Sativa (oat) Kernel Flour, Benzyl Alcohol, Tocopheryl Acetate, Disodium Phosphate, Citric Acid. Precauções Apenas para uso externo. Não ingerir. Conservar fora do alcance das crianças, em local fresco e seco. Em caso de contato acidental com os olhos, enxaguar abundantemente. Havendo irritação ou alergia, suspenda o uso e procure por orientação médica.', 145.29, 145.29, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-23020-kyyag8wz6knvd4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F21768573954', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697586183', 'Kit 2 Papel Higiênico Neve Supreme Folha Tripla Leve 24un cada', 'O Kit contém: 2 pacotes de Papel Higiênico Neve Supreme Folha Tripla Leve com 24un cada. O Novo Neve® Supreme recebe a textura acolchoada 3D, trazendo uma nova experiência de conforto em Folha Tripla, com a maciez que só Neve® pode garantir. Todos os papeis higiênicos Neve® contém a tecnologia Dermacare, que mantém o PH natural da pele. Contém 1 Pacote com 24 rolos de 20m cada de Papel Higiênico Neve Marca: Neve Tipo de Folha: Triplabr Benefícios: Higiene e conforto para todos os dias Mantém o pH Natural da pele com a tecnologia Dermacare Toque macio e suave Textura Acolchoada 3D ATENÇÃO: *Conservar em local seco e fresco.', 134.19, 134.19, NULL, 'Home & Living > Home Care Supplies > Toilet Paper', 'https://cf.shopee.com.br/file/sg-11134201-7rd5a-lw65lxwoflbwb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F22697586183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12808504671', 'Hastes Flexíveis Cotonetes 75 Unidades', 'COTONETES® é feito com algodão 100% puro e possui hastes plásticas flexíveis. Por isso oferece toda a suavidade, conforto e absorção para o cuidado da sua pele. COTONETES® é indicado para a higiene pessoal de toda a família. Pode ser usado para limpar delicadamente a parte externa da orelha (desde que não atinja o canal do ouvido), as dobrinhas do pescoço e pernas do bebê, além de ser recomendado para aplicar e remover maquiagem.', 11.99, 11.99, NULL, 'Health > Personal Care > Hand Sanitizers', 'https://cf.shopee.com.br/file/82d8d2ac6021e1204d2eaead9bcf2270', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F12808504671', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57300404522', 'Inseticida Baygon Defense Mata Baratas e Formigas à Base de Água 500ml Borrifador', 'Seu medo não manda a barata embora. Não deixe ela nem chegar perto. Evite baratas com o novo Baygon Defense. Com fórmula à base de água, ele pode ser aplicado após a limpeza, criando uma barreira protetora de longa duração. Use nas frestas, ralos e perto do lixo. A aplicação direcionada ajuda a manter os ambientes livres de pragas.', 32.58, 32.58, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-825bc-mgfffrjpf11oce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F57300404522', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23201384627', 'Crescimento capilar SOS Bomba 300ml + Máscara 500g Salon Line', 'O Kit Crescimento Capilar Bomba conta com o Shampoo, o Condicionador e a Máscara de Hidratação S.O.S Bomba Original que, juntos, proporcionam fios mais saudáveis e fortes da raiz às pontas. Desenvolvidos com ativos inovadores, apresentam resultados comprovados em até 30 dias de uso. INDICAÇÕES Para quais tipos de cabelo? Para todos os tipos de cabelos. Qual a indicação? Cabelos fracos e quebradiços. Pode usar a partir de quantos anos? A partir de 12 anos. ATIVOS Quais os principais ativos? Whey protein: rico em aminoácidos essenciais que restauram a fibra capilar danificada. Vitamina A: fortalece os fios e auxilia no crescimento saudável. D-pantenol: hidrata e melhora a textura da fibra, combatendo as pontas duplas. Biotina: ajuda a prevenir a queda de cabelo, estimula o crescimento e fortalece os fios. Óleo de rícino: hidrata, combate a queda por quebra, fortalece e recupera profundamente os fios, além de auxiliar no crescimento saudável. MODO DE USO Qual a melhor forma de usar? Cada produto deve ser aplicado de um jeito: Shampoo S.O.S Bomba Original: aplique uniformemente o Shampoo S.O.S Bomba Original no cabelo molhado. Massageie a raiz até formar espuma. Enxágue. Condicionador S.O.S Bomba Original: depois de lavar o cabelo com o shampoo para crescimento de cabelo, aplique o Condicionador S.O.S Bomba Original no comprimento e nas pontas. Deixe agir entre 1 e 3 minutos e enxágue. Máscara de Hidratação S.O.S Bomba Original: com o cabelo molhado, aplique a Máscara Hidratante S.O.S Bomba Original mecha a mecha, enluvando os fios do comprimento às pontas. Deixe agir de 3 a 5 minutos e enxágue. CARACTERÍSTICAS É produto vegano? O Shampoo, o Condicionador e a Máscara de Hidratação S.O.S Bomba Original não são veganos. É liberado? O Shampoo, o Condicionador e a Máscara de Hidratação S.O.S Bomba Original não são liberados.', 70.0, 54.91, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-825ar-mfukr444gqvhf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F23201384627', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699251049', 'Lâmpada Automotiva Halógena I30 2009 2010 2011 2012 2013 2014 2015 2016 H27 12V 27W', 'Lâmpada Automotiva Halógena I30 2009 2010 2011 2012 2013 2014 2015 2016 H27 12V 27W As lâmpadas halógenas são uma excelente solução em iluminação automotiva, não provocam o ofuscamento e são de grande ajuda nos dias de chuva. Características: Produto novo de ótima qualidade; Fabricado com materiais de alta tecnologia; Especificações técnicas: Halógena; Potência 27watts; Encaixe da lâmpada: H27; Tensão de operação: 12V; Uso automotivo de fácil instalação. Compatível com os modelos: I30 2009 a 2016. Obs: valor anunciado referente a unidade. Garantia: 90 dias. Dica: Garante uma condução segura e tranquila em condições de iluminação adversas, ampliando seu campo de visão, aqui você encontra os melhores produtos com os melhores preços! Importante: NÃO somos responsáveis pela má instalação ou mau uso do produto, para evitar transtornos procure por um profissional especializado.', 13.44, 12.1, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lv0ugm1msc9zb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242764769%2F18699251049', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
