INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997993860', 'RELOGIO TEMPERATURA MOTOR 40-110 CABO 4 METROS 60MM MB', 'RELOGIO INDICADOR MARCADOR TEMPERATURA MOTOR MB WMW WILLTEC RELOGIO TEMPERATURA REDONDO ADAPTAÇÕES DIVERSAS CABO 4 METROS - 4 A 100 GRAUS - ARO CROMADO PRODUTO NOVO MARCA: WILLTEC CÓDIGO FABRICANTE: W01170C Descubra a excelência em peças e acessórios para veículos pesados na RIALAN LITORAL AUTO PEÇAS, a sua principal escolha para garantir qualidade e confiabilidade em cada compra. Com um vasto estoque de mais de 50 mil itens, nossa loja oferece uma extensa variedade de opções para atender às necessidades específicas do seu caminhão. Na RIALAN LITORAL AUTO PEÇAS, comprometemo-nos em fornecer produtos de alta qualidade, garantindo a segurança e a eficiência do seu veículo pesado. Nossa equipe especializada está pronta para ajudar a encontrar as peças certas, oferecendo conhecimento técnico e atendimento personalizado. Além disso, destacamos nossa dedicação à satisfação do cliente, proporcionando uma experiência de compra fácil e transparente. Entendemos a importância de manter seu caminhão em ótimo estado de funcionamento, e é por isso que nos esforçamos para ser a sua escolha número um quando se trata de peças e acessórios automotivos. Não comprometa a performance do seu veículo pesado. Escolha a RIALAN LITORAL AUTO PEÇAS e experimente a diferença que a qualidade faz. Seja para manutenção preventiva ou reparos emergenciais, estamos aqui para oferecer soluções confiáveis e duradouras. Sua satisfação é a nossa prioridade.', 228.0, 228.0, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9otz18cesqqd4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1408271217%2F20997993860', NULL