INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194635634', 'Fralda Huggies Supreme Care Giga M Com 172 Unidades', 'A Fralda Huggies Maxima Proteção é a companhia perfeita para você que busca máxima proteção enquanto seu bebê se movimenta. Com uma suavidade mais macia do que nunca, especialmente na parte traseira, proporciona conforto e absorção ideais, mantendo seu bebê sempre sequinho. Benefícios da Fralda Huggies Maxima Proteção Seus canais de absorção em formato de X distribuem melhor o xixi e dão mais conforto para o bebê, evitando assim quedas ou passos em falso em razão da fralda cheia. Essa tecnologia está disponível dos tamanhos M ao XXG e em todas as embalagens da linha Supreme Care formato aberto. Modo de uso da Fralda Huggies Maxima Proteção 1) Abra a fralda e as orelhas traseiras e levante as barreiras. Coloque o bebê e verifique se a fralda está cobrindo suas costas até a cintura; 2) Descole as orelhas e fixe-as sobre a faixa frontal da fralda, ajustando-as de acordo com o corpinho do bebê. Quando a orelha chefar ao ícone passante, mude para um tamanho maior; 3) Ajuste o elástico das pernas para garantir que não dobre por cima das barreiras internas; 4) Enrole a fralda e prenda-a, utilizando as orelhas ajustáveis. Descartar as fraldas utilizadas no lixo, nunca no vaso sanitário.', 246.24, 246.24, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-8261l-mlfa6b46ojr4fe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609010660%2F23194635634', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
