INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097741118', 'KIT CENTRAL MULTIMIDIA MP5 7 POL CÂMERA DE RÉ FIAT STRADA 2021 A 2023 FIORINO 2022', 'KIT MOLDURA + CENTRAL MULTIMIDIA + CÂMERA DE RÉ • Especificações Técnicas: - Tela 7 Polegadas capacitiva - Espelhamento Android e iOS - Bluetooth - Entrada para cabo P2 - Rádio FM - Tela Full Touch - Entrada SD Card - Entrada USB - Controle Remoto - Saída de Áudio 4×45 - Entrada para Câmera de Ré A nossa moldura Fiat Strada possui um padrão 2 din e tamanho de 7 polegadas. É fabricada em plástico ABS (acrilonitrila butadieno estireno), o que garante maior resistência a impactos e a temperaturas extremas. Esta moldura 2 din Fiat Strada está disponível na cor preta com acabamento fosco. É compatível com o Fiat Strada 2021 Até 2023 e Fiorino 2022 Peças: 01 Moldura, 02 Suportes e 01 Aro', 426.99, 426.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > GPS Navigators', 'https://cf.shopee.com.br/file/sg-11134201-82632-mkjzptt9m1vm1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379659661%2F22097741118', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
