INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23797506518', 'Luva de Guidão Moto Para e Frio e Chuva', '1-Par de Luva de Guidão Uma excelente opção custo beneficio para o inverno e dias de chuva. As luvas fixas de guidão oferecem praticidade e durabilidade, pois não precisam ser colocadas e retiradas a todo momento, podem ficar instaladas na moto por quanto tempo for necessário, não gerando a necessidade de se retirar a todo momento como acontece com as luvas de mão convencionais. - Material impermeável - Fácil instalação e remoção (se necessário). - Altamente resistente e confortável. -Temos a opção com proteção Térmica e Simples ambas impermeável na variação do Produto pode escolher o que preferir . Garante segurança no uso, pois não diminui os movimentos das mãos e garante total liberdade na pilotagem da moto. Os produtos garantem mais elasticidade e resistência às condições climáticas e de uso em geral. Protege suas mãos da chuva e do frio Alta qualidade Segurança, praticidade e durabilidade Não diminui os movimentos das mãos Uso Universal Para modelos Biz temos outro anúncio Marca: FortWest ATENÇÃO - PRODUTO NOVO A PRONTA ENTREGA - GARANTIA PARA DEFEITOS DE FABRICAÇÃO - SENDO CONSTATADO MAU USO A GARANTIA NÃO SERA VÁLIDA CONTEÚDO DA EMBALAGEM: - 1 Par de luva de guidão -Desde Já agradecemos a Preferencia -Shopping da Moto Bike', 79.9, 49.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Others', 'https://cf.shopee.com.br/file/br-11134207-820l6-mo6x9a5e77k079', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F531303273%2F23797506518', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498328252', 'KIT C/ 1 DRIVER D250-X 100W RMS + CORNETA JBL HL 11-25 TRIO E CAPACITOR', 'KIT C/ 1 DRIVER D250X 100W RMS + CORNETA JBL HL 11-25 TRIO E CAPACITOR DRIVER DE COMPRESSÃO COM DIAFRAGMA FENÓLICO DE BAIXO CUSTO E ALTA EFICIÊNCIA, IDEAL PARA COBRIR FAIXAS DE MÉDIAS FREQUÊNCIAS EM SISTEMAS DE PROPAGANDA VOLANTE E SONORIZAR PEQUENOS AMBIENTES. COM GARGANTA DE UMA POLEGADA, ACOPLA-SE DIRETAMENTE A TODAS AS CORNETAS SELENIUM COM FINAL 25. POSSUI CONJUNTO MAGNÉTICO E BOBINA MÓVEL ENROLADA EM FÔRMA DE KAPTON. ESPECIFICAÇÕES TÉCNICAS: - DIMENSÕES: 7,5 X 12 X 12 CM - IMPEDÂNCIA NOMINAL: 8 OHMS - POTÊNCIA RMS: 100W RMS - POTÊNCIA PMPO: 200W - RESPOSTA DE FREQUÊNCIA: 400 A 9.000 HZ CORNETA JBL SELENIUM ORIGINAL HL 11-25 TRIO VERDE NEON * VERDE NEON * HL 11-25 TRIO * COMPATÍVEL COM TODOS OS DRIVERS DE 1" POLEGADA COM FIXAÇÃO ROSCA * DISPERSÃO SONORA (H x V): 45"x 45" * FIXAÇÃO: ROSCA * MATERIAL: ALUMÍNIO * DIÂMETRO DA GARGANTA: 25 MM CAPACITOR BIPOLAR ELETROLITICO * 47uF 100v * Capacitor de driver CONTEÚDO DA EMBALAGEM: 01 - DRIVER D250X 01 - HL 11-25 TRIO NEON 01 - CAPACITOR DRIVER', 458.58, 412.73, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-7rd6j-m7idjukwlqr0fb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F432660571%2F22498328252', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10598112852', 'Kit 3 Fraldas Babysec Galinha Pintadinha Premium Tamanho XXG 24 unidades cada', 'O Kit contém: 3 pacotes de Fraldas Babysec Galinha Pintadinha Premium Tamanho XXG com 24 unidades cada. A fralda infantil Babysec Premium Galinha Pintadinha Até 12h de Proteção possui sistema Flexiprotect com orelha e cintura elástica, garantindo o melhor ajuste, conforto e proteção para o bebê. Desenvolvida com tecnologia de gel extra absorvente e barreiras impermeáveis, garantindo rápida absorção e mantendo a pele do bebê seca e segura por mais tempo. Tem cobertura com toque suave e decorada com vários desenhos divertidos.', 196.09, 196.09, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-22090-ehmbkkw7ozhve6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F10598112852', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
