INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093484879', 'Grampo tipo sargento aperto rápido 8" 203mm GA308 VONDER', 'Ideal para fixar peças em processos de colagem, fixação, montagem de móveis, carpintaria, entre outros. Não utilizar para sustentação. O Grampo Tipo Sargento de Aperto Rápido 8" (203 mm) GA308 da Vonder é uma ferramenta essencial para quem busca eficiência e praticidade em trabalhos de marcenaria e montagem. Com um design robusto e resistência superior, este grampo permite um ajuste rápido e preciso, garantindo firmeza e segurança durante o uso. Produzido em plástico rígido ABS de alta resistência. Possui sistema de aperto rápido, proporcionando praticidade na aplicação. Conteúdo da Embalagem: 1 Grampo tipo sargento. Detalhes técnicos: Modelo: GA 308 Capacidade máxima de abertura: 8" - 203 mm Material da haste do grampo: Metal Material do cabo do grampo: Plástico Massa aproximada (peso): 0,22 kg', 79.9, 36.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7reox-m1pv5wvazz2cab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F23093484879', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
