INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250222784', 'Coloração Koleston Deluxe Chocolate 67', 'Koleston Deluxe Chocolate 67 - Cobertura total dos fios Sem Amônia A Koleston Deluxe Sem Amônia oferece uma coloração prática e eficaz, garantindo cobertura total dos fios brancos. Com fórmula inspirada no cuidado da pele e tecnologia de purificação de metais, ela vai além da cor: trata intensamente os cabelos com Ácido Hialurônico e AHA, deixando-os hidratados, fortes e com brilho radiante desde a primeira aplicação. Sem amônia, proporciona uma coloração suave, sem comprometer o desempenho. O resultado são fios até 99% mais resistentes, com cor intensa e duradoura, perfeita para quem busca beleza e tratamento em um só produto. O kit conta ainda com o exclusivo Reativador de Cor, que realça a tonalidade cerca de 15 dias após o uso, mantendo os cabelos vibrantes e luminosos por muito mais tempo. Benefícios e Diferenciais: - Cobertura total dos fios brancos - Hidratação intensa e brilho duradouro - Fórmula sem amônia, suave e sem odor forte - Enriquecida com Ácido Hialurônico e AHA - Fios mais fortes e até 99% menos quebra - Cor vibrante e duradoura - Reativador de Cor que prolonga a tonalidade Itens inclusos na caixa: 1 Bisnaga de Coloração Creme 1 Frasco Aplicador com Emulsão Reveladora 1 Tratamento Gloss Intenso 1 Reativador de Cor (para uso 15 dias após) 1 Par de luvas Conheça a linha Koleston Deluxe, coloração que garante hidratação profunda, fios mais fortes, brilho intenso e cor vibrante de longa duração.', 65.56, 65.56, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-821gh-mgi7sklnxiq5c7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F58250222784', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
