INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57509969732', 'Smart TV Samsung Business 4K 50" - LH50BEFH4GGXZD', 'A Smart TV Samsung Business - LH50BEFH4GGXZD entrega imagens em altíssima definição, com cores vibrantes e contraste aprimorado graças à resolução UHD. Seu design moderno e fino se adapta perfeitamente a ambientes corporativos, como salas de reunião, recepções e áreas de exposição, proporcionando uma experiência visual envolvente e profissional. Projetada especialmente para uso comercial, esta TV conta com a plataforma Tizen, que oferece interface intuitiva e compatibilidade com diversos aplicativos. Além disso, seus recursos inteligentes facilitam o controle e o gerenciamento de conteúdo, otimizando apresentações e comunicações dentro da empresa. Com desempenho superior e ampla conectividade, a Samsung Business 4K de 50 polegadas é a escolha ideal para quem busca tecnologia, confiabilidade e qualidade de imagem excepcional. Seu painel robusto e brilho aprimorado garantem excelente visibilidade em diferentes condições de iluminação, tornando-a perfeita para uso corporativo contínuo. Samsung 50" 4K Crystal UHD – Modelo LH50BEFH4GGXZD • Tela Tamanho: 50" (125,7 cm) Resolução: 4K (3.840 × 2.160) Processador de Imagem: Crystal Processor 4K HDR10+: Suporte Aprimorador de contraste: Sim Tecnologia de movimento: Motion Xcelerator Upscaling: 4K Upscaling Modo Cineasta: Sim • Áudio Som de rastreamento de objetos: OTS Lite Q-Symphony: Sim Saída de som (RMS): 20 W Tipo de alto-falante: 2 canais Áudio Bluetooth: Sim • Smart TV / Serviços Sistema operacional: Tizen™ Bixby: Sim Assistente de voz: Alexa Navegador da Web: Sim Início da mídia: Sim • Recursos Smart Experiência multi-dispositivos: Mobile to TV, Sound Mirroring, Wireless TV On Espaço de trabalho: Sim • Conectividade HDMI: 3 USB: 1 (USB-A) Ethernet (LAN): 1 Entrada de RF: 1/1 (uso comum terrestre) / 0 satélite Canal de retorno de áudio HDMI: eARC/ARC Wi-Fi: Sim (Wi-Fi 5) Bluetooth: Sim (5.2) • Design Estilo: Slim Look Moldura: 3 Bezel-less Cor frontal: Preto Tipo de suporte: Flat Feet (cor preta) • Acessibilidade Baixa visão: Audio Description, Zoom Menu and Text, High Contrast, SeeColors, Color Inversion, Grayscale, Auto Picture Off Deficientes auditivos: Closed Caption, Multi-output Audio, Sign Language Zoom Deficientes motores: Slow Button Repeat, Remote Control App for All Guia de voz: Inglês (US), Português (BR), Espanhol (MX) • Energia Consumo: 125 W Dimensões e Peso Dimensões do conjunto (L x A x P): 1120,3 × 647 × 60 mm Dimensões da embalagem (L x A x P): 1248 × 760 × 154 mm Peso do conjunto: 9,1 kg Peso com embalagem: 12,4 kg • Outros Sensor ecológico: Sim Suporte para mini-montagem na parede: Sim EMC: Class B Segurança: 60065, 62368-1 Transmissão digital: ISDB-T Sintonizador analógico: Sim (Trinorma) App de TV comercial (Android/iOS): Sim', 3618.0, 3617.0, NULL, 'Home Appliances > TVs & Accessories > TVs', 'https://cf.shopee.com.br/file/br-11134207-820ld-mnvv3uctn4le1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1343318906%2F57509969732', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23899431401', 'Batata Frita Lisa Clássica Lays', 'A Batata Frita Lay''s Clássica é a escolha ideal para quem busca um snack prático e delicioso a qualquer hora! Crocante, saborosa e feita com ingredientes selecionados: batata, óleos vegetais e sal. * Perfeita para dividir com os amigos ou para um lanche rápido. * Não contém glúten.', 15.99, 13.09, NULL, 'Food & Beverages > Snacks > Chips & Crisps', 'https://cf.shopee.com.br/file/sg-11134201-82593-mqnelazdkemb21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554909%2F23899431401', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898312419', 'Sabonete em Barra Rexona Antibacterial Limpeza Profunda 6 Unidades 84g Cada', 'Os sabonetes em barra de Rexona possuem uma combinação exclusiva de ingredientes que, em conjunto, entregam benefícios de limpeza profunda e refrescância além de deixar sua pele suave. Nossa fórmula antibacteriana elimina até 99,9% das bactérias* proporcionando uma sensação revitalizante, de refrescância prolongada e limpeza profunda. O sabonete em barra Rexona Antibacteriano Limpeza profunda limpa sem ressecar a pele. Dermatologicamente testado, apresenta um pH adequado, promovendo uma limpeza eficaz sem ressecar ou remover a camada protetora da sua pele. Limpeza profunda, hidratação na medida certa com aromas florais de jasmim e lírio com notas cítricas. Todas as variantes de Rexona são exclusivamente formuladas para proporcionar uma sensação única de refrescância durante e após o banho, para você sentir suas energias recarregadas. Eles apresentam um toque suave no banho, pois contém glicerina na fórmula, um ingrediente hidratante para a pele. Os sabonetes em barra Rexona oferecem uma refrescância inigualável para o seu banho. Dentro ou fora de casa, Rexona sempre está presente para garantir que sua pele esteja livre de bactérias. *Com base em estudo realizado em laboratório independente. Bactérias testadas: Staphylococcus Aureus. Produto cosmético sem ação terapêutica. • O sabonete em barra Rexona Antibacteriano Limpeza profunda tem uma fórmula exclusiva, garantindo proteção eficaz e uma pele suave; • Desenvolvido com tecnologia antibacteriana, sua fórmula elimina até 99,9% das bactérias* higienizando sua pele e deixando-a livre de germes; • Com glicerina, muito conhecida como um ingrediente hidratante para a pele, proporcionando um toque suave no banho; • Combinação exclusiva de ingredientes que entregam benefícios de limpeza e refrescância, com pH adequado, sem ressecar ou remover a camada protetora de sua pele; • Esse sabonete em barra promove sensação de frescor prolongada com aromas florais de jasmim e lírio com notas cítricas; • Dermatologicamente testado, entrega uma limpeza profunda, hidratação e perfume na medida certa.', 27.72, 27.72, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7rd57-m770mpra3ci420', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23898312419', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
