INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22620181019', 'Pet Smack Hidrat System 20ml Hidratante para Cães Gatos Centagro', 'PRODUTO ORIGINAL COM NOTA FISCAL! - - - - - DESCRIÇÃO: Centagro PetPower hidratação para animais que necessitam de um tratamento de choque na pele e pelagem extremamente ressecadas. Ação imediata, resultados visíveis logo na primeira aplicação. Com uma concentração maior de ativos que outros produtos de ação hidratante, com elevado concentração de nutrientes específicos para ação conjunta na pele e pêlo do animal. - - - - - Modo de uso: Coloque a dose (20ml) no copo dosador Pet Smack ou outro similar e completar com água (80ml) até obter 100ml. Sobre a pelagem limpa e úmida; espalhar mecha a mecha ou vaporizar com borrifador, massageando pele e pelo. Não enxaguar. Secar e escovar o animal. Reaplicar a cada 15 dias. - - - - - Enviamos o seu pedido o quanto antes possível! Obrigado pela preferência.', 54.5, 27.26, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/br-11134207-820m5-mqc7ibw88uf6f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442964228%2F22620181019', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
