INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19399562850', 'Sofá 3 Lugares Retrátil Reclinável com USB Veludo 230cm Khalifa Wood Estofados', 'Sofá 3 Lugares Retrátil Reclinável com USB Veludo 230cm Khalifa Wood Estofados, é a escolha ideal para quem deseja decorar sua sala com elegância e conforto. Com um diferencial único, seu tecido de veludo oferece um toque extra de maciez. Além disso, o encosto removível facilita o transporte, permitindo que ele passe facilmente por portas, corredores estreitos e elevadores. Feito com materiais de alta qualidade, este sofá foi pensado para garantir o seu bem-estar e conforto. Características: Densidade D 26 Reclinável: catraca com 5 posições Retrátil: sistema corrediças metálicas Duplo molejo: molas espirais e molas ensacadas Percintas elásticas Madeira: Eucalipto e reflorestamento tratado Encosto: 100 silicone Almofada braça: 100 silicone Almofadas decorativas: 100 silicone Pillow top: 18m Rodizio: silicone Com entrada USB-C Dimensões: Altura: 120 cm Largura: 230 cm Profundidade: 160 cm Peso: 60,00 kg Garantia do fornecedor de 3 meses', 2499.9, 2499.9, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/sg-11134201-7rfic-m3b4xtrbgijra3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F19399562850', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58261163713', 'Prato suporte 6 pol lixadeira roto orbital Bosch AVE 150mm GEX150, GEX150AC, GEX150 turbo', 'Prato suporte 6 pol lixadeira roto orbital Bosch gex 150, gEx 150 ac, gex 150 turbo Descrição: - 100% novo e de alta qualidade - Feito de borracha de alta qualidade e durável, longa vida útil - É ideal para trabalhos de lixamentos; - Possui nível de dureza macio; - Ideal para profissionais de oficinas, marcenarias, carpintarias, entre outros; Especificações: Tamanho da almofada: 6 (148mm) Quantidade de orifícios: 6 Espessura: 15mm Máx. rpm: 12000 Pacote incluído: 1 x prato Suporte Modelos Compatíveis: LIXADEIRA ROTO ORBITAL BOSCH gex 150, gEx 150 ac, gex 150 turbo', 160.8, 160.8, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824g9-mptxhlbz4qvg2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1036817611%2F58261163713', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
