INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11165244605', 'Espelho Retrovisor Pro Tork Mini Articulado Original Titan 150 2009/15 Honda (Par)', 'Apresentamos a você os retrovisores PRO TORK Modelo Original Articulado Mini, a solução ideal para melhorar a segurança e a visibilidade durante suas viagens de moto. Com esses retrovisores de alta qualidade, você terá uma visão clara e ampla do tráfego ao seu redor, mantendo-se sempre ciente do que está acontecendo nas ruas e estradas. Marca: PRO TORK Especificações e Benefícios: - Nossos retrovisores são projetados com atenção aos detalhes, combinando funcionalidade e estilo em um só produto. Eles são fabricados com materiais duráveis e resistentes, garantindo sua longevidade e capacidade de suportar as condições variadas do ambiente. - Além da sua funcionalidade essencial, esses retrovisores também oferecem um design moderno e elegante que complementa a aparência da sua motocicleta. - Ao investir em nossos retrovisores de motocicletas, você estará priorizando sua segurança e a dos outros usuários da estrada. Com uma visão clara e ampla dos veículos ao seu redor, você poderá tomar decisões mais informadas e evitar possíveis acidentes. Não deixe de adquirir os retrovisores de motocicletas PRO TORK de qualidade superior para aprimorar sua experiência de pilotagem. Melhore a visibilidade, a segurança e o estilo da sua moto hoje mesmo! Aplicação: TITAN / FAN / START / CARGO 125 /150 / 160 2009 à 2017; CB 250 2015 à 2017. Atenção: Recomendamos que a montagem seja realizada por um profissional especializado. A Loja não se responsabiliza por montagens errôneas ou mal uso do produto.', 84.11, 44.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Side Mirrors', 'https://cf.shopee.com.br/file/8788539ff5b16f9d3698d87e29461476', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F11165244605', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42312340595', 'Par Friso Moldura Paralama Crv 2012 2013 2014 2015', 'Friso Moldura Paralama Crv 2012 2013 2014 2015 DESCRIÇÃO DO PRODUTO A moldura do paralama é uma peça fundamental nos veículos, tanto em termos estéticos quanto funcionais. Localizada ao redor da borda exterior do paralama, essa estrutura desempenha um papel importante na proteção contra danos e na adição de estilo ao design do veículo. Especificações: - Material em Plástico - Texturizado - Cor: Preto Compatível com os carros da linha: - Crv 2012 - Crv 2013 - Crv 2014 - Crv 2015 Especificação Técnica: • Peça Dianteira • Acompanha Presilhas de Fixação O QUE VEM NA EMBALAGEM Conteúdo da Embalagem: • 02 Molduras Dianteiras FINALIZAÇÃO A imagens representam o real estado de conservação dos produtos. Detalhes técnicos e funcionalidades podem ser obtidos no chat! Compare o produto anunciado com o seu modelo de referência. Postaremos a sua mercadoria dentro de algumas horas após a confirmação da compra Não esqueça! Tire todas as suas dúvidas conosco antes de comprar o seu produto. Auto Peças Nova Kennedy Agradece sua preferência!', 259.9, 259.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Fender Flares', 'https://cf.shopee.com.br/file/sg-11134201-7rdxz-mdausab2ieww1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F494312426%2F42312340595', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
